CREATE OR REPLACE FUNCTION dation_private.activity_actor(wid uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE headers jsonb=coalesce(nullif(current_setting('request.headers',true),''),'{}')::jsonb; uid uuid;
BEGIN
 IF headers->>'x-dation-workspace-id' IS NOT NULL AND headers->>'x-dation-workspace-id'<>wid::text THEN RAISE EXCEPTION 'Activity workspace mismatch' USING ERRCODE='42501'; END IF;
 uid=coalesce(nullif(current_setting('dation.actor_user_id',true),''),nullif(headers->>'x-dation-actor-id',''))::uuid;
 IF uid IS NOT NULL THEN PERFORM dation_private.data_actor(wid,uid,true); END IF;
 RETURN uid;
END; $function$

CREATE OR REPLACE FUNCTION dation_private.activity_capture()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE row_data jsonb=CASE WHEN TG_OP='DELETE' THEN to_jsonb(OLD) ELSE to_jsonb(NEW) END;
 wid uuid=(row_data->>'workspace_id')::uuid; uid uuid; kind text; object_kind text; cid uuid; nid text; meta jsonb='{}';
BEGIN
 uid=dation_private.activity_actor(wid);
 IF TG_TABLE_NAME='datasets' THEN
  object_kind='dataset';
  IF TG_OP='INSERT' THEN
   uid=coalesce(uid,(row_data->>'uploaded_by_user_id')::uuid); kind='dataset.uploaded';
  ELSIF TG_OP='DELETE' THEN kind='dataset.deleted';
  ELSIF OLD.archived_at IS NULL AND NEW.archived_at IS NOT NULL THEN kind='dataset.archived';
  ELSIF OLD.archived_at IS NOT NULL AND NEW.archived_at IS NULL THEN kind='dataset.restored';
  END IF;
  meta=jsonb_build_object('dataset_type',row_data->>'dataset_type','row_count',row_data->'row_count');
  IF kind IS NOT NULL THEN INSERT INTO audit_events(workspace_id,actor_user_id,event_type,object_type,object_id,metadata_json) VALUES(wid,uid,kind,object_kind,(row_data->>'id')::uuid,meta); END IF;
  IF TG_OP<>'DELETE' AND row_data->'profile_json'->'valid' IN('true'::jsonb,'false'::jsonb) AND
   (TG_OP='INSERT' OR OLD.profile_json IS DISTINCT FROM NEW.profile_json) THEN
   INSERT INTO audit_events(workspace_id,actor_user_id,event_type,object_type,object_id,metadata_json)
   VALUES(wid,uid,'dataset.validated','dataset',(row_data->>'id')::uuid,meta||jsonb_build_object('valid',row_data->'profile_json'->'valid'));
  END IF;
 ELSIF TG_TABLE_NAME='decision_cases' THEN
  object_kind='decision_case';cid=(row_data->>'id')::uuid;
  IF TG_OP='INSERT' THEN uid=coalesce(uid,(row_data->>'created_by_user_id')::uuid);kind='decision_case.created';
  ELSIF OLD.status<>'archived' AND NEW.status='archived' THEN kind='decision_case.archived';
  ELSIF OLD.status='archived' AND NEW.status<>'archived' THEN kind='decision_case.restored';
  ELSIF NEW.label IS DISTINCT FROM OLD.label THEN kind='decision_case.renamed'; END IF;
 ELSE
  object_kind='run';cid=(row_data->>'decision_case_id')::uuid;nid=row_data->>'node_id';meta=jsonb_build_object('source','system');
  IF TG_OP='INSERT' THEN
   kind=CASE NEW.status WHEN 'queued' THEN 'run.queued' WHEN 'running' THEN 'run.started' WHEN 'completed' THEN 'run.completed' WHEN 'error' THEN 'run.failed' ELSE NULL END;
   IF NEW.status='queued' THEN uid=coalesce(uid,(row_data->>'created_by_user_id')::uuid);meta=dation_private.execution_responsibility_snapshot(wid,cid,nid);ELSIF uid IS NOT NULL THEN meta='{}'; END IF;
  ELSIF NEW.status IS DISTINCT FROM OLD.status THEN
   kind=CASE NEW.status WHEN 'running' THEN 'run.started' WHEN 'completed' THEN 'run.completed' WHEN 'error' THEN 'run.failed' ELSE NULL END;
   -- Workers have no actor. A real user cancellation keeps its verified actor.
   IF uid IS NOT NULL THEN meta='{}'; END IF;
  END IF;
 END IF;
 IF TG_TABLE_NAME<>'datasets' AND kind IS NOT NULL THEN
  INSERT INTO audit_events(workspace_id,actor_user_id,event_type,object_type,object_id,decision_case_id,node_id,metadata_json)
  VALUES(wid,uid,kind,object_kind,(row_data->>'id')::uuid,cid,nid,meta);
  IF TG_TABLE_NAME='decision_runs' THEN
  IF kind='run.completed' AND nid IN('logistics_assignment','logistics_scheduling') AND NEW.approved_at IS NULL AND EXISTS(SELECT 1 FROM decision_cases WHERE id=cid AND workspace_id=wid AND status<>'archived') AND
   (nid='logistics_assignment' OR EXISTS(SELECT 1 FROM decision_runs WHERE id=NEW.upstream_run_id AND workspace_id=wid AND decision_case_id=cid AND node_id='logistics_assignment' AND approved_at IS NOT NULL AND superseded_at IS NULL)) THEN
   INSERT INTO audit_events(workspace_id,event_type,object_type,object_id,decision_case_id,node_id,metadata_json)
   VALUES(wid,'decision.submitted','run',NEW.id,cid,nid,jsonb_build_object('source','system','automatic',true));
  END IF;
 END IF;
 END IF;
 RETURN NULL;
END; $function$

CREATE OR REPLACE FUNCTION dation_private.activity_enrich()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE kind text=dation_private.activity_kind(NEW.event_type,NEW.metadata_json); candidate text;
BEGIN
 candidate=NEW.metadata_json->>'case_id';
 IF NEW.decision_case_id IS NULL AND candidate ~* '^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$' THEN NEW.decision_case_id=candidate::uuid; END IF;
 IF NEW.decision_case_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM decision_cases WHERE id=NEW.decision_case_id AND workspace_id=NEW.workspace_id) THEN RAISE EXCEPTION 'Activity case mismatch' USING ERRCODE='42501'; END IF;
 NEW.node_id=coalesce(NEW.node_id,NEW.metadata_json->>'node_id');
 IF NEW.object_type IS NULL THEN
  NEW.object_type=CASE WHEN kind LIKE 'workspace.%' THEN 'workspace' WHEN kind IN('member.invited','member.invitation_revoked') THEN 'invitation' WHEN kind LIKE 'member.%' THEN 'member' WHEN kind='decision.assigned' THEN 'decision_case' WHEN kind='decision.approved' THEN 'run' ELSE NULL END;
  candidate=coalesce(NEW.metadata_json->>'run_id',NEW.metadata_json->>'user_id',NEW.metadata_json->>'invitation_id',NEW.decision_case_id::text);
  IF NEW.object_type='workspace' THEN NEW.object_id=NEW.workspace_id;
  ELSIF kind='member.joined' THEN NEW.object_id=NEW.actor_user_id;
  ELSIF candidate ~* '^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$' THEN NEW.object_id=candidate::uuid; END IF;
 END IF;
 RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION dation_private.approve_decision_run_version(target_run_id uuid, target_case_id uuid, target_node_id text)
 RETURNS SETOF decision_runs
 LANGUAGE plpgsql
 SET search_path TO 'dation_private', 'public', 'pg_temp'
AS $function$
DECLARE target public.decision_runs%rowtype; source public.decision_runs%rowtype;
 approval_time timestamptz; member_role text; assigned uuid; next_assignment public.decision_assignments;
BEGIN
 -- Serialize permission/assignment changes with approval, before the case lock.
 PERFORM 1 FROM public.workspaces WHERE id=dation_private.workspace_id() FOR UPDATE;
 member_role=dation_private.team_actor(dation_private.workspace_id(),nullif(current_setting('dation.actor_user_id',true),'')::uuid);
 IF member_role='viewer' THEN RAISE EXCEPTION 'Writer required' USING ERRCODE='42501'; END IF;
 SELECT owner_user_id INTO assigned FROM public.decision_assignments
 WHERE workspace_id=dation_private.workspace_id() AND decision_case_id=target_case_id AND node_id=target_node_id;
 IF assigned IS NOT NULL AND assigned::text<>current_setting('dation.actor_user_id') AND member_role<>'admin' THEN
 RAISE EXCEPTION 'Decision Owner required' USING ERRCODE='42501'; END IF;
 -- Lock the shared case first, before any candidate. This also serializes parent/child approvals.
 PERFORM 1 FROM public.decision_cases WHERE id=target_case_id FOR UPDATE;
 SELECT * INTO target FROM public.decision_runs WHERE id=target_run_id FOR UPDATE;
 IF NOT FOUND OR target.status<>'completed' OR target.decision_case_id IS DISTINCT FROM target_case_id
    OR target.node_id IS DISTINCT FROM target_node_id OR NOT (
      target_node_id='logistics_assignment' AND target.schema_version='assignment_v1'
      OR target_node_id='logistics_scheduling' AND target.schema_version='scheduling_v1') THEN
   RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='La corrida no puede aprobarse para ese Decision Case';
 END IF;
 IF target.superseded_at IS NOT NULL THEN
   RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='Una aprobación anterior no puede reactivarse; ejecutá una nueva alternativa';
 END IF;
 IF target.upstream_run_id IS NOT NULL THEN
   SELECT * INTO source FROM public.decision_runs WHERE id=target.upstream_run_id;
   IF NOT FOUND OR source.decision_case_id IS DISTINCT FROM target_case_id
     OR source.status<>'completed' OR source.approved_at IS NULL OR source.superseded_at IS NOT NULL THEN
     RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='La corrida upstream ya no es la decisión aprobada vigente';
   END IF;
 END IF;
 IF EXISTS(SELECT 1 FROM public.decision_cases WHERE id=target_case_id AND status='archived') THEN
 RAISE EXCEPTION 'Restore the case before approving' USING ERRCODE='22023'; END IF;
 IF target.approved_at IS NOT NULL THEN
   RETURN NEXT target; RETURN; -- A retry preserves actor/time and emits no second event.
 END IF;

 PERFORM dation_private.require_workflow_responsibility(dation_private.workspace_id(),target_case_id,target_node_id,'approve');
 -- Date the approval after acquiring the case lock, not when the waiting request began.
 approval_time := clock_timestamp();
 INSERT INTO public.decision_approval_events(run_id,case_id,node_id,action,actor,actor_user_id,occurred_at,replacement_run_id)
   SELECT id,target_case_id,target_node_id,'superseded',('user:'||current_setting('dation.actor_user_id')),current_setting('dation.actor_user_id')::uuid,approval_time,target_run_id
   FROM public.decision_runs WHERE decision_case_id=target_case_id AND node_id=target_node_id
     AND approved_at IS NOT NULL AND superseded_at IS NULL;
 UPDATE public.decision_runs SET superseded_at=approval_time,superseded_by_run_id=target_run_id
   WHERE decision_case_id=target_case_id AND node_id=target_node_id AND id<>target_run_id
     AND approved_at IS NOT NULL AND superseded_at IS NULL;
 UPDATE public.decision_runs SET approved_at=approval_time,approved_by=('user:'||current_setting('dation.actor_user_id')),approved_by_user_id=current_setting('dation.actor_user_id')::uuid,
   configuration_json=jsonb_set(configuration_json,'{decision_case}',
     coalesce(configuration_json->'decision_case','{}'::jsonb)||jsonb_build_object(
       'case_id',target_case_id::text,'node_id',target_node_id,'status','approved','approved_at',approval_time)),
   result_json=jsonb_set(result_json,'{decision_case}',
     coalesce(result_json->'decision_case','{}'::jsonb)||jsonb_build_object(
       'case_id',target_case_id::text,'node_id',target_node_id,'status','approved','approved_at',approval_time))
   WHERE id=target_run_id;
 INSERT INTO public.decision_approval_events(run_id,case_id,node_id,action,actor,actor_user_id,occurred_at)
   VALUES(target_run_id,target_case_id,target_node_id,'approved',('user:'||current_setting('dation.actor_user_id')),current_setting('dation.actor_user_id')::uuid,approval_time);
 SELECT * INTO next_assignment FROM public.decision_assignments WHERE decision_case_id=target_case_id AND node_id='logistics_scheduling';
 INSERT INTO public.audit_events(workspace_id,actor_user_id,event_type,metadata_json)
 VALUES(dation_private.workspace_id(),current_setting('dation.actor_user_id')::uuid,'decision.approved',
 jsonb_build_object('case_id',target_case_id,'node_id',target_node_id,'run_id',target_run_id,
 'admin_override',member_role='admin' AND assigned IS NOT NULL AND assigned::text<>current_setting('dation.actor_user_id'),
 'assigned_decision_owner_user_id',assigned,'next_node_id',CASE WHEN target_node_id='logistics_assignment' THEN 'logistics_scheduling' ELSE NULL END,
 'next_owner_user_id',CASE WHEN target_node_id='logistics_assignment' THEN next_assignment.owner_user_id ELSE NULL END,
 'next_approver_user_id',CASE WHEN target_node_id='logistics_assignment' THEN next_assignment.approver_user_id ELSE NULL END));
 RETURN QUERY SELECT * FROM public.decision_runs WHERE id=target_run_id;
END;
$function$

CREATE OR REPLACE FUNCTION dation_private.assert_owned(relation_name text, object_id uuid, tenant_id uuid, allow_missing boolean DEFAULT false)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE key_name text; owned boolean; present boolean;
BEGIN
 IF object_id IS NULL THEN RETURN; END IF;
 IF relation_name NOT IN('datasets','decision_cases','decision_runs','decision_chat_turns','decision_explanations','decision_comparative_analyses') THEN
  RAISE EXCEPTION 'Unregistered object type';
 END IF;
 key_name=CASE WHEN relation_name='decision_chat_turns' THEN 'turn_id' ELSE 'id' END;
 EXECUTE format('SELECT EXISTS(SELECT 1 FROM public.%I WHERE %I=$1 AND workspace_id=$2), EXISTS(SELECT 1 FROM public.%I WHERE %I=$1)',
  relation_name,key_name,relation_name,key_name) INTO owned,present USING object_id,tenant_id;
 IF NOT owned AND (present OR NOT allow_missing) THEN RAISE EXCEPTION 'Resource not found' USING ERRCODE='P0002'; END IF;
END; $function$

CREATE OR REPLACE FUNCTION dation_private.cancel_dispatch_job(target_run_id uuid)
 RETURNS SETOF decision_runs
 LANGUAGE plpgsql
 SET search_path TO 'dation_private', 'public', 'pg_temp'
AS $function$
begin
    perform 1 from public.dispatch_run_jobs where run_id=target_run_id for update;
    if not found then return; end if;
    update public.dispatch_run_jobs set state='error', lease_token=null, lease_expires_at=null
    where run_id=target_run_id and state in ('queued','running');
    if found then
        update public.decision_runs set status='error',finished_at=now(),
          error_message='La ejecución fue cancelada.',
          progress_json=jsonb_build_object('stage','cancelled')
        where id=target_run_id and status in ('queued','running');
    end if;
    return query select * from public.decision_runs where id=target_run_id;
end;
$function$

CREATE OR REPLACE FUNCTION dation_private.center_bundle(c decision_cases)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE summaries jsonb; a jsonb; s jsonb; n jsonb; latest jsonb; pending boolean=false; reviewing boolean=false; finished boolean; life text;
BEGIN
 summaries=dation_private.decision_case_history(c.id,NULL,0,0)->'summaries';
 a=summaries->'logistics_assignment'->'approved';s=summaries->'logistics_scheduling'->'approved';
 FOR n IN SELECT value FROM jsonb_each(summaries-'logistics_final_assignment') LOOP
  latest=n->'latest';
  IF latest->>'id' IS NOT NULL AND latest->>'approved_at' IS NULL AND latest->>'superseded_at' IS NULL THEN
   pending=true;
   IF latest->>'status'='completed' AND (latest->>'node_id'='logistics_assignment' OR latest->>'upstream_run_id'=a->>'id') THEN reviewing=true; END IF;
  END IF;
 END LOOP;
 finished=coalesce(a->>'id' IS NOT NULL AND s->>'id' IS NOT NULL AND s->>'upstream_run_id'=a->>'id' AND NOT pending,false);
 life=CASE WHEN c.status='archived' THEN 'archived' WHEN finished THEN 'completed' ELSE 'active' END;
 RETURN jsonb_build_object('case',to_jsonb(c)-'state_json','state_json',c.state_json,'summaries',summaries,
  'is_demo',EXISTS(SELECT 1 FROM datasets d WHERE d.workspace_id=c.workspace_id AND d.id IN(c.orders_dataset_id,c.fleet_dataset_id) AND d.is_sample),'status',life,'in_review',life='active' AND reviewing,'created_by',dation_private.center_person(c.workspace_id,c.created_by_user_id));
END; $function$

CREATE OR REPLACE FUNCTION dation_private.center_provenance()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE actor uuid;
BEGIN
 IF TG_OP='UPDATE' AND NEW.created_by_user_id IS DISTINCT FROM OLD.created_by_user_id THEN
  RAISE EXCEPTION 'Creator is immutable' USING ERRCODE='22023'; END IF;
 IF TG_OP='INSERT' THEN
  actor=nullif(current_setting('dation.actor_user_id',true),'')::uuid;
  IF actor IS NOT NULL THEN NEW.created_by_user_id=actor; END IF;
  IF NEW.created_by_user_id IS NOT NULL THEN
   PERFORM dation_private.data_actor(NEW.workspace_id,NEW.created_by_user_id,true);
  END IF;
 END IF;
 RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION dation_private.check_json_references(value jsonb, tenant_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE item record; relation_name text;
BEGIN
 IF jsonb_typeof(value)='object' THEN
  FOR item IN SELECT * FROM jsonb_each(value) LOOP
   relation_name=CASE WHEN item.key IN('dataset_id','orders_dataset_id','fleet_dataset_id','parent_dataset_id','orders_id','fleet_id') THEN 'datasets'
    WHEN item.key IN('run_id','latest_run_id','approved_run_id','upstream_run_id','source_run_id','source_assignment_run_id','base_run_id','superseded_by_run_id') THEN 'decision_runs'
    WHEN item.key IN('case_id','decision_case_id') THEN 'decision_cases'
    WHEN item.key IN('analysis_id','evidence_analysis_id','comparative_analysis_id') THEN 'decision_comparative_analyses' ELSE NULL END;
   IF item.key='stale_predecessor' AND jsonb_typeof(item.value)='object' THEN
    PERFORM dation_private.assert_owned('decision_cases',(item.value->>'id')::uuid,tenant_id);
   END IF;
   IF relation_name IS NOT NULL AND item.value<>'null'::jsonb THEN
    PERFORM dation_private.assert_owned(relation_name,(item.value#>>'{}')::uuid,tenant_id);
   ELSIF jsonb_typeof(item.value) IN('array','object') THEN
    PERFORM dation_private.check_json_references(item.value,tenant_id);
   END IF;
  END LOOP;
 ELSIF jsonb_typeof(value)='array' THEN
  FOR item IN SELECT v FROM jsonb_array_elements(value) v LOOP
   PERFORM dation_private.check_json_references(item.v,tenant_id);
  END LOOP;
 END IF;
END; $function$

CREATE OR REPLACE FUNCTION dation_private.dataset_referenced(wid uuid, did uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE relation_name text; used boolean;
BEGIN
 IF EXISTS(SELECT 1 FROM dation_private.ultimate_input_objects WHERE workspace_id=wid AND dataset_id=did) THEN RETURN true; END IF;
 IF EXISTS(SELECT 1 FROM public.case_data_pack_entries WHERE workspace_id=wid AND dataset_id=did) THEN RETURN true; END IF;
 -- Conservative: include JSON evidence and indirect/version references, even in
 -- archived cases and terminal runs. This rare destructive action may scan.
 FOR relation_name IN SELECT unnest(ARRAY['datasets','decision_cases','decision_runs','dispatch_run_jobs',
 'decision_case_reconciliations','decision_approval_events','decision_comparative_analyses',
 'decision_explanations','decision_messages','decision_chat_turns','decision_interpretation_sources']) LOOP
  EXECUTE format('SELECT EXISTS(SELECT 1 FROM public.%I t WHERE workspace_id=$1 %s AND jsonb_path_exists(to_jsonb(t),''$.** ? (@ == $id)'',jsonb_build_object(''id'',$2::text)))',
   relation_name,CASE WHEN relation_name='datasets' THEN 'AND id<>$2' ELSE '' END) INTO used USING wid,did;
  IF used THEN RETURN true; END IF;
 END LOOP;
 RETURN false;
END; $function$

CREATE OR REPLACE FUNCTION dation_private.enqueue_comparative_analysis(target_base_id uuid, job_request jsonb, existing_result jsonb DEFAULT NULL::jsonb, retry_failed boolean DEFAULT false)
 RETURNS SETOF decision_comparative_analyses
 LANGUAGE plpgsql
 SET search_path TO 'dation_private', 'public', 'pg_temp'
AS $function$
DECLARE base decision_runs; current decision_comparative_analyses; fingerprint text;
BEGIN
 PERFORM pg_advisory_xact_lock(701013);
 SELECT * INTO base FROM decision_runs WHERE id=target_base_id FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Base run not found' USING ERRCODE='P0002'; END IF;
 IF base.status<>'completed' OR base.schema_version<>'assignment_v1' THEN
  RAISE EXCEPTION 'Completed Assignment required' USING ERRCODE='22023';
 END IF;
 fingerprint=coalesce(base.result_fingerprint,base.result_json->>'result_fingerprint');
 IF fingerprint IS NULL OR job_request->>'base_run_id' IS DISTINCT FROM target_base_id::text OR
    job_request->>'engine_name' IS DISTINCT FROM base.engine_name OR
    job_request->>'engine_version' IS DISTINCT FROM base.engine_version OR
    job_request->>'schema_version' IS DISTINCT FROM base.schema_version OR
    job_request->'configuration' IS DISTINCT FROM ((base.result_json->'configuration')-'options') OR
    job_request->'options' IS DISTINCT FROM ((base.result_json->'configuration'->'options')||'{"analysis_depth":"comparative"}'::jsonb) OR
    (existing_result IS NOT NULL AND existing_result IS DISTINCT FROM base.result_json) THEN
  RAISE EXCEPTION 'Comparative intention does not match persisted base' USING ERRCODE='22023';
 END IF;
 SELECT * INTO current FROM decision_comparative_analyses WHERE base_run_id=target_base_id FOR UPDATE;
 IF FOUND AND (current.status<>'error' OR NOT retry_failed) THEN
  RETURN NEXT current; RETURN;
 END IF;
 IF existing_result IS NULL AND (SELECT count(*) FROM decision_comparative_analyses WHERE status IN('queued','running'))>=16 THEN
  RAISE EXCEPTION 'Comparative queue full' USING ERRCODE='53300';
 END IF;
 IF current.id IS NOT NULL THEN
  UPDATE decision_comparative_analyses SET status='queued',generation=generation+1,attempts=0,
   lease_token=NULL,lease_expires_at=NULL,heartbeat_at=NULL,request_json=job_request,
   available_at=clock_timestamp(),deadline_at=clock_timestamp()+interval '30 minutes',
   started_at=NULL,finished_at=NULL,error_message=NULL,result_json=NULL,result_fingerprint=NULL,duration_ms=NULL,
   progress_json='{"stage":"queued"}' WHERE id=current.id;
 ELSE
  INSERT INTO decision_comparative_analyses(base_run_id,base_result_fingerprint,source_mode,status,request_json,
   result_json,result_fingerprint,finished_at,progress_json,duration_ms)
  VALUES(target_base_id,fingerprint,CASE WHEN existing_result IS NULL THEN 'computed' ELSE 'existing' END,
   CASE WHEN existing_result IS NULL THEN 'queued' ELSE 'completed' END,job_request,
   existing_result,CASE WHEN existing_result IS NULL THEN NULL ELSE fingerprint END,
   CASE WHEN existing_result IS NULL THEN NULL ELSE clock_timestamp() END,
   CASE WHEN existing_result IS NULL THEN '{"stage":"queued"}'::jsonb ELSE '{"stage":"completed"}'::jsonb END,
   CASE WHEN existing_result IS NULL THEN NULL ELSE 0 END);
 END IF;
 RETURN QUERY SELECT * FROM decision_comparative_analyses WHERE base_run_id=target_base_id;
END; $function$

CREATE OR REPLACE FUNCTION dation_private.enqueue_dispatch_run(run_payload jsonb, job_request jsonb, intent_fingerprint text, queue_limit integer DEFAULT 32)
 RETURNS SETOF decision_runs
 LANGUAGE plpgsql
 SET search_path TO 'dation_private', 'public', 'pg_temp'
AS $function$
declare
    existing_job public.dispatch_run_jobs%rowtype;
    target_id uuid := (run_payload ->> 'id')::uuid;
begin
    perform 1 from public.workspaces where id=dation_private.workspace_id() for update;
    -- Serialize admission, but never calculation. Replays do not consume capacity.
    perform pg_advisory_xact_lock(701003);
    select * into existing_job from public.dispatch_run_jobs where run_id = target_id;
    if found then
        if existing_job.request_fingerprint is distinct from intent_fingerprint then
            raise exception using errcode = '22023', message = 'run_id ya pertenece a otra intención';
        end if;
        return query select * from public.decision_runs where id = target_id;
        return;
    end if;
    if exists(select 1 from public.decision_runs where id = target_id) then
        raise exception using errcode = '22023', message = 'run_id ya existe';
    end if;

    if (run_payload->>'decision_case_id') is not null then
      perform dation_private.require_workflow_responsibility(dation_private.workspace_id(),
        (run_payload->>'decision_case_id')::uuid,run_payload->>'node_id','execute');
    end if;
    if (select count(*) from public.dispatch_run_jobs where state in ('queued','running'))
       >= greatest(1, least(queue_limit, 256)) then
        raise exception using errcode = '53300', message = 'La cola de ejecución está llena';
    end if;
    insert into public.decision_runs(
        id, created_at, dataset_id, orders_dataset_id, fleet_dataset_id, schema_version,
        engine_name, engine_version, configuration_json, decision_case_id, node_id,
        upstream_run_id, status, progress_json
    ) values (
        target_id, clock_timestamp(), (run_payload ->> 'dataset_id')::uuid,
        (run_payload ->> 'orders_dataset_id')::uuid, (run_payload ->> 'fleet_dataset_id')::uuid,
        run_payload ->> 'schema_version', run_payload ->> 'engine_name', run_payload ->> 'engine_version',
        run_payload -> 'configuration_json', (run_payload ->> 'decision_case_id')::uuid,
        run_payload ->> 'node_id', (run_payload ->> 'upstream_run_id')::uuid,
        'queued', jsonb_build_object('stage','queued')
    );
    insert into public.dispatch_run_jobs(run_id, request_json, request_fingerprint)
    values (target_id, job_request, intent_fingerprint);
    return query select * from public.decision_runs where id = target_id;
end;
$function$

CREATE OR REPLACE FUNCTION dation_private.finish_comparative_analysis(target_analysis_id uuid, worker_token uuid, terminal_values jsonb)
 RETURNS SETOF decision_comparative_analyses
 LANGUAGE plpgsql
 SET search_path TO 'dation_private', 'public', 'pg_temp'
AS $function$
DECLARE target decision_comparative_analyses; base decision_runs; outcome text=terminal_values->>'status';
BEGIN
 IF outcome IS NULL OR outcome NOT IN('completed','error') THEN RAISE EXCEPTION 'Invalid outcome'; END IF;
 SELECT * INTO target FROM decision_comparative_analyses WHERE id=target_analysis_id FOR UPDATE;
 IF NOT FOUND OR target.status<>'running' OR target.lease_token IS DISTINCT FROM worker_token OR
  target.lease_expires_at<=clock_timestamp() OR target.deadline_at<=clock_timestamp() THEN RETURN; END IF;
 SELECT * INTO STRICT base FROM decision_runs WHERE id=target.base_run_id;
 IF outcome='completed' AND (
  jsonb_typeof(terminal_values->'result_json') IS DISTINCT FROM 'object' OR
  terminal_values->'result_json'->'scenarios'->'selected' IS DISTINCT FROM base.result_json->'scenarios'->'selected' OR
  (terminal_values->'result_json'->'configuration')-'options' IS DISTINCT FROM (base.result_json->'configuration')-'options' OR
  terminal_values->'result_json'->'configuration'->'options' IS DISTINCT FROM target.request_json->'options' OR
  terminal_values->'result_json'->>'schema_version' IS DISTINCT FROM base.schema_version OR
  terminal_values->'result_json'->'inputs' IS DISTINCT FROM base.result_json->'inputs' OR
  terminal_values->>'result_fingerprint' IS NULL) THEN
  RAISE EXCEPTION 'Comparative must preserve the original decision' USING ERRCODE='22023';
 END IF;
 UPDATE decision_comparative_analyses SET status=outcome,finished_at=clock_timestamp(),
  result_json=terminal_values->'result_json',result_fingerprint=terminal_values->>'result_fingerprint',
  duration_ms=(terminal_values->>'duration_ms')::bigint,error_message=left(terminal_values->>'error_message',1500),
  progress_json=jsonb_build_object('stage',outcome),lease_token=NULL,lease_expires_at=NULL WHERE id=target_analysis_id;
 RETURN QUERY SELECT * FROM decision_comparative_analyses WHERE id=target_analysis_id;
END; $function$

CREATE OR REPLACE FUNCTION dation_private.finish_dispatch_job(target_run_id uuid, worker_token uuid, terminal_values jsonb)
 RETURNS SETOF decision_runs
 LANGUAGE plpgsql
 SET search_path TO 'dation_private', 'public', 'pg_temp'
AS $function$
declare target public.dispatch_run_jobs%rowtype; outcome text := terminal_values ->> 'status';
begin
    if outcome not in ('completed','error') then raise exception 'Estado terminal inválido'; end if;
    select * into target from public.dispatch_run_jobs where run_id=target_run_id for update;
    if not found or target.state <> 'running' or target.lease_token is distinct from worker_token
       or target.lease_expires_at <= now() or target.deadline_at <= now() then return; end if;
    if outcome='completed' and (terminal_values -> 'result_json' is null
       or jsonb_typeof(terminal_values -> 'result_json') <> 'object') then
        raise exception 'Falta el resultado completado';
    end if;
    update public.decision_runs set status=outcome, finished_at=now(),
        duration_ms=(terminal_values ->> 'duration_ms')::integer,
        result_json=terminal_values -> 'result_json',
        result_fingerprint=terminal_values ->> 'result_fingerprint',
        input_fingerprint=coalesce(terminal_values ->> 'input_fingerprint',input_fingerprint),
        summary_json=terminal_values -> 'summary_json',
        progress_json=coalesce(terminal_values -> 'progress_json',jsonb_build_object('stage',outcome)),
        error_message=terminal_values ->> 'error_message'
    where id=target_run_id and status='running';
    if not found then return; end if;
    update public.dispatch_run_jobs set state=outcome, lease_token=null, lease_expires_at=null
    where run_id=target_run_id;
    return query select * from public.decision_runs where id=target_run_id;
end;
$function$

CREATE OR REPLACE FUNCTION dation_private.guard_dataset_deletion()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE pending record;
BEGIN
 -- Concurrent reference creation holds a shared workspace lock. Preparing or
 -- finishing deletion takes the exclusive lock before checking all evidence.
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('dation-data:'||NEW.workspace_id::text,0));
 IF TG_TABLE_NAME='datasets' THEN
  IF TG_OP='UPDATE' AND NEW.uploaded_by_user_id IS DISTINCT FROM OLD.uploaded_by_user_id THEN
   RAISE EXCEPTION 'Uploader identity is immutable' USING ERRCODE='22023';
  END IF;
  IF TG_OP='INSERT' AND NEW.uploaded_by_user_id IS NOT NULL THEN
   PERFORM dation_private.data_actor(NEW.workspace_id,NEW.uploaded_by_user_id,true);
  END IF;
  IF TG_OP='INSERT' AND EXISTS(SELECT 1 FROM dation_private.dataset_uploads WHERE dataset_id=NEW.id AND status IN('discarding','discarded')) THEN
   RAISE EXCEPTION 'Upload was discarded' USING ERRCODE='22023'; END IF;
 END IF;
 FOR pending IN SELECT dataset_id FROM dation_private.dataset_deletions WHERE workspace_id=NEW.workspace_id AND status='pending' LOOP
  IF TG_TABLE_NAME='datasets' AND (to_jsonb(NEW)->>'id')=pending.dataset_id::text THEN CONTINUE; END IF;
  IF jsonb_path_exists(to_jsonb(NEW),'$.** ? (@ == $id)',jsonb_build_object('id',pending.dataset_id::text)) THEN
   RAISE EXCEPTION 'Dataset deletion is pending' USING ERRCODE='22023';
  END IF;
 END LOOP;
 RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION dation_private.heartbeat_dispatch_job(target_run_id uuid, worker_token uuid, lease_seconds integer DEFAULT 120, progress jsonb DEFAULT NULL::jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'dation_private', 'public', 'pg_temp'
AS $function$
begin
    update public.dispatch_run_jobs set heartbeat_at=now(),
        lease_expires_at=least(deadline_at,now()+make_interval(secs=>greatest(30,least(lease_seconds,300))))
    where run_id=target_run_id and state='running' and lease_token=worker_token
      and lease_expires_at > now() and deadline_at > now();
    if not found then return false; end if;
    if progress is not null then
        update public.decision_runs set progress_json=progress
        where id=target_run_id and status='running';
    end if;
    return true;
end;
$function$

CREATE OR REPLACE FUNCTION dation_private.invalidate_run_lineage(admitted decision_runs)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE sequence text[]=ARRAY['logistics_assignment','logistics_scheduling','logistics_final_assignment'];
 position integer; affected text[]; reopening boolean; stamp timestamptz=clock_timestamp();
BEGIN
 position=array_position(sequence,admitted.node_id);
 IF admitted.decision_case_id IS NULL OR position IS NULL THEN RETURN; END IF;
 PERFORM 1 FROM workspaces WHERE id=admitted.workspace_id FOR UPDATE;
 PERFORM 1 FROM decision_cases WHERE workspace_id=admitted.workspace_id AND id=admitted.decision_case_id FOR UPDATE;
 SELECT EXISTS(SELECT 1 FROM decision_runs WHERE workspace_id=admitted.workspace_id
  AND decision_case_id=admitted.decision_case_id AND node_id=admitted.node_id
  AND id<>admitted.id AND approved_at IS NOT NULL AND superseded_at IS NULL) INTO reopening;
 affected=sequence[(position+1):array_length(sequence,1)];
 IF reopening THEN affected=array_prepend(admitted.node_id,coalesce(affected,ARRAY[]::text[])); END IF;
 INSERT INTO decision_approval_events(workspace_id,run_id,case_id,node_id,action,actor,actor_user_id,occurred_at,replacement_run_id)
 SELECT workspace_id,id,decision_case_id,node_id,'superseded',coalesce('user:'||admitted.created_by_user_id,'system:run_reopening'),
  admitted.created_by_user_id,stamp,admitted.id FROM decision_runs
 WHERE workspace_id=admitted.workspace_id AND decision_case_id=admitted.decision_case_id
  AND node_id=ANY(affected) AND id<>admitted.id AND approved_at IS NOT NULL AND superseded_at IS NULL;
 UPDATE decision_runs SET superseded_at=stamp,superseded_by_run_id=admitted.id
 WHERE workspace_id=admitted.workspace_id AND decision_case_id=admitted.decision_case_id
  AND node_id=ANY(affected) AND id<>admitted.id AND superseded_at IS NULL;
END; $function$

CREATE OR REPLACE FUNCTION dation_private.maintain_dispatch_jobs()
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO 'dation_private', 'public', 'pg_temp'
AS $function$
declare changed integer;
begin
    with expired as (
        update public.dispatch_run_jobs set state='error', lease_token=null, lease_expires_at=null
        where (dation_private.workspace_id() IS NULL OR workspace_id=dation_private.workspace_id()) and state in ('queued','running') and (
            deadline_at <= now()
            or (state='running' and lease_expires_at <= now() and attempts >= max_attempts)
        ) returning run_id
    )
    update public.decision_runs set status='error', finished_at=now(),
        error_message='La ejecución agotó su plazo o sus intentos de recuperación.',
        progress_json=jsonb_build_object('stage','error','reason','recovery_exhausted')
    where id in (select run_id from expired) and status in ('queued','running');
    get diagnostics changed = row_count;
    return changed;
end;
$function$

