CREATE OR REPLACE FUNCTION dation_private.t4_entries(wid uuid, cid uuid, selection jsonb, contracts jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE item jsonb; did uuid; model uuid; entry jsonb; result jsonb='{}'; slot text;
BEGIN
 SELECT logistics_model_version_id INTO model FROM public.decision_cases WHERE workspace_id=wid AND id=cid;
 IF jsonb_typeof(selection) IS DISTINCT FROM 'array' OR jsonb_array_length(selection) NOT BETWEEN 1 AND 2
  OR (SELECT count(*)<>count(DISTINCT x->>'slot_key') FROM jsonb_array_elements(selection) x) THEN RAISE EXCEPTION 'Invalid slot selection' USING ERRCODE='22023'; END IF;
 SELECT coalesce(jsonb_object_agg(e.slot_key,dation_private.t4_entry(wid,e.slot_key,e.dataset_id)),'{}') INTO result
  FROM public.case_data_packs p JOIN public.case_data_pack_entries e ON e.workspace_id=p.workspace_id AND e.pack_version_id=p.current_version_id
  WHERE p.workspace_id=wid AND p.case_id=cid;
 FOR item IN SELECT x FROM jsonb_array_elements(selection) x LOOP
  slot=item->>'slot_key';
  IF coalesce(slot,'') NOT IN('transport_demand','transport_resources') OR num_nonnulls(item->>'upload_id',item->>'dataset_id')<>1 THEN RAISE EXCEPTION 'Invalid semantic slot' USING ERRCODE='22023'; END IF;
  IF item?'upload_id' THEN
   SELECT dataset_id INTO did FROM dation_private.ultimate_input_uploads WHERE workspace_id=wid AND case_id=cid AND id=(item->>'upload_id')::uuid AND entity=slot AND status='READY';
  ELSE did=(item->>'dataset_id')::uuid; END IF;
  entry=dation_private.t4_entry(wid,slot,did);
  IF entry IS NULL OR entry->>'contract_hash' IS DISTINCT FROM contracts->>slot
   OR NOT EXISTS(SELECT 1 FROM dation_private.ultimate_input_objects o JOIN public.datasets d ON d.workspace_id=o.workspace_id AND d.id=o.dataset_id
    WHERE o.workspace_id=wid AND o.dataset_id=did AND o.model_version_id=model AND d.archived_at IS NULL) THEN
   RAISE EXCEPTION 'Input is not compatible with this Model Version' USING ERRCODE='22023'; END IF;
  result=jsonb_set(result,ARRAY[slot],entry);
 END LOOP;
 IF EXISTS(SELECT 1 FROM jsonb_each(result) x WHERE x.value='null'::jsonb) THEN RAISE EXCEPTION 'Missing immutable input metadata' USING ERRCODE='22023'; END IF;
 RETURN (SELECT coalesce(jsonb_agg(value ORDER BY key),'[]') FROM jsonb_each(result));
END; $function$

CREATE OR REPLACE FUNCTION dation_private.t8_canonical(v jsonb)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE answer text;
BEGIN
 IF jsonb_typeof(v)='object' THEN
  SELECT '{'||coalesce(string_agg(to_json(key)::text||':'||dation_private.t8_canonical(value),',' ORDER BY key COLLATE "C"),'')||'}' INTO answer FROM jsonb_each(v);
 ELSIF jsonb_typeof(v)='array' THEN
  SELECT '['||coalesce(string_agg(dation_private.t8_canonical(value),',' ORDER BY ord),'')||']' INTO answer FROM jsonb_array_elements(v) WITH ORDINALITY x(value,ord);
 ELSE answer=v::text; END IF;
 RETURN answer;
END; $function$

CREATE OR REPLACE FUNCTION dation_private.t8_input_hash(c jsonb)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN
 c=c-'case_name'-'display_metadata';
 c=jsonb_set(c,'{case_policy}',dation_private.t8_policy_projection(c->'case_policy'));
 c=jsonb_set(c,'{node_policy}',dation_private.t8_policy_projection(c->'node_policy'));
 c=jsonb_set(c,'{read_set}',(SELECT jsonb_agg(x ORDER BY x->>'slot') FROM jsonb_array_elements(c->'read_set') x));
 c=jsonb_set(c,'{active_dimensions}',(SELECT jsonb_agg(x ORDER BY x) FROM jsonb_array_elements(c->'active_dimensions') x));
 RETURN dation_private.t8_hash('INPUT_CONTEXT',jsonb_build_object('context',c,'runtime_identity',jsonb_build_object(
  'engine_name','transport_plan','engine_version','2.0.0','runtime_profile','transport_plan_v1','result_schema','transport_plan_v1','result_schema_version',1),
  'transit_model_version','DATION_TRANSIT_V1','upstream',NULL));
END; $function$

CREATE OR REPLACE FUNCTION dation_private.t8_pack_invalidation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE r public.decision_runs; uid uuid; stamp timestamptz=clock_timestamp();
BEGIN
 IF NEW.current_version_id IS NOT DISTINCT FROM OLD.current_version_id THEN RETURN NEW; END IF;
 PERFORM 1 FROM public.workspaces WHERE id=NEW.workspace_id FOR UPDATE;
 PERFORM 1 FROM public.decision_cases WHERE workspace_id=NEW.workspace_id AND id=NEW.case_id FOR UPDATE;
 SELECT created_by INTO uid FROM public.case_data_pack_versions WHERE id=NEW.current_version_id;
 FOR r IN SELECT * FROM public.decision_runs WHERE workspace_id=NEW.workspace_id AND decision_case_id=NEW.case_id
  AND workflow_version=2 AND superseded_at IS NULL ORDER BY CASE node_id WHEN 'logistics_assignment' THEN 0 ELSE 1 END,id FOR UPDATE LOOP
  IF NOT dation_private.t8_fresh(r) THEN
   IF r.approved_at IS NOT NULL THEN
    INSERT INTO public.decision_approval_events(workspace_id,run_id,case_id,node_id,action,actor,actor_user_id,occurred_at,reason_code,caused_by_pack_version_id)
     VALUES(r.workspace_id,r.id,r.decision_case_id,r.node_id,'superseded','user:'||uid,uid,stamp,'INPUT_READ_SET_CHANGED',NEW.current_version_id);
   END IF;
   UPDATE public.decision_runs SET superseded_at=stamp,invalidated_by_pack_version_id=NEW.current_version_id WHERE id=r.id;
  END IF;
 END LOOP;
 RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION dation_private.t8_package_hash(v jsonb)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE m jsonb;
BEGIN
 SELECT coalesce(jsonb_agg(a ORDER BY a->>'kind',a->>'part_key',a->>'artifact_id'),'[]') INTO m FROM jsonb_array_elements(v#>'{artifact_manifest,artifacts}') a;
 v=jsonb_set(v,'{fingerprints}',(v->'fingerprints')-'result_fingerprint');
 v=jsonb_set(v,'{artifact_manifest,artifacts}',m);
 RETURN dation_private.t8_hash('RESULT_PACKAGE',v);
END; $function$

CREATE OR REPLACE FUNCTION dation_private.t8_read_set(r decision_runs)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE c public.decision_cases; key text; result jsonb='{}'; value jsonb; pvid uuid;
BEGIN
 SELECT * INTO c FROM public.decision_cases WHERE workspace_id=r.workspace_id AND id=r.decision_case_id;
 SELECT current_version_id INTO pvid FROM public.case_data_packs WHERE workspace_id=r.workspace_id AND case_id=r.decision_case_id;
 FOR key IN SELECT jsonb_object_keys(r.configuration_json#>'{ultimate_graph,read_set}') LOOP
  value=NULL;
  IF key IN('transport_demand','transport_resources','scheduling_enrichment') THEN
   SELECT jsonb_build_object('canonical_sha256',e.canonical_sha256,'contract_hash',e.contract_hash,'normalizer_version',e.normalizer_version) INTO value
    FROM public.case_data_pack_entries e WHERE workspace_id=r.workspace_id AND pack_version_id=pvid AND slot_key=key;
  ELSIF key='model' THEN value=to_jsonb(c.logistics_model_version_id);
  ELSIF key='horizon' THEN value=jsonb_build_array(c.planning_start,c.planning_end);
  ELSIF key='case_policy' THEN value=to_jsonb(c.case_policy_hash);
  ELSIF key='node_policy' THEN value=to_jsonb(r.node_policy_hash);
  ELSIF key='approved:logistics_assignment' THEN
   SELECT CASE WHEN count(*)=1 THEN to_jsonb(min(id::text)) ELSE 'null'::jsonb END INTO value FROM public.decision_runs
    WHERE workspace_id=r.workspace_id AND decision_case_id=r.decision_case_id AND node_id='logistics_assignment'
    AND workflow_version=2 AND approved_at IS NOT NULL AND superseded_at IS NULL;
  ELSE RETURN NULL; END IF;
  result=result||jsonb_build_object(key,value);
 END LOOP;
 RETURN result;
END; $function$

CREATE OR REPLACE FUNCTION dation_private.t9_core_hash(v jsonb)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE transport jsonb=v->'transport_plan'; metrics jsonb=v->'metrics'; trips jsonb;
BEGIN
 SELECT jsonb_agg(jsonb_set(jsonb_set(t,'{orders}',(SELECT jsonb_agg(a ORDER BY a->>'order_id') FROM jsonb_array_elements(t->'orders') a)),'{reason_codes}',coalesce((SELECT jsonb_agg(x ORDER BY x) FROM jsonb_array_elements(t->'reason_codes') x),'[]')) ORDER BY t->>'trip_id') INTO trips FROM jsonb_array_elements(transport->'trips') t;
 transport=jsonb_set(transport,'{trips}',coalesce(trips,'[]'));
 transport=jsonb_set(transport,'{unassigned_demand}',coalesce((SELECT jsonb_agg(t ORDER BY t->>'order_id') FROM jsonb_array_elements(transport->'unassigned_demand') t),'[]'));
 metrics=jsonb_set(metrics,'{coverage_by_priority}',(SELECT jsonb_agg(t ORDER BY t->>'priority') FROM jsonb_array_elements(metrics->'coverage_by_priority') t));
 RETURN dation_private.t8_hash('CORE_RESULT',jsonb_build_object('contract_version',v->'contract_version','result_schema',v->'result_schema','result_schema_version',v->'result_schema_version','input_context_hash',v->'input_context_hash',
  'decision',jsonb_build_object('node_id',v#>'{decision,node_id}','decision_type',v#>'{decision,decision_type}'),'engine',(v->'engine')-'result_generated_at','feasibility',v->'feasibility','metrics',metrics,'transport_plan',transport,'schedule',v->'schedule','source_transport_plan',v->'source_transport_plan'));
END; $function$

CREATE OR REPLACE FUNCTION dation_private.ultimate_artifact_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE key text;
BEGIN
 IF TG_OP<>'INSERT' THEN
  IF OLD.publication_state='READY' THEN RAISE EXCEPTION 'READY artifact is immutable' USING ERRCODE='22023'; END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  IF (to_jsonb(NEW)-'publication_state'-'result_fingerprint') IS DISTINCT FROM
     (to_jsonb(OLD)-'publication_state'-'result_fingerprint') THEN
   RAISE EXCEPTION 'Prepared artifact identity is immutable' USING ERRCODE='22023'; END IF;
 END IF;
 FOREACH key IN ARRAY NEW.lookup_keys LOOP
  IF key !~ '^(CASE|ORDER|TRIP|RESOURCE|ALTERNATIVE|EXCEPTION)/[A-Za-z0-9][A-Za-z0-9_.:-]{0,127}$' THEN
   RAISE EXCEPTION 'Invalid entity lookup key' USING ERRCODE='22023'; END IF;
 END LOOP;
 IF NOT EXISTS(SELECT 1 FROM public.decision_runs WHERE workspace_id=NEW.workspace_id AND id=NEW.run_id AND workflow_version=2) THEN
  RAISE EXCEPTION 'Artifacts require an Ultimate Run' USING ERRCODE='22023'; END IF;
 RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION dation_private.ultimate_artifact_ready()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE a public.decision_result_artifacts; r public.decision_runs; descriptor jsonb;
BEGIN
 SELECT * INTO a FROM public.decision_result_artifacts WHERE id=NEW.id;
 IF NOT FOUND OR a.publication_state<>'READY' THEN RETURN NULL; END IF;
 SELECT * INTO r FROM public.decision_runs WHERE workspace_id=a.workspace_id AND id=a.run_id;
 descriptor=jsonb_build_object('artifact_id',a.id,'workspace_id',a.workspace_id,'run_id',a.run_id,
  'kind',a.kind,'part_key',a.part_key,'artifact_schema',a.artifact_schema,'schema_version',a.schema_version,
  'content_sha256',a.content_sha256,'size_bytes',a.size_bytes,'media_type',a.media_type,
  'core_fingerprint',a.core_fingerprint,'assembler_version',a.assembler_version);
 IF r.status<>'completed' OR r.result_package_version IS DISTINCT FROM 1
  OR r.result_fingerprint IS DISTINCT FROM a.result_fingerprint OR r.core_fingerprint IS DISTINCT FROM a.core_fingerprint
  OR r.assembler_version IS DISTINCT FROM a.assembler_version OR r.artifact_manifest_hash IS NULL
  OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(r.result_json#>'{artifact_manifest,artifacts}','[]')) item
    WHERE item @> descriptor) THEN
  RAISE EXCEPTION 'READY artifact requires its exact published Run/manifest binding' USING ERRCODE='23514'; END IF;
 RETURN NULL;
END; $function$

CREATE OR REPLACE FUNCTION dation_private.ultimate_interpretation_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE ref jsonb;
BEGIN
 IF TG_OP='UPDATE' THEN
  IF NEW IS DISTINCT FROM OLD THEN RAISE EXCEPTION 'Interpretation provenance is immutable' USING ERRCODE='22023'; END IF;
  RETURN NEW;
 END IF;
 IF NEW.provenance_version IS NOT NULL THEN
  IF NOT EXISTS(SELECT 1 FROM public.decision_runs WHERE workspace_id=NEW.workspace_id AND id=NEW.run_id
    AND result_fingerprint=NEW.result_fingerprint AND workflow_version=2 AND status='completed' AND result_package_version=1) THEN
   RAISE EXCEPTION 'Interpretation requires the published Ultimate result' USING ERRCODE='22023'; END IF;
  FOR ref IN SELECT value FROM jsonb_array_elements(NEW.evidence_refs) LOOP
   IF NOT EXISTS(SELECT 1 FROM public.decision_result_artifacts WHERE workspace_id=NEW.workspace_id AND run_id=NEW.run_id
     AND result_fingerprint=NEW.result_fingerprint AND publication_state='READY'
     AND id::text=ref->>'artifact_id' AND content_sha256=ref->>'content_sha256') THEN
    RAISE EXCEPTION 'Interpretation evidence must belong to the same published Run' USING ERRCODE='22023'; END IF;
  END LOOP;
 END IF;
 RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION dation_private.ultimate_pack_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE cohort smallint; version_xid xid8; actual_type text;
BEGIN
 IF TG_TABLE_NAME='case_data_packs' THEN
  SELECT workflow_version INTO cohort FROM public.decision_cases WHERE workspace_id=NEW.workspace_id AND id=NEW.case_id;
  IF cohort IS NOT NULL AND cohort<>2 THEN RAISE EXCEPTION 'Progressive Pack requires an Ultimate Case' USING ERRCODE='22023'; END IF;
  IF TG_OP='UPDATE' AND ROW(NEW.id,NEW.workspace_id,NEW.case_id,NEW.created_at)
    IS DISTINCT FROM ROW(OLD.id,OLD.workspace_id,OLD.case_id,OLD.created_at) THEN
   RAISE EXCEPTION 'Pack identity is immutable' USING ERRCODE='22023'; END IF;
 ELSIF TG_TABLE_NAME='case_data_pack_versions' THEN NEW.created_xid=pg_current_xact_id();
 ELSE
  SELECT created_xid INTO version_xid FROM public.case_data_pack_versions
   WHERE workspace_id=NEW.workspace_id AND case_id=NEW.case_id AND id=NEW.pack_version_id;
  IF NOT FOUND THEN RETURN NEW; END IF; -- The composite FK rejects an absent/cross-tenant version.
  IF version_xid IS DISTINCT FROM pg_current_xact_id() THEN
   RAISE EXCEPTION 'Entries belong to the immutable version creation transaction' USING ERRCODE='22023'; END IF;
  SELECT dataset_type INTO actual_type FROM public.datasets WHERE workspace_id=NEW.workspace_id AND id=NEW.dataset_id;
  IF NOT FOUND THEN RETURN NEW; END IF; -- The interpretation FK is authoritative.
  IF NEW.slot_key IN('transport_demand','transport_resources') AND actual_type IS DISTINCT FROM NEW.slot_key THEN
   RAISE EXCEPTION 'Pack slot conflicts with dataset contract' USING ERRCODE='22023'; END IF;
 END IF;
 RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION dation_private.ultimate_run_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE c public.decision_cases;
BEGIN
 IF NEW.decision_case_id IS NOT NULL THEN
  SELECT * INTO c FROM public.decision_cases WHERE workspace_id=NEW.workspace_id AND id=NEW.decision_case_id;
  IF FOUND AND c.workflow_version<>NEW.workflow_version THEN
   RAISE EXCEPTION 'Run/Case cohorts differ' USING ERRCODE='22023'; END IF;
 END IF;
 IF TG_OP='UPDATE' AND ROW(NEW.workflow_version,NEW.logistics_model_version_id,NEW.data_pack_version_id,
  NEW.graph_definition_version,NEW.case_policy_hash,NEW.node_policy_hash,NEW.contract_hash,NEW.input_context_hash,
  NEW.transit_model_version,NEW.runtime_profile,NEW.result_schema_version)
 IS DISTINCT FROM ROW(OLD.workflow_version,OLD.logistics_model_version_id,OLD.data_pack_version_id,
  OLD.graph_definition_version,OLD.case_policy_hash,OLD.node_policy_hash,OLD.contract_hash,OLD.input_context_hash,
  OLD.transit_model_version,OLD.runtime_profile,OLD.result_schema_version) THEN
  RAISE EXCEPTION 'Run context pinning is immutable' USING ERRCODE='22023'; END IF;
 IF NEW.workflow_version=2 THEN
  IF c.context_frozen_at IS NULL OR NEW.case_policy_hash IS DISTINCT FROM c.case_policy_hash
    OR NEW.graph_definition_version IS DISTINCT FROM c.graph_definition_version THEN
   RAISE EXCEPTION 'Run requires the frozen Case policy/graph' USING ERRCODE='22023'; END IF;
  IF NOT EXISTS(SELECT 1 FROM public.case_data_pack_entries WHERE workspace_id=NEW.workspace_id
    AND case_id=NEW.decision_case_id AND pack_version_id=NEW.data_pack_version_id
    AND slot_key='transport_demand' AND dataset_id=NEW.dataset_id) THEN
   RAISE EXCEPTION 'Run primary raw Demand must belong to its Pack' USING ERRCODE='22023'; END IF;
  IF NEW.status='completed' AND (NEW.result_json->>'result_schema' IS DISTINCT FROM NEW.schema_version
    OR NEW.result_json->>'result_schema_version' IS DISTINCT FROM NEW.result_schema_version::text) THEN
   RAISE EXCEPTION 'Run/package schema mismatch' USING ERRCODE='22023'; END IF;
 END IF;
 RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION public.claim_dispatch_job(worker_token uuid, lease_seconds integer DEFAULT 120)
 RETURNS SETOF dispatch_run_jobs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'dation_private', 'public', 'pg_temp'
AS $function$
declare target public.dispatch_run_jobs%rowtype;
begin
    perform dation_private.maintain_dispatch_jobs();
    select * into target from public.dispatch_run_jobs
    where coalesce((request_json->>'workflow_version')::integer,1)=1 AND ((state='queued' and available_at <= now()) or (state='running' and lease_expires_at <= now()))
      and attempts < max_attempts and deadline_at > now()
    order by available_at, created_at for update skip locked limit 1;
    if not found then return; end if;
    update public.dispatch_run_jobs set state='running', attempts=attempts+1,
        lease_token=worker_token, heartbeat_at=now(),
        lease_expires_at=least(deadline_at,now()+make_interval(secs=>greatest(30,least(lease_seconds,300))))
    where run_id=target.run_id;
    update public.decision_runs set status='running', started_at=coalesce(started_at,now()),
        progress_json=jsonb_build_object('stage','validating','attempt',target.attempts+1), error_message=null
    where id=target.run_id and status in ('queued','running');
    return query select * from public.dispatch_run_jobs where run_id=target.run_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.claim_dispatch_job_v2(worker_token uuid, lease_seconds integer DEFAULT 120)
 RETURNS SETOF dispatch_run_jobs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE j public.dispatch_run_jobs;
BEGIN
 PERFORM dation_private.maintain_dispatch_jobs();
 SELECT * INTO j FROM public.dispatch_run_jobs WHERE ((state='queued' AND available_at<=clock_timestamp()) OR (state='running' AND lease_expires_at<=clock_timestamp()))
  AND attempts<max_attempts AND deadline_at>clock_timestamp() ORDER BY available_at,created_at FOR UPDATE SKIP LOCKED LIMIT 1;
 IF NOT FOUND THEN RETURN; END IF;
 UPDATE public.dispatch_run_jobs SET state='running',attempts=attempts+1,lease_token=worker_token,heartbeat_at=clock_timestamp(),
  lease_expires_at=least(deadline_at,clock_timestamp()+make_interval(secs=>greatest(30,least(lease_seconds,300)))) WHERE run_id=j.run_id;
 UPDATE public.decision_runs SET status='running',started_at=coalesce(started_at,clock_timestamp()),progress_json=jsonb_build_object('stage','validating'),error_message=NULL
  WHERE id=j.run_id AND status IN('queued','running');
 RETURN QUERY SELECT * FROM public.dispatch_run_jobs WHERE run_id=j.run_id;
END; $function$

CREATE OR REPLACE FUNCTION public.enqueue_case_reconciliation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'dation_private', 'public', 'pg_temp'
AS $function$
begin
    if new.decision_case_id is not null then
        perform dation_private.request_case_reconciliation(new.decision_case_id);
    end if;
    return new;
