$function$

CREATE OR REPLACE FUNCTION public.platform_apply_case_attributes(target_workspace_id uuid, actor_user_id uuid, target_case_id uuid, expected_updated_at timestamp with time zone, identity_changes jsonb, expected_owner_updated_at timestamp with time zone, change_data_owner boolean DEFAULT false, new_data_owner_user_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE result jsonb; responsibilities jsonb; owner_version timestamptz;
BEGIN
 -- Same workspace -> Case lock order as admission and responsibility assignment.
 PERFORM 1 FROM workspaces WHERE id=target_workspace_id FOR UPDATE;
 result=public.platform_update_case_identity(target_workspace_id,actor_user_id,target_case_id,expected_updated_at,identity_changes);
 SELECT updated_at INTO owner_version FROM dation_private.workflow_stage_assignments
  WHERE workspace_id=target_workspace_id AND decision_case_id=target_case_id AND stage_key='data_owner';
 IF owner_version IS DISTINCT FROM expected_owner_updated_at THEN RAISE EXCEPTION 'Assignment changed' USING ERRCODE='55006'; END IF;
 IF change_data_owner THEN
  responsibilities=public.platform_workflow_responsibilities(target_workspace_id,actor_user_id,target_case_id,'write','data_owner',expected_owner_updated_at,new_data_owner_user_id,NULL);
 ELSE
  responsibilities=public.platform_workflow_responsibilities(target_workspace_id,actor_user_id,target_case_id);
 END IF;
 -- Any ownership/CAS/permission failure rolls back the identity update as well.
 RETURN result||jsonb_build_object('workflow_responsibilities',responsibilities);
END; $function$

CREATE OR REPLACE FUNCTION public.platform_assign_decision(target_workspace_id uuid, actor_user_id uuid, target_case_id uuid, target_node_id text, expected_updated_at timestamp with time zone, new_owner_user_id uuid, new_approver_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE assignment decision_assignments;
BEGIN
 PERFORM 1 FROM workspaces WHERE id=target_workspace_id FOR UPDATE;
 PERFORM dation_private.team_actor(target_workspace_id,actor_user_id,true);
 PERFORM 1 FROM decision_cases WHERE workspace_id=target_workspace_id AND id=target_case_id AND status<>'archived' FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Case not found or archived' USING ERRCODE='P0002'; END IF;
 IF target_node_id NOT IN('logistics_assignment','logistics_scheduling') OR target_node_id IS NULL THEN RAISE EXCEPTION 'Invalid node' USING ERRCODE='22023'; END IF;
 SELECT * INTO assignment FROM decision_assignments WHERE workspace_id=target_workspace_id AND decision_case_id=target_case_id AND node_id=target_node_id FOR UPDATE;
 IF assignment.updated_at IS DISTINCT FROM expected_updated_at THEN RAISE EXCEPTION 'Assignment changed' USING ERRCODE='55006'; END IF;
 IF new_approver_user_id IS NOT NULL AND new_approver_user_id IS DISTINCT FROM new_owner_user_id AND new_approver_user_id IS DISTINCT FROM assignment.approver_user_id THEN
  RAISE EXCEPTION 'Use the Decision Owner; separate approvers are retired' USING ERRCODE='22023'; END IF;
 IF new_owner_user_id IS DISTINCT FROM assignment.owner_user_id THEN
  IF new_owner_user_id IS NOT NULL AND NOT dation_private.responsibility_eligible(target_workspace_id,new_owner_user_id,'decision_owner') THEN
   RAISE EXCEPTION 'Assignee responsibility is not eligible' USING ERRCODE='22023'; END IF;
  INSERT INTO decision_assignments(workspace_id,decision_case_id,node_id,owner_user_id)
   VALUES(target_workspace_id,target_case_id,target_node_id,new_owner_user_id)
   ON CONFLICT(decision_case_id,node_id) DO UPDATE SET owner_user_id=excluded.owner_user_id,updated_at=clock_timestamp()
   RETURNING * INTO assignment;
  INSERT INTO audit_events(workspace_id,actor_user_id,event_type,object_type,object_id,decision_case_id,node_id,metadata_json)
   VALUES(target_workspace_id,actor_user_id,'decision.owner_changed','decision_case',target_case_id,target_case_id,target_node_id,
    jsonb_build_object('stage_key',target_node_id,'new_user_id',new_owner_user_id));
 END IF;
 RETURN jsonb_build_object('updated_at',assignment.updated_at);
END; $function$

CREATE OR REPLACE FUNCTION public.platform_create_workspace(actor_user_id uuid, workspace_name text, workspace_country text, workspace_timezone text, workspace_currency text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE target uuid;
BEGIN
 IF NOT (SELECT admissions_open FROM dation_private.platform_release WHERE singleton) OR NOT EXISTS(
  SELECT 1 FROM auth.users WHERE id=actor_user_id AND email_confirmed_at IS NOT NULL) THEN RAISE EXCEPTION 'Identity denied' USING ERRCODE='42501'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(actor_user_id::text,0));
 IF EXISTS(SELECT 1 FROM workspace_members WHERE user_id=actor_user_id) OR EXISTS(
  SELECT 1 FROM dation_private.legacy_owners o JOIN auth.users u ON lower(u.email)=o.email WHERE u.id=actor_user_id) THEN
  RAISE EXCEPTION 'Existing membership must be resolved first' USING ERRCODE='22023'; END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_timezone_names WHERE name=workspace_timezone) THEN RAISE EXCEPTION 'Invalid timezone' USING ERRCODE='22023'; END IF;
 INSERT INTO profiles(id) VALUES(actor_user_id) ON CONFLICT DO NOTHING;
 INSERT INTO workspaces(name,country,timezone,currency,created_by) VALUES(trim(workspace_name),workspace_country,workspace_timezone,workspace_currency,actor_user_id) RETURNING id INTO target;
 INSERT INTO workspace_members(workspace_id,user_id,access_role,joined_at) VALUES(target,actor_user_id,'admin',now());
 INSERT INTO workspace_ddas(workspace_id,dda_id,status)
  SELECT target,id,CASE WHEN id='logistics' THEN 'enabled' ELSE 'coming_soon' END
  FROM unnest(ARRAY['logistics','production','inventory','demand','purchasing','maintenance','pricing']) id;
 INSERT INTO audit_events(workspace_id,actor_user_id,event_type) VALUES(target,actor_user_id,'workspace.created');
 UPDATE profiles SET active_workspace_id=target,updated_at=now() WHERE id=actor_user_id;
 RETURN jsonb_build_object('workspace_id',target);
END; $function$

CREATE OR REPLACE FUNCTION public.platform_dataset_delete(target_workspace_id uuid, actor_user_id uuid, target_dataset_id uuid, operation text DEFAULT 'prepare'::text, operation_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE target datasets; intent dation_private.dataset_deletions;
BEGIN
 PERFORM dation_private.data_actor(target_workspace_id,actor_user_id,true);
 IF operation NOT IN('prepare','finish') THEN RAISE EXCEPTION 'Invalid delete operation' USING ERRCODE='22023'; END IF;
 IF NOT pg_try_advisory_xact_lock(hashtextextended('dation-data:'||target_workspace_id::text,0)) THEN
  RAISE EXCEPTION 'Workspace data is busy; retry' USING ERRCODE='55006'; END IF;
 SELECT * INTO intent FROM dation_private.dataset_deletions WHERE dataset_id=target_dataset_id AND workspace_id=target_workspace_id FOR UPDATE;
 IF FOUND AND intent.status='completed' THEN RETURN jsonb_build_object('deleted',true); END IF;
 SELECT * INTO target FROM datasets WHERE id=target_dataset_id AND workspace_id=target_workspace_id FOR UPDATE NOWAIT;
 IF NOT FOUND THEN RAISE EXCEPTION 'Dataset not found' USING ERRCODE='P0002'; END IF;
 IF target.archived_at IS NULL OR target.is_default OR dation_private.dataset_referenced(target_workspace_id,target_dataset_id) THEN
  RAISE EXCEPTION 'Archive first; referenced datasets must be retained' USING ERRCODE='22023'; END IF;
 IF operation='prepare' THEN
  IF intent.id IS NULL THEN
   INSERT INTO dation_private.dataset_deletions(workspace_id,dataset_id,actor_user_id,storage_bucket,storage_path)
    VALUES(target_workspace_id,target_dataset_id,actor_user_id,target.storage_bucket,target.storage_path) RETURNING * INTO intent;
   UPDATE datasets SET deletion_requested_at=clock_timestamp() WHERE id=target_dataset_id AND workspace_id=target_workspace_id;
  END IF;
  RETURN jsonb_build_object('deleted',false,'operation_id',intent.id,'storage_bucket',intent.storage_bucket,'storage_path',intent.storage_path);
 END IF;
 IF intent.id IS NULL OR operation_id IS DISTINCT FROM intent.id OR target.deletion_requested_at IS NULL THEN
  RAISE EXCEPTION 'Prepare deletion before finishing' USING ERRCODE='42501'; END IF;
 DELETE FROM datasets WHERE id=target_dataset_id AND workspace_id=target_workspace_id;
 UPDATE dation_private.dataset_deletions SET status='completed',completed_at=clock_timestamp() WHERE id=intent.id;
 RETURN jsonb_build_object('deleted',true);
EXCEPTION WHEN lock_not_available THEN
 RAISE EXCEPTION 'Dataset is busy; retry' USING ERRCODE='55006';
END; $function$

CREATE OR REPLACE FUNCTION public.platform_dataset_upload(target_workspace_id uuid, actor_user_id uuid, operation text, target_dataset_id uuid DEFAULT NULL::uuid, operation_id uuid DEFAULT NULL::uuid, object_bucket text DEFAULT NULL::text, object_path text DEFAULT NULL::text, filename text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE intent dation_private.dataset_uploads; stored datasets;
BEGIN
 PERFORM dation_private.data_actor(target_workspace_id,actor_user_id,true);
 IF operation NOT IN('prepare','stored','failed','discard','finish') THEN RAISE EXCEPTION 'Invalid upload operation' USING ERRCODE='22023'; END IF;
 IF operation<>'prepare' AND NOT pg_try_advisory_xact_lock(hashtextextended('dation-data:'||target_workspace_id::text,0)) THEN
  RAISE EXCEPTION 'Workspace data is busy; retry' USING ERRCODE='55006'; END IF;
 IF operation='prepare' THEN
  IF target_dataset_id IS NULL OR length(coalesce(filename,'')) NOT BETWEEN 1 AND 512 OR
   object_bucket IS NULL OR object_path IS NULL OR split_part(object_path,'/',1)<>target_workspace_id::text
   OR split_part(object_path,'/',2)<>target_dataset_id::text OR array_length(string_to_array(object_path,'/'),1)<>3
   OR split_part(object_path,'/',3) IN('','.','..') THEN RAISE EXCEPTION 'Invalid upload identity' USING ERRCODE='22023'; END IF;
  INSERT INTO dation_private.dataset_uploads(workspace_id,actor_user_id,dataset_id,storage_bucket,storage_path,filename)
   VALUES(target_workspace_id,actor_user_id,target_dataset_id,object_bucket,object_path,filename) RETURNING * INTO intent;
  RETURN jsonb_build_object('operation_id',intent.id);
 END IF;
 SELECT * INTO intent FROM dation_private.dataset_uploads WHERE id=operation_id AND workspace_id=target_workspace_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Upload not found' USING ERRCODE='P0002'; END IF;
 SELECT * INTO stored FROM datasets WHERE id=intent.dataset_id AND workspace_id=target_workspace_id;
 IF FOUND THEN
  IF stored.storage_bucket<>intent.storage_bucket OR stored.storage_path<>intent.storage_path THEN RAISE EXCEPTION 'Upload identity mismatch' USING ERRCODE='42501'; END IF;
  UPDATE dation_private.dataset_uploads SET status='stored',updated_at=clock_timestamp() WHERE id=intent.id;
  RETURN jsonb_build_object('cleared',true,'stored',true);
 END IF;
 IF intent.status IN('stored','discarded') THEN RETURN jsonb_build_object('cleared',true); END IF;
 IF operation='stored' THEN RAISE EXCEPTION 'Stored dataset not found' USING ERRCODE='P0002'; END IF;
 IF operation='failed' THEN
  IF intent.status='pending' THEN UPDATE dation_private.dataset_uploads SET status='failed',updated_at=clock_timestamp() WHERE id=intent.id; END IF;
  RETURN jsonb_build_object('pending',true);
 END IF;
 IF operation='finish' THEN
  UPDATE dation_private.dataset_uploads SET status='discarded',updated_at=clock_timestamp() WHERE id=intent.id;
  RETURN jsonb_build_object('cleared',true);
 END IF;
 IF intent.status='pending' AND intent.created_at>now()-interval '15 minutes' THEN
  RAISE EXCEPTION 'Upload is still active' USING ERRCODE='55006'; END IF;
 UPDATE dation_private.dataset_uploads SET status='discarding',updated_at=clock_timestamp() WHERE id=intent.id;
 RETURN jsonb_build_object('cleared',false,'operation_id',intent.id,'dataset_id',intent.dataset_id,
  'storage_bucket',intent.storage_bucket,'storage_path',intent.storage_path);
END; $function$

CREATE OR REPLACE FUNCTION public.platform_decision_center(target_workspace_id uuid, actor_user_id uuid, target_case_id uuid DEFAULT NULL::uuid, filter_name text DEFAULT 'all'::text, search_text text DEFAULT ''::text, dda text DEFAULT 'all'::text, target_node_id text DEFAULT NULL::text, page_limit integer DEFAULT 25, page_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE current_case decision_cases; answer jsonb; history jsonb;
BEGIN
 PERFORM dation_private.data_actor(target_workspace_id,actor_user_id);
 PERFORM set_config('dation.workspace_id',target_workspace_id::text,true);
 IF filter_name NOT IN('all','in_progress','review','completed','archived') OR dda NOT IN('all','logistics')
 OR length(search_text)>120 OR page_limit NOT BETWEEN 1 AND 50 OR page_offset NOT BETWEEN 0 AND 1000000
 OR (target_node_id IS NOT NULL AND target_node_id NOT IN('logistics_assignment','logistics_scheduling','logistics_final_assignment')) THEN
  RAISE EXCEPTION 'Invalid center query' USING ERRCODE='22023'; END IF;
 IF target_case_id IS NOT NULL THEN
  SELECT * INTO current_case FROM decision_cases WHERE id=target_case_id AND workspace_id=target_workspace_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Case not found' USING ERRCODE='P0002'; END IF;
  answer=dation_private.center_bundle(current_case)||jsonb_build_object('collaboration',dation_private.case_collaboration(target_workspace_id,current_case.id,actor_user_id));
  IF target_node_id IS NOT NULL THEN
   SELECT coalesce(jsonb_agg(dation_private.center_run(r) ORDER BY r.created_at DESC,r.id DESC),'[]') INTO history
   FROM (SELECT * FROM decision_runs WHERE workspace_id=target_workspace_id AND decision_case_id=current_case.id AND node_id=target_node_id AND (search_text='' OR id::text=search_text)
     ORDER BY created_at DESC,id DESC LIMIT page_limit OFFSET page_offset) r;
   RETURN answer||jsonb_build_object('runs',history,'node_id',target_node_id,'limit',page_limit,'offset',page_offset);
  END IF;
  RETURN answer||jsonb_build_object('orders',(SELECT dation_private.hub_dataset(d) FROM datasets d WHERE id=current_case.orders_dataset_id AND workspace_id=target_workspace_id),
   'fleet',(SELECT dation_private.hub_dataset(d) FROM datasets d WHERE id=current_case.fleet_dataset_id AND workspace_id=target_workspace_id),
   'run_people',coalesce((SELECT jsonb_object_agg(r.id::text,dation_private.center_run(r)) FROM decision_runs r
    WHERE r.workspace_id=target_workspace_id AND r.decision_case_id=current_case.id AND r.id IN
     (SELECT (value->k->>'id')::uuid FROM jsonb_each(answer->'summaries') CROSS JOIN (VALUES('latest'),('approved')) v(k))),'{}'));
 END IF;
 WITH base AS MATERIALIZED (SELECT c.*,(dation_private.center_bundle(c)||jsonb_build_object('collaboration',dation_private.case_collaboration(target_workspace_id,c.id,actor_user_id))) bundle FROM decision_cases c WHERE c.workspace_id=target_workspace_id
  AND (dda='all' OR c.domain=dda) AND (search_text='' OR strpos(lower(concat_ws(' ',c.id::text,'DC-'||substr(c.id::text,1,8),c.label)),lower(search_text))>0)),
 matched AS (SELECT * FROM base WHERE CASE filter_name
  WHEN 'all' THEN bundle->>'status'<>'archived'
  WHEN 'archived' THEN bundle->>'status'='archived'
  WHEN 'completed' THEN bundle->>'status'='completed'
  WHEN 'review' THEN (bundle->>'in_review')::boolean
  ELSE bundle->>'status'='active' AND NOT (bundle->>'in_review')::boolean END),
 page AS (SELECT * FROM matched ORDER BY last_activity_at DESC,id DESC LIMIT page_limit OFFSET page_offset)
 SELECT jsonb_build_object('items',coalesce((SELECT jsonb_agg(bundle ORDER BY last_activity_at DESC,id DESC) FROM page),'[]'),
  'total',(SELECT count(*) FROM matched),'limit',page_limit,'offset',page_offset) INTO answer;
 RETURN answer;
END; $function$

CREATE OR REPLACE FUNCTION public.platform_identity(actor_user_id uuid, first_name text DEFAULT ''::text, last_name text DEFAULT ''::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE account auth.users; person profiles; membership workspace_members; workspace workspaces; legacy record; membership_count integer;
BEGIN
 IF NOT (SELECT admissions_open FROM dation_private.platform_release WHERE singleton) THEN RAISE EXCEPTION 'Platform access is being upgraded' USING ERRCODE='55000'; END IF;
 SELECT * INTO account FROM auth.users WHERE id=actor_user_id AND email_confirmed_at IS NOT NULL;
 IF NOT FOUND THEN RAISE EXCEPTION 'Confirmed identity required' USING ERRCODE='42501'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(actor_user_id::text,0));
 INSERT INTO profiles(id,first_name,last_name,display_name) VALUES(actor_user_id,left(first_name,100),left(last_name,100),trim(left(first_name,100)||' '||left(last_name,100)))
 ON CONFLICT(id) DO NOTHING;
 -- Only a confirmed, explicitly authorized email can claim the preserved workspace.
 FOR legacy IN SELECT * FROM dation_private.legacy_owners WHERE email=lower(account.email) AND claimed_by IS NULL FOR UPDATE LOOP
  INSERT INTO workspace_members(workspace_id,user_id,access_role,status,joined_at)
   VALUES(legacy.workspace_id,actor_user_id,'admin','active',now()) ON CONFLICT DO NOTHING;
  UPDATE dation_private.legacy_owners SET claimed_by=actor_user_id WHERE email=legacy.email;
  UPDATE workspaces SET created_by=actor_user_id,updated_at=now() WHERE id=legacy.workspace_id AND created_by IS NULL;
  UPDATE profiles SET active_workspace_id=legacy.workspace_id WHERE id=actor_user_id;
  INSERT INTO audit_events(workspace_id,actor_user_id,event_type) VALUES(legacy.workspace_id,actor_user_id,'workspace.legacy_claimed');
 END LOOP;
 SELECT * INTO person FROM profiles WHERE id=actor_user_id;
 SELECT count(*) INTO membership_count FROM workspace_members m JOIN workspaces w ON w.id=m.workspace_id
  WHERE m.user_id=actor_user_id AND m.status='active' AND w.status='active';
 IF membership_count=1 THEN
  SELECT m.* INTO membership FROM workspace_members m JOIN workspaces w ON w.id=m.workspace_id
   WHERE m.user_id=actor_user_id AND m.status='active' AND w.status='active';
 ELSIF membership_count>1 THEN
  SELECT m.* INTO membership FROM workspace_members m JOIN workspaces w ON w.id=m.workspace_id
   WHERE m.user_id=actor_user_id AND m.workspace_id=person.active_workspace_id AND m.status='active' AND w.status='active';
  IF NOT FOUND THEN RAISE EXCEPTION 'Multiple memberships require an administrator-selected active workspace' USING ERRCODE='42501'; END IF;
 ELSIF EXISTS(SELECT 1 FROM workspace_members WHERE user_id=actor_user_id) THEN
  RAISE EXCEPTION 'No active membership' USING ERRCODE='42501';
 END IF;
 IF membership.workspace_id IS NOT NULL THEN
  SELECT * INTO workspace FROM workspaces WHERE id=membership.workspace_id;
 END IF;
 RETURN jsonb_build_object('profile',to_jsonb(person)||jsonb_build_object('email',account.email),
   'membership',CASE WHEN membership.workspace_id IS NULL THEN NULL ELSE to_jsonb(membership) END,
   'workspace',CASE WHEN workspace.id IS NULL THEN NULL ELSE to_jsonb(workspace) END,
   'ddas',coalesce((SELECT jsonb_agg(to_jsonb(d)) FROM workspace_ddas d WHERE d.workspace_id=membership.workspace_id),'[]'));
END; $function$

CREATE OR REPLACE FUNCTION public.platform_invite_member(target_workspace_id uuid, actor_user_id uuid, invite_email text, invite_role text, invite_business_role text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE invitation workspace_invitations;
BEGIN
 PERFORM 1 FROM workspaces WHERE id=target_workspace_id FOR UPDATE;
 PERFORM dation_private.team_actor(target_workspace_id,actor_user_id,true);
 IF invite_email IS NULL OR invite_role IS NULL OR invite_email<>lower(trim(invite_email)) OR length(invite_email)>254 OR invite_email !~ '^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$'
 OR invite_role NOT IN('admin','operator','viewer') OR (invite_business_role IS NOT NULL AND invite_business_role NOT IN('data_owner','data_steward','decision_owner','approver')) THEN RAISE EXCEPTION 'Invalid invitation' USING ERRCODE='22023'; END IF;
 IF EXISTS(SELECT 1 FROM workspace_members m JOIN auth.users u ON u.id=m.user_id WHERE m.workspace_id=target_workspace_id AND lower(u.email)=invite_email) THEN
 RAISE EXCEPTION 'Member already exists; manage the member instead' USING ERRCODE='22023'; END IF;
 -- Revoke expired invitations before issuing a fresh one; active duplicates fail.
 UPDATE workspace_invitations SET status='revoked',updated_at=clock_timestamp() WHERE workspace_id=target_workspace_id AND email=invite_email AND status='pending' AND expires_at<=now();
 IF EXISTS(SELECT 1 FROM workspace_invitations WHERE workspace_id=target_workspace_id AND email=invite_email AND status='pending') THEN RAISE EXCEPTION 'Invitation already pending' USING ERRCODE='22023'; END IF;
 INSERT INTO workspace_invitations(workspace_id,email,access_role,business_role,invited_by) VALUES(target_workspace_id,invite_email,invite_role,invite_business_role,actor_user_id) RETURNING * INTO invitation;
 INSERT INTO audit_events(workspace_id,actor_user_id,event_type,metadata_json) VALUES(target_workspace_id,actor_user_id,'team.invited',jsonb_build_object('invitation_id',invitation.id,'email',invite_email,'access_role',invite_role,'business_role',invite_business_role));
 RETURN jsonb_build_object('id',invitation.id,'email',invitation.email,'expires_at',invitation.expires_at,'updated_at',invitation.updated_at);
END; $function$

CREATE OR REPLACE FUNCTION public.platform_onboarding(target_workspace_id uuid, actor_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE explored timestamptz; enabled boolean; prepared boolean=false; first_run decision_runs;
BEGIN
 PERFORM dation_private.team_actor(target_workspace_id,actor_user_id);
 SELECT explored_at INTO explored FROM dation_private.workspace_onboarding
 WHERE workspace_id=target_workspace_id AND user_id=actor_user_id;
 SELECT EXISTS(SELECT 1 FROM workspace_ddas WHERE workspace_id=target_workspace_id AND dda_id='logistics' AND status='enabled') INTO enabled;
 IF enabled THEN
  SELECT EXISTS(SELECT 1 FROM datasets WHERE workspace_id=target_workspace_id AND dataset_type='orders' AND archived_at IS NULL AND deletion_requested_at IS NULL AND profile_json->'valid'='true')
   AND EXISTS(SELECT 1 FROM datasets WHERE workspace_id=target_workspace_id AND dataset_type='fleet' AND archived_at IS NULL AND deletion_requested_at IS NULL AND profile_json->'valid'='true') INTO prepared;
  SELECT * INTO first_run FROM decision_runs WHERE workspace_id=target_workspace_id AND status='completed' AND node_id IN('logistics_assignment','logistics_scheduling') ORDER BY created_at,id LIMIT 1;
 END IF;
 RETURN jsonb_build_object('available',true,'workspace_created',true,'explored_at',explored,'data_ready',prepared,
  'first_decision_completed',first_run.id IS NOT NULL,'logistics_enabled',enabled,
  'data_includes_demo',prepared AND EXISTS(SELECT 1 FROM datasets WHERE workspace_id=target_workspace_id AND dataset_type IN('orders','fleet') AND is_sample AND archived_at IS NULL AND deletion_requested_at IS NULL AND profile_json->'valid'='true'),
  'first_decision_demo',EXISTS(SELECT 1 FROM datasets WHERE workspace_id=target_workspace_id AND is_sample AND id IN(first_run.orders_dataset_id,first_run.fleet_dataset_id,first_run.dataset_id)));
END; $function$

CREATE OR REPLACE FUNCTION public.platform_received_invitations(actor_user_id uuid, invitation_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE account auth.users; invitation workspace_invitations; member workspace_members;
BEGIN
 IF NOT coalesce((SELECT admissions_open FROM dation_private.platform_release WHERE singleton),false) THEN RAISE EXCEPTION 'Admissions closed' USING ERRCODE='42501'; END IF;
 SELECT * INTO account FROM auth.users WHERE id=actor_user_id AND email_confirmed_at IS NOT NULL;
 IF NOT FOUND THEN RAISE EXCEPTION 'Confirmed identity required' USING ERRCODE='42501'; END IF;
 IF invitation_id IS NULL THEN
 RETURN jsonb_build_object('items',coalesce((SELECT jsonb_agg(to_jsonb(i)) FROM (
 SELECT i.id,w.name AS workspace_name,i.access_role,i.business_role,i.expires_at FROM workspace_invitations i JOIN workspaces w ON w.id=i.workspace_id
 WHERE i.email=lower(account.email) AND i.status='pending' AND i.expires_at>now() AND w.status='active'
 AND EXISTS(SELECT 1 FROM workspace_members m WHERE m.workspace_id=i.workspace_id AND m.user_id=i.invited_by AND m.status='active' AND m.access_role='admin')
 ORDER BY i.created_at DESC,i.id LIMIT 50) i),'[]'));
 END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(actor_user_id::text,0));
 SELECT * INTO invitation FROM workspace_invitations WHERE id=invitation_id AND email=lower(account.email);
 IF NOT FOUND THEN RAISE EXCEPTION 'Invitation not found' USING ERRCODE='P0002'; END IF;
 PERFORM 1 FROM workspaces WHERE id=invitation.workspace_id AND status='active' FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Workspace unavailable' USING ERRCODE='42501'; END IF;
 SELECT * INTO invitation FROM workspace_invitations WHERE id=invitation_id FOR UPDATE;
 IF invitation.status='accepted' AND invitation.accepted_by=actor_user_id THEN
 PERFORM dation_private.team_actor(invitation.workspace_id,actor_user_id);
 RETURN jsonb_build_object('workspace_id',invitation.workspace_id,'already_accepted',true);
 END IF;
 IF invitation.status<>'pending' OR invitation.expires_at<=now() THEN RAISE EXCEPTION 'Invitation expired or revoked' USING ERRCODE='22023'; END IF;
 PERFORM dation_private.team_actor(invitation.workspace_id,invitation.invited_by,true);
 IF EXISTS(SELECT 1 FROM workspace_members WHERE workspace_id=invitation.workspace_id AND user_id=actor_user_id) THEN RAISE EXCEPTION 'Existing member cannot accept an invitation' USING ERRCODE='22023'; END IF;
 INSERT INTO profiles(id) VALUES(actor_user_id) ON CONFLICT DO NOTHING;
 INSERT INTO workspace_members(workspace_id,user_id,access_role,business_role,invited_by,joined_at)
 VALUES(invitation.workspace_id,actor_user_id,invitation.access_role,invitation.business_role,invitation.invited_by,clock_timestamp());
 UPDATE profiles SET active_workspace_id=invitation.workspace_id,updated_at=clock_timestamp() WHERE id=actor_user_id;
 UPDATE workspace_invitations SET status='accepted',accepted_by=actor_user_id,accepted_at=clock_timestamp(),updated_at=clock_timestamp() WHERE id=invitation_id;
 INSERT INTO audit_events(workspace_id,actor_user_id,event_type,metadata_json) VALUES(invitation.workspace_id,actor_user_id,'team.invitation_accepted',jsonb_build_object('invitation_id',invitation_id,'access_role',invitation.access_role,'business_role',invitation.business_role));
 RETURN jsonb_build_object('workspace_id',invitation.workspace_id,'already_accepted',false);
END; $function$

CREATE OR REPLACE FUNCTION public.platform_record_export(target_workspace_id uuid, actor_user_id uuid, target_run_id uuid, export_format text, operation_id uuid, content_sha256 text, content_bytes integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE r decision_runs; previous audit_events; key text;
BEGIN
 PERFORM dation_private.team_actor(target_workspace_id,actor_user_id);
 IF NOT EXISTS(SELECT 1 FROM workspace_ddas WHERE workspace_id=target_workspace_id AND dda_id='logistics' AND status='enabled') THEN RAISE EXCEPTION 'DDA not enabled' USING ERRCODE='42501'; END IF;
 SELECT * INTO r FROM decision_runs WHERE id=target_run_id AND workspace_id=target_workspace_id AND status='completed';
 IF NOT FOUND THEN RAISE EXCEPTION 'Exportable run not found' USING ERRCODE='P0002'; END IF;
 IF export_format IS NULL OR export_format NOT IN('csv','json') OR operation_id IS NULL OR content_sha256 IS NULL OR content_sha256 !~ '^[a-f0-9]{64}$' OR content_bytes IS NULL OR content_bytes<1 THEN RAISE EXCEPTION 'Invalid export' USING ERRCODE='22023'; END IF;
 key='export:'||actor_user_id::text||':'||operation_id::text;
 INSERT INTO audit_events(workspace_id,actor_user_id,event_type,object_type,object_id,decision_case_id,node_id,event_key,metadata_json)
 VALUES(target_workspace_id,actor_user_id,'export.generated','run',r.id,r.decision_case_id,r.node_id,key,
  jsonb_build_object('format',export_format,'bytes',content_bytes,'sha256',content_sha256)) ON CONFLICT(workspace_id,event_key) WHERE event_key IS NOT NULL DO NOTHING;
 SELECT * INTO previous FROM audit_events WHERE workspace_id=target_workspace_id AND event_key=key;
 IF previous.object_id<>r.id OR previous.metadata_json->>'format'<>export_format OR previous.metadata_json->>'sha256'<>content_sha256 THEN RAISE EXCEPTION 'Export request changed' USING ERRCODE='55006'; END IF;
 RETURN jsonb_build_object('id',previous.id);
END; $function$

CREATE OR REPLACE FUNCTION public.platform_replace_case_data_pack(target_workspace_id uuid, actor_user_id uuid, target_case_id uuid, expected_updated_at timestamp with time zone, orders_id uuid, fleet_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE c decision_cases; next_case decision_cases; next_id uuid;
BEGIN
 PERFORM dation_private.data_actor(target_workspace_id,actor_user_id,true);
 PERFORM set_config('dation.workspace_id',target_workspace_id::text,true);
 PERFORM set_config('dation.actor_user_id',actor_user_id::text,true);
 PERFORM 1 FROM workspaces WHERE id=target_workspace_id FOR UPDATE;
 SELECT * INTO c FROM decision_cases WHERE workspace_id=target_workspace_id AND id=target_case_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Case not found' USING ERRCODE='P0002'; END IF;
 IF expected_updated_at IS DISTINCT FROM c.updated_at THEN RAISE EXCEPTION 'Case changed; refresh' USING ERRCODE='55006'; END IF;
 IF NOT EXISTS(SELECT 1 FROM datasets WHERE workspace_id=target_workspace_id AND id=orders_id AND dataset_type='orders' AND deletion_requested_at IS NULL)
 OR NOT EXISTS(SELECT 1 FROM datasets WHERE workspace_id=target_workspace_id AND id=fleet_id AND dataset_type='fleet' AND deletion_requested_at IS NULL) THEN
  RAISE EXCEPTION 'Invalid Data Pack' USING ERRCODE='22023'; END IF;
 IF (c.orders_dataset_id,c.fleet_dataset_id)=(orders_id,fleet_id) THEN
  RETURN jsonb_build_object('id',c.id,'updated_at',c.updated_at,'created',false);
 END IF;
 -- Stable per source Case/Data Pack so a network retry cannot duplicate the fork.
 next_id=md5(target_workspace_id::text||target_case_id::text||orders_id::text||fleet_id::text)::uuid;
 INSERT INTO decision_cases(id,workspace_id,schema_version,domain,status,orders_dataset_id,fleet_dataset_id,input_signature,label,category,description,state_json)
 VALUES(next_id,target_workspace_id,'decision_case_v2',c.domain,'active',orders_id,fleet_id,orders_id::text||':'||fleet_id::text,c.label,c.category,c.description,'{}'::jsonb)
 ON CONFLICT(id) DO NOTHING;
 SELECT * INTO STRICT next_case FROM decision_cases WHERE workspace_id=target_workspace_id AND id=next_id
  AND orders_dataset_id=orders_id AND fleet_dataset_id=fleet_id;
 RETURN jsonb_build_object('id',next_case.id,'updated_at',next_case.updated_at,'created',true,'predecessor_id',c.id);
END; $function$

CREATE OR REPLACE FUNCTION public.platform_revoke_invitation(target_workspace_id uuid, actor_user_id uuid, invitation_id uuid, expected_updated_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE invitation workspace_invitations;
BEGIN
 PERFORM 1 FROM workspaces WHERE id=target_workspace_id FOR UPDATE;
 PERFORM dation_private.team_actor(target_workspace_id,actor_user_id,true);
 SELECT * INTO invitation FROM workspace_invitations WHERE workspace_id=target_workspace_id AND id=invitation_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Invitation not found' USING ERRCODE='P0002'; END IF;
 IF invitation.status<>'pending' OR invitation.updated_at IS DISTINCT FROM expected_updated_at THEN RAISE EXCEPTION 'Invitation changed' USING ERRCODE='55006'; END IF;
 UPDATE workspace_invitations SET status='revoked',updated_at=clock_timestamp() WHERE id=invitation_id;
 INSERT INTO audit_events(workspace_id,actor_user_id,event_type,metadata_json) VALUES(target_workspace_id,actor_user_id,'team.invitation_revoked',jsonb_build_object('invitation_id',invitation_id));
 RETURN jsonb_build_object('id',invitation_id,'status','revoked');
END; $function$

CREATE OR REPLACE FUNCTION public.platform_rpc(target_workspace_id uuid, actor_user_id uuid, operation text, arguments jsonb DEFAULT '{}'::jsonb, worker_call boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE member_role text; answer jsonb; payload jsonb; is_read boolean;
BEGIN
 IF target_workspace_id IS NULL OR jsonb_typeof(arguments) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'Invalid context' USING ERRCODE='42501'; END IF;
 PERFORM set_config('dation.workspace_id',target_workspace_id::text,true);
 PERFORM set_config('dation.actor_user_id',coalesce(actor_user_id::text,''),true);
 is_read=operation IN('list_decision_cases','decision_case_history','read_decision_chat_turn','read_decision_chat_turn_with_evidence','current_decision_explanation',
  'dispatch_operational_snapshot','comparative_operational_snapshot');
 IF worker_call THEN
  IF actor_user_id IS NOT NULL OR operation NOT IN('heartbeat_dispatch_job','finish_dispatch_job','heartbeat_comparative_analysis','finish_comparative_analysis','ack_case_reconciliation','decision_case_history') THEN
   RAISE EXCEPTION 'Worker operation denied' USING ERRCODE='42501'; END IF;
 ELSE
  SELECT m.access_role INTO member_role FROM workspace_members m JOIN workspaces w ON w.id=m.workspace_id
   WHERE m.workspace_id=target_workspace_id AND m.user_id=actor_user_id AND m.status='active' AND w.status='active';
  IF NOT FOUND OR (member_role='viewer' AND NOT is_read) THEN RAISE EXCEPTION 'Membership denied' USING ERRCODE='42501'; END IF;
  IF operation IN('dispatch_operational_snapshot','comparative_operational_snapshot') AND member_role<>'admin' THEN RAISE EXCEPTION 'Admin required' USING ERRCODE='42501'; END IF;
 END IF;
 PERFORM dation_private.assert_owned('decision_runs',(arguments->>'target_run_id')::uuid,target_workspace_id);
 PERFORM dation_private.assert_owned('decision_cases',(arguments->>'target_case_id')::uuid,target_workspace_id);
 PERFORM dation_private.assert_owned('decision_runs',(arguments->>'target_base_id')::uuid,target_workspace_id);
 PERFORM dation_private.assert_owned('decision_comparative_analyses',(arguments->>'target_analysis_id')::uuid,target_workspace_id);
 PERFORM dation_private.assert_owned('datasets',(arguments->>'target_id')::uuid,target_workspace_id);
 PERFORM dation_private.assert_owned('decision_chat_turns',(arguments->>'target_turn_id')::uuid,target_workspace_id,true);
 PERFORM dation_private.assert_owned('decision_comparative_analyses',(arguments->>'evidence_analysis_id')::uuid,target_workspace_id);
 IF arguments ? 'explanation' THEN
  PERFORM dation_private.assert_owned('decision_runs',(arguments->'explanation'->>'run_id')::uuid,target_workspace_id);
  PERFORM dation_private.assert_owned('decision_explanations',(arguments->'explanation'->>'id')::uuid,target_workspace_id,true);
 END IF;
 IF operation='enqueue_dispatch_run' THEN
  payload=arguments->'run_payload';
  PERFORM dation_private.assert_owned('decision_runs',(payload->>'id')::uuid,target_workspace_id,true);
  PERFORM dation_private.check_json_references(payload-'id',target_workspace_id);
  IF arguments->'job_request'->>'workspace_id' IS DISTINCT FROM target_workspace_id::text THEN RAISE EXCEPTION 'Invalid job workspace' USING ERRCODE='42501'; END IF;
 END IF;
 CASE operation
 WHEN 'list_decision_cases' THEN SELECT coalesce(jsonb_agg(to_jsonb(result)),'[]') INTO answer FROM dation_private.list_decision_cases(coalesce((arguments->>'case_status')::text,'active'),coalesce((arguments->>'page_limit')::integer,50),coalesce((arguments->>'page_offset')::integer,0),coalesce((arguments->>'summary_only')::boolean,false)) result;
 WHEN 'decision_case_history' THEN SELECT to_jsonb(dation_private.decision_case_history((arguments->>'target_case_id')::uuid,(arguments->>'target_node_id')::text,coalesce((arguments->>'page_limit')::integer,50),coalesce((arguments->>'page_offset')::integer,0))) INTO answer;
 WHEN 'approve_decision_run_version' THEN SELECT coalesce(jsonb_agg(to_jsonb(result)),'[]') INTO answer FROM dation_private.approve_decision_run_version((arguments->>'target_run_id')::uuid,(arguments->>'target_case_id')::uuid,(arguments->>'target_node_id')::text) result;
 WHEN 'enqueue_dispatch_run' THEN SELECT coalesce(jsonb_agg(to_jsonb(result)),'[]') INTO answer FROM dation_private.enqueue_dispatch_run(nullif(arguments->'run_payload','null'::jsonb),nullif(arguments->'job_request','null'::jsonb),(arguments->>'intent_fingerprint')::text,coalesce((arguments->>'queue_limit')::integer,32)) result;
 WHEN 'cancel_dispatch_job' THEN SELECT coalesce(jsonb_agg(to_jsonb(result)),'[]') INTO answer FROM dation_private.cancel_dispatch_job((arguments->>'target_run_id')::uuid) result;
 WHEN 'heartbeat_dispatch_job' THEN SELECT to_jsonb(dation_private.heartbeat_dispatch_job((arguments->>'target_run_id')::uuid,(arguments->>'worker_token')::uuid,coalesce((arguments->>'lease_seconds')::integer,120),nullif(arguments->'progress','null'::jsonb))) INTO answer;
 WHEN 'finish_dispatch_job' THEN SELECT coalesce(jsonb_agg(to_jsonb(result)),'[]') INTO answer FROM dation_private.finish_dispatch_job((arguments->>'target_run_id')::uuid,(arguments->>'worker_token')::uuid,nullif(arguments->'terminal_values','null'::jsonb)) result;
 WHEN 'ack_case_reconciliation' THEN PERFORM dation_private.ack_case_reconciliation((arguments->>'target_case_id')::uuid,(arguments->>'observed_version')::bigint); answer='null'::jsonb;
 WHEN 'request_case_reconciliation' THEN PERFORM dation_private.request_case_reconciliation((arguments->>'target_case_id')::uuid); answer='null'::jsonb;
 WHEN 'set_default_fleet' THEN PERFORM dation_private.set_default_fleet((arguments->>'target_id')::uuid); answer='null'::jsonb;
 WHEN 'enqueue_comparative_analysis' THEN SELECT coalesce(jsonb_agg(to_jsonb(result)),'[]') INTO answer FROM dation_private.enqueue_comparative_analysis((arguments->>'target_base_id')::uuid,nullif(arguments->'job_request','null'::jsonb),nullif(arguments->'existing_result','null'::jsonb),coalesce((arguments->>'retry_failed')::boolean,false)) result;
 WHEN 'heartbeat_comparative_analysis' THEN SELECT to_jsonb(dation_private.heartbeat_comparative_analysis((arguments->>'target_analysis_id')::uuid,(arguments->>'worker_token')::uuid,coalesce((arguments->>'lease_seconds')::integer,120),nullif(arguments->'progress','null'::jsonb))) INTO answer;
 WHEN 'finish_comparative_analysis' THEN SELECT coalesce(jsonb_agg(to_jsonb(result)),'[]') INTO answer FROM dation_private.finish_comparative_analysis((arguments->>'target_analysis_id')::uuid,(arguments->>'worker_token')::uuid,nullif(arguments->'terminal_values','null'::jsonb)) result;
 WHEN 'read_decision_chat_turn' THEN SELECT to_jsonb(dation_private.read_decision_chat_turn((arguments->>'target_turn_id')::uuid,(arguments->>'target_run_id')::uuid,(arguments->>'intent_hash')::text)) INTO answer;
 WHEN 'read_decision_chat_turn_with_evidence' THEN SELECT to_jsonb(dation_private.read_decision_chat_turn_with_evidence((arguments->>'target_turn_id')::uuid,(arguments->>'target_run_id')::uuid,(arguments->>'intent_hash')::text)) INTO answer;
 WHEN 'record_decision_chat_turn' THEN SELECT to_jsonb(dation_private.record_decision_chat_turn((arguments->>'target_turn_id')::uuid,(arguments->>'target_run_id')::uuid,(arguments->>'intent_hash')::text,(arguments->>'question_text')::text,(arguments->>'answer_text')::text,nullif(arguments->'metadata','null'::jsonb))) INTO answer;
 WHEN 'record_decision_chat_turn_with_evidence' THEN SELECT to_jsonb(dation_private.record_decision_chat_turn_with_evidence((arguments->>'target_turn_id')::uuid,(arguments->>'target_run_id')::uuid,(arguments->>'intent_hash')::text,(arguments->>'question_text')::text,(arguments->>'answer_text')::text,nullif(arguments->'metadata','null'::jsonb),(arguments->>'evidence_analysis_id')::uuid)) INTO answer;
 WHEN 'record_decision_explanation_with_evidence' THEN SELECT coalesce(jsonb_agg(to_jsonb(result)),'[]') INTO answer FROM dation_private.record_decision_explanation_with_evidence(nullif(arguments->'explanation','null'::jsonb),(arguments->>'evidence_analysis_id')::uuid) result;
 WHEN 'current_decision_explanation' THEN SELECT coalesce(jsonb_agg(to_jsonb(result)),'[]') INTO answer FROM dation_private.current_decision_explanation((arguments->>'target_run_id')::uuid) result;
 WHEN 'dispatch_operational_snapshot' THEN SELECT to_jsonb(dation_private.dispatch_operational_snapshot()) INTO answer;
 WHEN 'comparative_operational_snapshot' THEN SELECT to_jsonb(dation_private.comparative_operational_snapshot()) INTO answer;
 ELSE RAISE EXCEPTION 'Operation denied' USING ERRCODE='42501';
 END CASE;
 RETURN answer;
END; $function$

CREATE OR REPLACE FUNCTION public.platform_set_member_responsibilities(target_workspace_id uuid, actor_user_id uuid, member_user_id uuid, expected_updated_at timestamp with time zone, new_responsibilities text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE member public.workspace_members; roles text[]; previous text[];
BEGIN
 PERFORM 1 FROM public.workspaces WHERE id=target_workspace_id FOR UPDATE;
 PERFORM dation_private.team_actor(target_workspace_id,actor_user_id,true);
 SELECT * INTO member FROM public.workspace_members WHERE workspace_id=target_workspace_id AND user_id=member_user_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Member not found' USING ERRCODE='P0002'; END IF;
 IF expected_updated_at IS NULL OR member.updated_at IS DISTINCT FROM expected_updated_at THEN RAISE EXCEPTION 'Member changed' USING ERRCODE='55006'; END IF;
 IF new_responsibilities IS NULL OR cardinality(new_responsibilities)>4 OR array_position(new_responsibilities,NULL) IS NOT NULL OR NOT new_responsibilities <@ ARRAY['data_owner','data_steward','decision_owner','approver'] THEN RAISE EXCEPTION 'Invalid responsibilities' USING ERRCODE='22023'; END IF;
 SELECT coalesce(array_agg(DISTINCT value ORDER BY value),'{}') INTO roles FROM unnest(new_responsibilities) t(value);
 IF cardinality(roles)<>cardinality(new_responsibilities) THEN RAISE EXCEPTION 'Duplicate responsibility' USING ERRCODE='22023'; END IF;
 previous=dation_private.member_roles(target_workspace_id,member_user_id);
 IF roles=previous THEN RETURN jsonb_build_object('business_roles',roles,'updated_at',member.updated_at); END IF;
 UPDATE public.workspace_members SET business_role=roles[1],updated_at=clock_timestamp() WHERE workspace_id=target_workspace_id AND user_id=member_user_id RETURNING * INTO member;
 DELETE FROM dation_private.member_responsibilities WHERE workspace_id=target_workspace_id AND user_id=member_user_id;
 INSERT INTO dation_private.member_responsibilities SELECT target_workspace_id,member_user_id,value FROM unnest(roles) t(value);
 INSERT INTO public.audit_events(workspace_id,actor_user_id,event_type,object_type,object_id,metadata_json) VALUES(target_workspace_id,actor_user_id,'member.responsibilities_changed','member',member_user_id,jsonb_build_object('user_id',member_user_id,'previous',previous,'responsibilities',roles));
 RETURN jsonb_build_object('business_roles',roles,'updated_at',member.updated_at);
END; $function$

CREATE OR REPLACE FUNCTION public.platform_team_foundation(target_workspace_id uuid, actor_user_id uuid, search_text text DEFAULT ''::text, page_limit integer DEFAULT 25, page_offset integer DEFAULT 0, candidates_only boolean DEFAULT false, responsibility_group text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE answer jsonb; members jsonb; total bigint;
BEGIN
 PERFORM dation_private.team_actor(target_workspace_id,actor_user_id);
 IF responsibility_group IS NULL THEN
  answer=public.platform_team(target_workspace_id,actor_user_id,search_text,page_limit,page_offset,candidates_only);
  SELECT coalesce(jsonb_agg(value||jsonb_build_object('business_roles',dation_private.member_roles(target_workspace_id,(value->>'user_id')::uuid)) ORDER BY ordinal),'[]') INTO members FROM jsonb_array_elements(answer->'members') WITH ORDINALITY e(value,ordinal);
  RETURN answer||jsonb_build_object('members',members);
 END IF;
 IF NOT candidates_only OR responsibility_group NOT IN('data','data_owner','data_steward','decision_owner','approver') OR search_text IS NULL OR length(search_text)>120 OR page_limit IS NULL OR page_limit NOT BETWEEN 1 AND 50 OR page_offset IS NULL OR page_offset NOT BETWEEN 0 AND 1000000 THEN RAISE EXCEPTION 'Invalid candidates query' USING ERRCODE='22023'; END IF;
 WITH matched AS MATERIALIZED (
  SELECT m.*,u.email,coalesce(nullif(p.display_name,''),'Miembro del equipo') name,dation_private.member_roles(m.workspace_id,m.user_id) business_roles
  FROM public.workspace_members m JOIN auth.users u ON u.id=m.user_id LEFT JOIN public.profiles p ON p.id=m.user_id
  WHERE m.workspace_id=target_workspace_id AND dation_private.responsibility_eligible(target_workspace_id,m.user_id,responsibility_group)
   AND (search_text='' OR strpos(lower(concat_ws(' ',p.display_name,u.email)),lower(search_text))>0)),
 page AS (SELECT * FROM matched ORDER BY name,user_id LIMIT page_limit OFFSET page_offset)
 SELECT coalesce((SELECT jsonb_agg(to_jsonb(p) ORDER BY name,user_id) FROM page p),'[]'),(SELECT count(*) FROM matched) INTO members,total;
 RETURN jsonb_build_object('members',members,'invitations','[]'::jsonb,'total',total,'invitation_total',0,'limit',page_limit,'offset',page_offset);
END; $function$

CREATE OR REPLACE FUNCTION public.platform_ultimate_copilot(target_workspace_id uuid, actor_user_id uuid, target_run_id uuid, target_turn_id uuid, intent_hash text, operation text, payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE role_name text; r public.decision_runs; t public.decision_chat_turns;
 source public.decision_interpretation_sources; answer jsonb; stamp timestamptz;
 intent jsonb=payload->'intent'; receipt jsonb=payload->'receipt';
BEGIN
 role_name=dation_private.team_actor(target_workspace_id,actor_user_id);
 IF (role_name='viewer' AND operation<>'history') OR operation NOT IN('read','record','history') OR operation IS NULL
    OR target_turn_id IS NULL OR intent_hash IS NULL OR intent_hash !~ '^[0-9a-f]{64}$' THEN
  RAISE EXCEPTION 'Copilot access or request denied' USING ERRCODE='42501'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.workspace_ddas WHERE workspace_id=target_workspace_id AND dda_id='logistics' AND status='enabled') THEN
  RAISE EXCEPTION 'DDA unavailable' USING ERRCODE='42501'; END IF;
 SELECT * INTO r FROM public.decision_runs WHERE workspace_id=target_workspace_id AND id=target_run_id FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Run access denied' USING ERRCODE='42501'; END IF;
 IF r.workflow_version<>2 OR r.status<>'completed' OR r.result_package_version IS DISTINCT FROM 1 THEN
  RAISE EXCEPTION 'Published Run required' USING ERRCODE='22023'; END IF;
 IF operation='history' THEN
  IF coalesce((payload->>'offset')::integer,0) NOT BETWEEN 0 AND 1000000 THEN
   RAISE EXCEPTION 'Invalid history page' USING ERRCODE='22023'; END IF;
  SELECT coalesce(jsonb_agg(x.body ORDER BY x.created_at DESC,x.turn_id),'[]') INTO answer FROM (
   SELECT history_turn.created_at,history_turn.turn_id,jsonb_build_object('turn_id',history_turn.turn_id,'created_at',history_turn.created_at,
    'question',q.content,'receipt',m.content::jsonb,'prompt_version',history_turn.prompt_version,'provider',history_turn.provider,'model',history_turn.model) AS body
   FROM public.decision_chat_turns history_turn JOIN public.decision_messages m ON m.turn_id=history_turn.turn_id AND m.role='assistant' AND m.workspace_id=target_workspace_id
   JOIN public.decision_messages q ON q.turn_id=history_turn.turn_id AND q.role='user' AND q.workspace_id=target_workspace_id
   JOIN public.decision_interpretation_sources s ON s.chat_turn_id=history_turn.turn_id AND s.workspace_id=target_workspace_id
    AND s.run_id=r.id AND s.result_fingerprint=r.result_fingerprint AND s.provenance_version=2
   WHERE history_turn.workspace_id=target_workspace_id AND history_turn.run_id=r.id ORDER BY history_turn.created_at DESC,history_turn.turn_id LIMIT 21 OFFSET coalesce((payload->>'offset')::integer,0)
  ) x;
  RETURN jsonb_build_object('rows',CASE WHEN jsonb_array_length(answer)>20 THEN answer-20 ELSE answer END,
    'offset',coalesce((payload->>'offset')::integer,0),'next_offset',CASE WHEN jsonb_array_length(answer)>20 THEN coalesce((payload->>'offset')::integer,0)+20 END);
 END IF;
 -- Per-turn serialization preserves exact intent replay without provider reruns.
 PERFORM pg_advisory_xact_lock(hashtextextended(target_turn_id::text,0));
 SELECT * INTO t FROM public.decision_chat_turns WHERE turn_id=target_turn_id;
 IF FOUND THEN
  IF t.workspace_id IS DISTINCT FROM target_workspace_id OR t.run_id IS DISTINCT FROM target_run_id OR t.question_hash IS DISTINCT FROM intent_hash THEN
   RAISE EXCEPTION 'Turn intention conflict' USING ERRCODE='22023'; END IF;
  SELECT * INTO source FROM public.decision_interpretation_sources WHERE chat_turn_id=target_turn_id AND workspace_id=target_workspace_id AND provenance_version=2;
  IF NOT FOUND OR source.result_fingerprint IS DISTINCT FROM r.result_fingerprint THEN
   RAISE EXCEPTION 'Turn provenance conflict' USING ERRCODE='22023'; END IF;
  SELECT content::jsonb INTO STRICT answer FROM public.decision_messages
   WHERE turn_id=target_turn_id AND workspace_id=target_workspace_id AND role='assistant';
  RETURN answer;
 END IF;
 IF operation='read' THEN RETURN NULL; END IF;
 IF intent IS NULL OR receipt IS NULL OR jsonb_typeof(receipt)<>'object'
  OR octet_length(receipt::text)>20000 OR length(intent->>'question') NOT BETWEEN 1 AND 4000
  OR intent->>'schema_version' IS DISTINCT FROM 'decision_intent_v2'
  OR intent#>>'{provenance,run_id}' IS DISTINCT FROM target_run_id::text
  OR intent#>>'{provenance,result_fingerprint}' IS DISTINCT FROM r.result_fingerprint
  OR receipt->'provenance' IS DISTINCT FROM intent->'provenance'
  OR receipt->>'context_hash' IS DISTINCT FROM intent->>'context_hash'
  OR receipt->>'mode' IS DISTINCT FROM intent->>'mode'
  OR receipt->'selected_entity' IS DISTINCT FROM intent->'selected_entity'
  OR payload->>'prompt_version' IS DISTINCT FROM 'ULTIMATE_APPROVAL_COPILOT_V1'
  OR jsonb_typeof(payload->'evidence_refs') IS DISTINCT FROM 'array' THEN
  RAISE EXCEPTION 'Invalid Copilot provenance' USING ERRCODE='22023'; END IF;
 stamp=clock_timestamp();
 INSERT INTO public.decision_chat_turns(workspace_id,turn_id,run_id,question_hash,created_at,provider,model,knowledge_version,prompt_version)
 VALUES(target_workspace_id,target_turn_id,target_run_id,intent_hash,stamp,receipt#>>'{provider_info,provider}',receipt#>>'{provider_info,model}','DATION_REASONS_V1','ULTIMATE_APPROVAL_COPILOT_V1');
 INSERT INTO public.decision_messages(workspace_id,run_id,created_at,role,content,provider,model,knowledge_version,turn_id) VALUES
 (target_workspace_id,target_run_id,stamp,'user',intent->>'question',NULL,NULL,'DATION_REASONS_V1',target_turn_id),
 (target_workspace_id,target_run_id,stamp+interval '1 microsecond','assistant',receipt::text,receipt#>>'{provider_info,provider}',receipt#>>'{provider_info,model}','DATION_REASONS_V1',target_turn_id);
 INSERT INTO public.decision_interpretation_sources(workspace_id,run_id,chat_turn_id,provenance_version,result_fingerprint,
  decision_context_schema,decision_context_hash,mode,selected_entity,evidence_refs)
 VALUES(target_workspace_id,target_run_id,target_turn_id,2,r.result_fingerprint,'decision_context_v1',intent->>'context_hash',
  intent->>'mode',nullif(intent->'selected_entity','null'::jsonb),payload->'evidence_refs');
 RETURN receipt;
END; $function$

CREATE OR REPLACE FUNCTION public.platform_ultimate_data_pack(target_workspace_id uuid, actor_user_id uuid, operation text, arguments jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE role_name text; c public.decision_cases; p public.case_data_packs; v public.case_data_pack_versions;
 j dation_private.ultimate_input_uploads; pub dation_private.ultimate_pack_publications; d public.datasets;
 item jsonb; entries jsonb; did uuid; target uuid; published uuid; number integer; enabled boolean; old_entries jsonb; changes jsonb;
BEGIN
 role_name=dation_private.data_actor(target_workspace_id,actor_user_id);
 IF operation IS NULL OR operation NOT IN('state','history','upload_get','prepare','store','plan','publish','replay','compatible','dataset_get','dataset_archive','version_get','discard','cleanup','cleanup_finish')
  OR jsonb_typeof(arguments) IS DISTINCT FROM 'object' OR octet_length(arguments::text)>1048576 THEN RAISE EXCEPTION 'Invalid Pack operation' USING ERRCODE='22023'; END IF;
 IF operation IN('dataset_get','dataset_archive') THEN
  SELECT * INTO d FROM public.datasets WHERE workspace_id=target_workspace_id AND id=(arguments->>'dataset_id')::uuid AND deletion_requested_at IS NULL;
  IF NOT FOUND OR d.dataset_type NOT IN('transport_demand','transport_resources') THEN RAISE EXCEPTION 'Input not found' USING ERRCODE='P0002'; END IF;
  IF operation='dataset_archive' THEN
   PERFORM 1 FROM public.workspaces WHERE id=target_workspace_id FOR UPDATE;
   PERFORM dation_private.data_actor(target_workspace_id,actor_user_id,true);
   PERFORM set_config('dation.workspace_id',target_workspace_id::text,true);PERFORM set_config('dation.actor_user_id',actor_user_id::text,true);
   UPDATE public.datasets SET archived_at=CASE WHEN (arguments->>'archived')::boolean THEN clock_timestamp() ELSE NULL END WHERE workspace_id=target_workspace_id AND id=d.id;
   RETURN jsonb_build_object('archived',(arguments->>'archived')::boolean);
  END IF;
  RETURN jsonb_build_object('dataset',to_jsonb(d),'entry',dation_private.t4_entry(target_workspace_id,d.dataset_type,d.id));
 END IF;
 target=(arguments->>'case_id')::uuid;
 SELECT * INTO c FROM public.decision_cases WHERE workspace_id=target_workspace_id AND id=target AND workflow_version=2;
 IF NOT FOUND THEN RAISE EXCEPTION 'Ultimate Case not found' USING ERRCODE='P0002'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.workspace_ddas WHERE workspace_id=target_workspace_id AND dda_id='logistics' AND status='enabled') THEN RAISE EXCEPTION 'DDA denied' USING ERRCODE='42501'; END IF;
 SELECT * INTO p FROM public.case_data_packs WHERE workspace_id=target_workspace_id AND case_id=c.id;
 IF operation='replay' THEN
  PERFORM dation_private.data_actor(target_workspace_id,actor_user_id,true);
  SELECT * INTO pub FROM dation_private.ultimate_pack_publications WHERE id=(arguments->>'publication_id')::uuid;
  IF NOT FOUND THEN RETURN jsonb_build_object('replayed',false); END IF;
  IF pub.workspace_id<>target_workspace_id OR pub.case_id<>c.id THEN RAISE EXCEPTION 'Publication not found' USING ERRCODE='P0002'; END IF;
  IF pub.intent_hash IS DISTINCT FROM arguments->>'intent_hash' THEN RAISE EXCEPTION 'Publication intent changed' USING ERRCODE='55006'; END IF;
  RETURN jsonb_build_object('replayed',true,'publication',to_jsonb(pub),'version',(SELECT to_jsonb(x) FROM public.case_data_pack_versions x WHERE workspace_id=target_workspace_id AND id=pub.pack_version_id));
 END IF;
 IF operation IN('prepare','store','plan','publish','discard','cleanup','cleanup_finish') THEN
  PERFORM 1 FROM public.workspaces WHERE id=target_workspace_id FOR UPDATE;
  PERFORM dation_private.data_actor(target_workspace_id,actor_user_id,true);
  SELECT * INTO c FROM public.decision_cases WHERE workspace_id=target_workspace_id AND id=target FOR UPDATE;
  SELECT * INTO p FROM public.case_data_packs WHERE workspace_id=target_workspace_id AND case_id=target FOR UPDATE;
  IF NOT EXISTS(SELECT 1 FROM public.workspace_ddas WHERE workspace_id=target_workspace_id AND dda_id='logistics' AND status='enabled') THEN RAISE EXCEPTION 'DDA denied' USING ERRCODE='42501'; END IF;
  -- Resolve a committed publication before mutable revision/flag/archive checks.
  IF operation='publish' THEN
   SELECT * INTO pub FROM dation_private.ultimate_pack_publications WHERE id=(arguments->>'publication_id')::uuid;
   IF FOUND THEN
    IF pub.workspace_id<>target_workspace_id OR pub.case_id<>target THEN RAISE EXCEPTION 'Publication not found' USING ERRCODE='P0002'; END IF;
    IF pub.intent_hash IS DISTINCT FROM arguments->>'intent_hash' THEN RAISE EXCEPTION 'Publication intent changed' USING ERRCODE='55006'; END IF;
    RETURN jsonb_build_object('replayed',true,'publication',to_jsonb(pub),'version',(SELECT to_jsonb(x) FROM public.case_data_pack_versions x WHERE workspace_id=target_workspace_id AND id=pub.pack_version_id));
   END IF;
  END IF;
  SELECT ultimate_foundation_enabled AND ultimate_data_pack_enabled INTO enabled FROM dation_private.platform_release WHERE singleton;
  IF NOT enabled THEN RAISE EXCEPTION 'Ultimate input publication is closed' USING ERRCODE='P0002'; END IF;
  IF c.status='archived' THEN RAISE EXCEPTION 'Restore Case before editing inputs' USING ERRCODE='22023'; END IF;
  PERFORM set_config('dation.workspace_id',target_workspace_id::text,true);PERFORM set_config('dation.actor_user_id',actor_user_id::text,true);
 END IF;
 IF operation IN('state','history') THEN
  SELECT ultimate_foundation_enabled AND ultimate_data_pack_enabled INTO enabled FROM dation_private.platform_release WHERE singleton;
  RETURN jsonb_build_object('case',to_jsonb(c),'pack',to_jsonb(p),'model_version',(SELECT to_jsonb(x) FROM public.logistics_model_versions x WHERE workspace_id=target_workspace_id AND id=c.logistics_model_version_id),
   'version',(SELECT to_jsonb(x) FROM public.case_data_pack_versions x WHERE workspace_id=target_workspace_id AND id=p.current_version_id),
   'latest_version',(SELECT max(version) FROM public.case_data_pack_versions WHERE workspace_id=target_workspace_id AND pack_id=p.id),
   'entries',coalesce((SELECT jsonb_agg(dation_private.t4_entry(target_workspace_id,e.slot_key,e.dataset_id) ORDER BY e.slot_key) FROM public.case_data_pack_entries e WHERE e.workspace_id=target_workspace_id AND e.pack_version_id=p.current_version_id),'[]'),
   'uploads',coalesce((SELECT jsonb_agg(dation_private.t4_upload(x) ORDER BY created_at DESC,id) FROM (SELECT * FROM dation_private.ultimate_input_uploads WHERE workspace_id=target_workspace_id AND case_id=target AND status<>'DISCARDED' ORDER BY created_at DESC,id LIMIT 20) x),'[]'),
   'history',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY version DESC) FROM (SELECT * FROM public.case_data_pack_versions WHERE workspace_id=target_workspace_id AND pack_id=p.id ORDER BY version DESC LIMIT 20 OFFSET greatest(0,least(coalesce((arguments->>'offset')::integer,0),1000000))) x),'[]'),
   'history_total',(SELECT count(*) FROM public.case_data_pack_versions WHERE workspace_id=target_workspace_id AND pack_id=p.id),
   'enabled',enabled,'can_edit',enabled AND role_name<>'viewer' AND c.status<>'archived','runtime_execution_available',false);
 END IF;
 IF operation='version_get' THEN
  SELECT * INTO v FROM public.case_data_pack_versions WHERE workspace_id=target_workspace_id AND case_id=target AND id=(arguments->>'version_id')::uuid;
  IF NOT FOUND THEN RAISE EXCEPTION 'Pack Version not found' USING ERRCODE='P0002'; END IF;
  RETURN jsonb_build_object('version',to_jsonb(v),'entries',coalesce((SELECT jsonb_agg(dation_private.t4_entry(target_workspace_id,e.slot_key,e.dataset_id) ORDER BY e.slot_key) FROM public.case_data_pack_entries e WHERE e.workspace_id=target_workspace_id AND e.pack_version_id=v.id),'[]'));
 END IF;
 IF operation='compatible' THEN
  IF coalesce(arguments->>'entity','') NOT IN('transport_demand','transport_resources') THEN RAISE EXCEPTION 'Invalid entity' USING ERRCODE='22023'; END IF;
  RETURN jsonb_build_object('items',coalesce((SELECT jsonb_agg(to_jsonb(x)) FROM (SELECT ds.id,ds.original_filename,ds.row_count,ds.created_at,ds.data_contract_hash FROM public.datasets ds JOIN dation_private.ultimate_input_objects o ON o.workspace_id=ds.workspace_id AND o.dataset_id=ds.id
   WHERE ds.workspace_id=target_workspace_id AND ds.dataset_type=arguments->>'entity' AND ds.data_contract_hash=arguments->>'contract_hash'
    AND o.model_version_id=c.logistics_model_version_id AND ds.archived_at IS NULL AND ds.deletion_requested_at IS NULL ORDER BY ds.created_at DESC,ds.id LIMIT 25 OFFSET greatest(0,least(coalesce((arguments->>'offset')::integer,0),1000000))) x),'[]'));
 END IF;
 IF operation='prepare' THEN
  SELECT * INTO j FROM dation_private.ultimate_input_uploads WHERE id=(arguments->>'upload_id')::uuid;
  IF FOUND THEN
   IF j.workspace_id<>target_workspace_id OR j.case_id<>target THEN RAISE EXCEPTION 'Upload not found' USING ERRCODE='P0002'; END IF;
   IF j.intent_hash IS DISTINCT FROM arguments->>'intent_hash' THEN RAISE EXCEPTION 'Upload intent changed' USING ERRCODE='55006'; END IF;
   RETURN dation_private.t4_upload(j);
  END IF;
  IF coalesce(arguments->>'entity','') NOT IN('transport_demand','transport_resources') OR arguments#>>'{profile,valid}' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'Validated input required' USING ERRCODE='22023'; END IF;
  INSERT INTO dation_private.ultimate_input_uploads(id,workspace_id,case_id,model_version_id,entity,actor_user_id,intent_hash,contract_id,contract_hash,normalizer_version,raw_sha256,canonical_sha256,raw_size,normalized_size,record_count,column_count,filename,storage_bucket,profile,summary)
   VALUES((arguments->>'upload_id')::uuid,target_workspace_id,target,c.logistics_model_version_id,arguments->>'entity',actor_user_id,arguments->>'intent_hash',arguments->>'contract_id',arguments->>'contract_hash',arguments->>'normalizer_version',arguments->>'raw_sha256',arguments->>'canonical_sha256',(arguments->>'raw_size')::bigint,(arguments->>'normalized_size')::bigint,(arguments->>'record_count')::bigint,(arguments->>'column_count')::integer,arguments->>'filename',arguments->>'storage_bucket',arguments->'profile',arguments->'summary') RETURNING * INTO j;
  RETURN dation_private.t4_upload(j);
 END IF;
 IF operation IN('upload_get','store','discard','cleanup','cleanup_finish') THEN
  SELECT * INTO j FROM dation_private.ultimate_input_uploads WHERE workspace_id=target_workspace_id AND case_id=target AND id=(arguments->>'upload_id')::uuid FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Upload not found' USING ERRCODE='P0002'; END IF;
  IF operation='upload_get' THEN RETURN dation_private.t4_upload(j); END IF;
  IF operation='store' THEN
   IF j.status='READY' THEN RETURN dation_private.t4_upload(j); END IF;
   IF j.status<>'PREPARED' OR j.raw_sha256 IS DISTINCT FROM arguments->>'verified_raw_sha256' OR j.canonical_sha256 IS DISTINCT FROM arguments->>'verified_canonical_sha256' THEN RAISE EXCEPTION 'Upload is not complete or was discarded' USING ERRCODE='22023'; END IF;
   SELECT * INTO d FROM public.datasets WHERE workspace_id=target_workspace_id AND dataset_type=j.entity AND sha256=j.raw_sha256 AND data_contract_hash=j.contract_hash;
   IF FOUND THEN
    IF d.canonical_sha256<>j.canonical_sha256 OR d.normalizer_version<>j.normalizer_version OR d.archived_at IS NOT NULL OR d.deletion_requested_at IS NOT NULL
     OR NOT EXISTS(SELECT 1 FROM dation_private.ultimate_input_objects WHERE workspace_id=target_workspace_id AND dataset_id=d.id AND model_version_id=j.model_version_id) THEN RAISE EXCEPTION 'Stored interpretation unavailable' USING ERRCODE='22023'; END IF;
   ELSE
    INSERT INTO public.datasets(id,workspace_id,dataset_type,original_filename,canonical_filename,storage_bucket,storage_path,mime_type,size_bytes,sha256,status,row_count,column_count,schema_version,profile_json,uploaded_by_user_id,data_contract_id,data_contract_hash,normalizer_version,canonical_sha256)
     VALUES(j.reserved_dataset_id,target_workspace_id,j.entity,j.filename,j.entity||'.csv',j.storage_bucket,target_workspace_id::text||'/'||j.reserved_dataset_id::text||'/input.csv','text/csv',j.raw_size,j.raw_sha256,'uploaded',j.record_count,j.column_count,j.entity||'_v1',j.profile,j.actor_user_id,j.contract_id,j.contract_hash,j.normalizer_version,j.canonical_sha256) RETURNING * INTO d;
    INSERT INTO dation_private.ultimate_input_objects(workspace_id,dataset_id,model_version_id,normalized_bucket,normalized_path,normalized_size,summary)
     VALUES(target_workspace_id,d.id,j.model_version_id,j.storage_bucket,target_workspace_id::text||'/normalized/'||d.id::text||'/'||j.canonical_sha256||'.json',j.normalized_size,j.summary);
   END IF;
   UPDATE dation_private.ultimate_input_uploads SET dataset_id=d.id,status='READY',cleanup_pending=d.id<>reserved_dataset_id,updated_at=clock_timestamp() WHERE id=j.id RETURNING * INTO j;
   RETURN dation_private.t4_upload(j);
  END IF;
  IF operation='discard' THEN
   -- READY metadata is durable/reusable; discard the candidate link only.
   UPDATE dation_private.ultimate_input_uploads SET status='DISCARDED',cleanup_pending=(dataset_id IS NULL OR dataset_id<>reserved_dataset_id),updated_at=clock_timestamp() WHERE id=j.id RETURNING * INTO j;
  ELSIF operation='cleanup_finish' THEN
   UPDATE dation_private.ultimate_input_uploads SET cleanup_pending=false,updated_at=clock_timestamp() WHERE id=j.id RETURNING * INTO j;
  END IF;
  IF operation IN('discard','cleanup') AND j.cleanup_pending AND NOT EXISTS(SELECT 1 FROM public.datasets WHERE id=j.reserved_dataset_id) THEN
   RETURN dation_private.t4_upload(j)||jsonb_build_object('may_delete_reserved_objects',true);
  END IF;
  RETURN dation_private.t4_upload(j)||jsonb_build_object('may_delete_reserved_objects',false);
 END IF;
 entries=dation_private.t4_entries(target_workspace_id,target,arguments->'selection',arguments->'contracts');
 IF operation='plan' THEN RETURN jsonb_build_object('pack',to_jsonb(p),'entries',entries,'next_version',(SELECT max(version)+1 FROM public.case_data_pack_versions WHERE workspace_id=target_workspace_id AND pack_id=p.id)); END IF;
 IF p.revision IS DISTINCT FROM (arguments->>'expected_revision')::bigint OR p.current_version_id IS DISTINCT FROM (arguments->>'expected_current_version_id')::uuid THEN RAISE EXCEPTION 'Pack changed; candidate retained' USING ERRCODE='55006'; END IF;
 IF entries IS DISTINCT FROM arguments->'entries' OR coalesce(arguments->>'manifest_hash','') !~ '^[0-9a-f]{64}$' OR coalesce(arguments->>'contract_set_hash','') !~ '^[0-9a-f]{64}$' OR coalesce(arguments->>'intent_hash','') !~ '^[0-9a-f]{64}$' THEN RAISE EXCEPTION 'Incomplete manifest' USING ERRCODE='22023'; END IF;
 SELECT coalesce(jsonb_object_agg(e.slot_key,jsonb_build_object('raw_sha256',e.raw_sha256,'canonical_sha256',e.canonical_sha256,'contract_hash',e.contract_hash)),'{}') INTO old_entries FROM public.case_data_pack_entries e WHERE e.workspace_id=target_workspace_id AND e.pack_version_id=p.current_version_id;
 SELECT coalesce(jsonb_agg(jsonb_build_object('slot_key',x->>'slot_key','previous',old_entries->(x->>'slot_key'),'current',jsonb_build_object('raw_sha256',x->>'raw_sha256','canonical_sha256',x->>'canonical_sha256','contract_hash',x->>'contract_hash')) ORDER BY x->>'slot_key'),'[]') INTO changes
  FROM jsonb_array_elements(entries) x WHERE old_entries->(x->>'slot_key') IS DISTINCT FROM jsonb_build_object('raw_sha256',x->>'raw_sha256','canonical_sha256',x->>'canonical_sha256','contract_hash',x->>'contract_hash');
 SELECT max(version)+1 INTO number FROM public.case_data_pack_versions WHERE workspace_id=target_workspace_id AND pack_id=p.id;
 published=(arguments->>'version_id')::uuid;
 INSERT INTO public.case_data_pack_versions(id,workspace_id,case_id,pack_id,version,manifest_hash,contract_set_hash,created_by) VALUES(published,target_workspace_id,target,p.id,number,arguments->>'manifest_hash',arguments->>'contract_set_hash',actor_user_id) RETURNING * INTO v;
 FOR item IN SELECT x FROM jsonb_array_elements(entries) x LOOP
  INSERT INTO public.case_data_pack_entries(pack_version_id,slot_key,workspace_id,case_id,dataset_id,contract_id,contract_hash,raw_sha256,canonical_sha256,normalizer_version,normalized_bucket,normalized_path,record_count)
   VALUES(v.id,item->>'slot_key',target_workspace_id,target,(item->>'dataset_id')::uuid,item->>'contract_id',item->>'contract_hash',item->>'raw_sha256',item->>'canonical_sha256',item->>'normalizer_version',item->>'normalized_bucket',item->>'normalized_path',(item->>'record_count')::bigint);
 END LOOP;
 INSERT INTO dation_private.ultimate_pack_publications(id,workspace_id,case_id,pack_version_id,intent_hash,actor_user_id,previous_version_id,changes)
  VALUES((arguments->>'publication_id')::uuid,target_workspace_id,target,v.id,arguments->>'intent_hash',actor_user_id,p.current_version_id,changes) RETURNING * INTO pub;
 UPDATE public.case_data_packs SET current_version_id=v.id,revision=revision+1 WHERE workspace_id=target_workspace_id AND id=p.id;
 UPDATE public.decision_cases SET updated_at=clock_timestamp(),last_activity_at=clock_timestamp() WHERE workspace_id=target_workspace_id AND id=target;
 INSERT INTO public.audit_events(workspace_id,actor_user_id,event_type,object_type,object_id,decision_case_id,metadata_json) VALUES(target_workspace_id,actor_user_id,'case_data_pack.published','case_data_pack',p.id,target,jsonb_build_object('version_id',v.id,'version',v.version,'changes',changes));
 RETURN jsonb_build_object('replayed',false,'publication',to_jsonb(pub),'version',to_jsonb(v));
END; $function$

CREATE OR REPLACE FUNCTION public.platform_ultimate_execution(target_workspace_id uuid, actor_user_id uuid, operation text, arguments jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE wid uuid=target_workspace_id; uid uuid=actor_user_id; rid uuid=(arguments->>'run_id')::uuid; cid uuid=(arguments->>'case_id')::uuid;
 c public.decision_cases; r public.decision_runs; j public.dispatch_run_jobs; mv public.logistics_model_versions;
 p public.case_data_packs; pub dation_private.ultimate_run_publications; role_name text; owner_id uuid; data_owner uuid;
 body jsonb; input jsonb; ctx jsonb; reads jsonb; entries jsonb; policy jsonb; item jsonb; previous public.decision_runs;
 stamp timestamptz; intent text; fp text; mh text; manifest jsonb; a public.decision_result_artifacts; blockers jsonb='[]'; enabled boolean; scheduling_enabled boolean; node_key text=coalesce(arguments->>'node_id',arguments#>>'{client_request,node_id}','logistics_assignment'); schema_name text; engine_name text; ih text; upstream public.decision_runs; source_job public.dispatch_run_jobs;
BEGIN
 IF operation NOT IN('state','replay','admit','read','approve','prepare','prepared','finish') OR operation IS NULL THEN RAISE EXCEPTION 'Unsupported operation' USING ERRCODE='22023'; END IF;
 IF uid IS NULL THEN
  IF operation NOT IN('prepared','prepare','finish') THEN RAISE EXCEPTION 'Actor required' USING ERRCODE='42501'; END IF;
 ELSE role_name=dation_private.team_actor(wid,uid); END IF;
 IF NOT EXISTS(SELECT 1 FROM public.workspace_ddas WHERE workspace_id=wid AND dda_id='logistics' AND status='enabled') THEN RAISE EXCEPTION 'DDA disabled' USING ERRCODE='42501'; END IF;
 PERFORM set_config('dation.workspace_id',wid::text,true);
 PERFORM set_config('dation.actor_user_id',coalesce(uid::text,''),true);
 IF rid IS NOT NULL THEN
  SELECT * INTO r FROM public.decision_runs WHERE workspace_id=wid AND id=rid AND workflow_version=2;
  IF FOUND THEN cid=r.decision_case_id;node_key=r.node_id; END IF;
 END IF;
 -- Lock order: workspace -> Case -> job -> Run -> artifact. Claimers lock job -> Run.
 PERFORM 1 FROM public.workspaces WHERE id=wid FOR UPDATE;
 SELECT * INTO c FROM public.decision_cases WHERE workspace_id=wid AND id=cid AND workflow_version=2 FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Case not found' USING ERRCODE='P0002'; END IF;
 IF uid IS NOT NULL THEN role_name=dation_private.team_actor(wid,uid); END IF;
 SELECT ultimate_admissions_enabled,ultimate_scheduling_admissions_enabled INTO enabled,scheduling_enabled FROM dation_private.platform_release WHERE singleton;
 IF node_key NOT IN('logistics_assignment','logistics_scheduling') THEN RAISE EXCEPTION 'Unknown node' USING ERRCODE='22023'; END IF;
 IF operation='state' THEN
  body=public.platform_ultimate_graph(wid,uid,c.id);
  SELECT coalesce(jsonb_agg(to_jsonb(e)||jsonb_build_object('normalized_size',o.normalized_size,'model_version_id',o.model_version_id,'summary',o.summary) ORDER BY e.slot_key),'[]') INTO entries
   FROM public.case_data_pack_entries e JOIN dation_private.ultimate_input_objects o ON o.workspace_id=e.workspace_id AND o.dataset_id=e.dataset_id
   JOIN public.case_data_packs cp ON cp.workspace_id=e.workspace_id AND cp.case_id=e.case_id AND cp.current_version_id=e.pack_version_id
   WHERE e.workspace_id=wid AND e.case_id=cid;
  IF node_key='logistics_scheduling' THEN
    SELECT * INTO upstream FROM public.decision_runs WHERE workspace_id=wid AND decision_case_id=cid AND workflow_version=2 AND node_id='logistics_assignment'
     AND approved_at IS NOT NULL AND superseded_at IS NULL AND (arguments->'source_transport_plan' IS NULL OR arguments->'source_transport_plan'='null'::jsonb OR
       (id::text=arguments#>>'{source_transport_plan,run_id}' AND result_fingerprint=arguments#>>'{source_transport_plan,result_fingerprint}'));
    IF upstream.id IS NULL OR NOT dation_private.t8_fresh(upstream) OR upstream.status<>'completed' OR (upstream.result_json#>>'{metrics,trip_count}')::integer=0 THEN
     RAISE EXCEPTION 'Exact current approved D1 required (empty plan is NOT_APPLICABLE)' USING ERRCODE='22023'; END IF;
    IF (SELECT count(*) FROM public.decision_runs WHERE workspace_id=wid AND decision_case_id=cid AND workflow_version=2 AND node_id='logistics_assignment' AND approved_at IS NOT NULL AND superseded_at IS NULL)<>1 THEN RAISE EXCEPTION 'Ambiguous approved D1' USING ERRCODE='22023'; END IF;
    SELECT * INTO source_job FROM public.dispatch_run_jobs WHERE workspace_id=wid AND run_id=upstream.id;
    body=body||jsonb_build_object('source_run',to_jsonb(upstream),'source_input',source_job.request_json->'input','source_artifacts',
     (SELECT jsonb_agg(to_jsonb(ar) ORDER BY ar.kind,ar.part_key) FROM public.decision_result_artifacts ar WHERE ar.workspace_id=wid AND ar.run_id=upstream.id));
   END IF;
   RETURN body||jsonb_build_object('pinned_entries',entries,'admissions_enabled',enabled,'scheduling_enabled',scheduling_enabled);
 END IF;
 IF operation IN('replay','admit') THEN
  intent=dation_private.t8_hash('ULTIMATE_RUN_INTENT',jsonb_build_object('actor',uid,'request',arguments->'client_request'));
  SELECT * INTO j FROM public.dispatch_run_jobs WHERE workspace_id=wid AND run_id=rid;
  IF FOUND THEN
   IF j.request_fingerprint IS DISTINCT FROM intent THEN RAISE EXCEPTION 'Intention conflict' USING ERRCODE='22023'; END IF;
   RETURN jsonb_build_object('replayed',true,'run',to_jsonb(r)-'result_json'-'configuration_json');
  END IF;
  IF operation='replay' THEN RETURN jsonb_build_object('replayed',false); END IF;
  IF NOT enabled OR node_key='logistics_scheduling' AND NOT scheduling_enabled THEN RAISE EXCEPTION 'Ultimate admissions closed' USING ERRCODE='42501'; END IF;
  IF role_name NOT IN('admin','operator') OR c.status='archived' THEN RAISE EXCEPTION 'Writer required' USING ERRCODE='42501'; END IF;
  SELECT owner_user_id INTO owner_id FROM public.decision_assignments WHERE workspace_id=wid AND decision_case_id=cid AND node_id=node_key;
  SELECT owner_user_id INTO data_owner FROM dation_private.workflow_stage_assignments WHERE workspace_id=wid AND decision_case_id=cid AND stage_key='data_owner';
  IF NOT dation_private.responsibility_eligible(wid,owner_id,'decision_owner') OR NOT dation_private.responsibility_eligible(wid,data_owner,'data_owner') THEN RAISE EXCEPTION 'Eligible owners required' USING ERRCODE='22023'; END IF;
  IF role_name<>'admin' AND owner_id IS DISTINCT FROM uid THEN RAISE EXCEPTION 'Decision Owner or Admin required' USING ERRCODE='42501'; END IF;
  input=arguments->'input';ctx=input->'context';policy=ctx->'node_policy';reads=arguments->'graph_snapshot'->'read_set';
  schema_name=CASE node_key WHEN 'logistics_assignment' THEN 'transport_plan_v1' ELSE 'day_scheduling_v1' END;
  engine_name=CASE node_key WHEN 'logistics_assignment' THEN 'transport_plan' ELSE 'day_scheduling' END;
  ih=dation_private.t9_input_hash(ctx,jsonb_build_object('engine_name',engine_name,'engine_version','2.0.0','runtime_profile',schema_name,'result_schema',schema_name,'result_schema_version',1),
     CASE WHEN node_key='logistics_scheduling' THEN input->'source_transport_plan' ELSE NULL END);
  IF node_key='logistics_scheduling' THEN
   SELECT * INTO upstream FROM public.decision_runs WHERE workspace_id=wid AND decision_case_id=cid AND id=(input#>>'{source_transport_plan,run_id}')::uuid
    AND workflow_version=2 AND node_id='logistics_assignment' AND approved_at IS NOT NULL AND superseded_at IS NULL AND result_fingerprint=input#>>'{source_transport_plan,result_fingerprint}';
   SELECT * INTO source_job FROM public.dispatch_run_jobs WHERE workspace_id=wid AND run_id=upstream.id;
   IF upstream.id IS NULL OR NOT dation_private.t8_fresh(upstream) OR upstream.result_fingerprint IS DISTINCT FROM arguments#>>'{client_request,source_transport_plan,result_fingerprint}'
    OR input->'source_transport_plan' IS DISTINCT FROM arguments#>'{client_request,source_transport_plan}'
    OR input#>>'{source_core,decision,run_id}' IS DISTINCT FROM upstream.id::text OR input#>>'{source_core,context,workspace_id}' IS DISTINCT FROM wid::text
    OR input#>>'{source_core,context,case_id}' IS DISTINCT FROM cid::text OR dation_private.t9_core_hash(input->'source_core') IS DISTINCT FROM upstream.core_fingerprint
    OR input#>>'{source_evidence,core_result_fingerprint}' IS DISTINCT FROM upstream.core_fingerprint
    OR input->'resources' IS DISTINCT FROM source_job.request_json#>'{input,resources}' OR input->'model' IS DISTINCT FROM source_job.request_json#>'{input,model}'
    OR input->'source_temporal_certified' IS DISTINCT FROM 'true'::jsonb OR (upstream.result_json#>>'{metrics,trip_count}')::integer=0
    THEN RAISE EXCEPTION 'Invalid exact approved D1 handoff' USING ERRCODE='22023'; END IF;
  END IF;

  SELECT * INTO mv FROM public.logistics_model_versions WHERE workspace_id=wid AND id=c.logistics_model_version_id;
  SELECT * INTO p FROM public.case_data_packs WHERE workspace_id=wid AND case_id=cid;
  IF (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(reads) key) IS DISTINCT FROM
    (CASE WHEN node_key='logistics_assignment' THEN ARRAY['case_policy','horizon','model','node_policy','transport_demand','transport_resources']::text[] ELSE ARRAY['approved:logistics_assignment','horizon','node_policy']::text[] END)
   OR jsonb_array_length(arguments->'entries') IS DISTINCT FROM 2
   OR input#>>'{model,workspace_id}' IS DISTINCT FROM wid::text
   OR input#>>'{model,model_id}' IS DISTINCT FROM mv.model_id::text
   OR input#>>'{model,version_id}' IS DISTINCT FROM mv.id::text
   OR input#>>'{model,version}' IS DISTINCT FROM mv.version::text
   OR input#>>'{model,configuration_hash}' IS DISTINCT FROM mv.config_hash
   OR input#>>'{model,contract_registry_version}' IS DISTINCT FROM mv.contract_registry_version
   OR ((input->'model')-'workspace_id'-'model_id'-'version_id'-'version'-'configuration_hash'-'contract_registry_version') IS DISTINCT FROM
      (SELECT jsonb_object_agg(key,value) FROM jsonb_each(mv.config_jsonb) WHERE key IN('operating_role','transport_pattern','primary_dimension','active_dimensions','allowed_sources','homogeneous_loads_declared','split_permitted','currency_policy'))
   OR ctx->>'pack_manifest_hash' IS DISTINCT FROM (SELECT manifest_hash FROM public.case_data_pack_versions WHERE workspace_id=wid AND id=p.current_version_id)
   OR ctx->>'data_pack_version' IS DISTINCT FROM (SELECT version::text FROM public.case_data_pack_versions WHERE workspace_id=wid AND id=p.current_version_id)
   OR ctx->'active_dimensions' IS DISTINCT FROM mv.config_jsonb->'active_dimensions'
   OR ctx->'primary_dimension' IS DISTINCT FROM mv.config_jsonb->'primary_dimension'
   OR ctx->'operating_role' IS DISTINCT FROM mv.config_jsonb->'operating_role'
   OR ctx->>'case_name' IS DISTINCT FROM c.label
   OR (policy->>'override')::boolean IS DISTINCT FROM (nullif(btrim(policy->>'override_reason'),'') IS NOT NULL)
   OR (coalesce((policy->>'override')::boolean,false)=false AND policy-'override'-'override_reason' IS DISTINCT FROM c.case_policy_jsonb)
   THEN RAISE EXCEPTION 'Frozen model/read-set/policy invalid' USING ERRCODE='22023'; END IF;
  FOR item IN SELECT value FROM jsonb_array_elements(arguments->'entries') LOOP
   IF NOT EXISTS(SELECT 1 FROM public.case_data_pack_entries e JOIN dation_private.ultimate_input_objects o ON o.workspace_id=e.workspace_id AND o.dataset_id=e.dataset_id
    WHERE e.workspace_id=wid AND e.case_id=cid AND e.pack_version_id=p.current_version_id AND e.slot_key=item->>'slot_key'
    AND e.slot_key IN('transport_demand','transport_resources') AND e.dataset_id::text=item->>'dataset_id'
    AND e.canonical_sha256=item->>'canonical_sha256' AND e.contract_hash=item->>'contract_hash' AND e.normalizer_version=item->>'normalizer_version'
    AND e.normalized_bucket=item->>'normalized_bucket' AND e.normalized_path=item->>'normalized_path'
    AND o.normalized_size=(item->>'normalized_size')::bigint AND o.model_version_id=mv.id) THEN RAISE EXCEPTION 'Unbound input locator' USING ERRCODE='22023'; END IF;
  END LOOP;
  IF (SELECT jsonb_agg(x ORDER BY x->>'slot') FROM jsonb_array_elements(ctx->'read_set') x) IS DISTINCT FROM
    (SELECT jsonb_agg(jsonb_build_object('slot',e.slot_key,'canonical_sha256',e.canonical_sha256,'contract_hash',e.contract_hash,'normalizer_version',e.normalizer_version) ORDER BY e.slot_key)
     FROM public.case_data_pack_entries e WHERE e.workspace_id=wid AND e.pack_version_id=p.current_version_id AND e.slot_key IN('transport_demand','transport_resources')) THEN
   RAISE EXCEPTION 'Frozen semantic inputs invalid' USING ERRCODE='22023'; END IF;
  IF arguments#>>'{client_request,node_id}' IS DISTINCT FROM node_key OR input->>'run_id' IS DISTINCT FROM rid::text
   OR ctx->>'workspace_id' IS DISTINCT FROM wid::text OR ctx->>'case_id' IS DISTINCT FROM cid::text
   OR ctx->>'logistics_model_version_id' IS DISTINCT FROM c.logistics_model_version_id::text OR ctx->>'data_pack_version_id' IS DISTINCT FROM p.current_version_id::text
   OR ctx->>'planning_start' IS DISTINCT FROM c.planning_start::text OR ctx->>'planning_end' IS DISTINCT FROM c.planning_end::text
   OR ctx->'case_policy' IS DISTINCT FROM c.case_policy_jsonb OR ctx->>'graph_version' IS DISTINCT FROM c.graph_definition_version
   OR ctx->>'model_hash' IS DISTINCT FROM mv.config_hash OR ctx->>'contract_hash' IS DISTINCT FROM mv.contract_hash
   OR ctx->'currency_policy' IS DISTINCT FROM mv.config_jsonb->'currency_policy'
   OR NOT dation_private.t3_policy_valid(policy-'override'-'override_reason') THEN RAISE EXCEPTION 'Invalid pinned input' USING ERRCODE='22023'; END IF;
  FOR item IN SELECT value FROM jsonb_array_elements(c.case_policy_jsonb->'guardrails') LOOP
   IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(policy->'guardrails') x WHERE x->>'kind'=item->>'kind' AND
    CASE WHEN item->>'kind'='MAXIMUM_EXTERNAL_SHARE' THEN (x->>'limit')::numeric<=(item->>'limit')::numeric ELSE (x->>'limit')::numeric>=(item->>'limit')::numeric END) THEN RAISE EXCEPTION 'Guardrail relaxed' USING ERRCODE='22023'; END IF;
  END LOOP;
  IF arguments#>>'{client_request,expected_context_hash}' IS DISTINCT FROM ih
   OR ctx->>'data_pack_version_id' IS DISTINCT FROM arguments#>>'{client_request,data_pack_version_id}'
   OR ctx->>'logistics_model_version_id' IS DISTINCT FROM arguments#>>'{client_request,model_version_id}'
   OR policy IS DISTINCT FROM arguments#>'{client_request,node_policy}'
   OR arguments#>>'{graph_snapshot,definition_hash}' IS DISTINCT FROM (SELECT definition_hash FROM dation_private.decision_definition_versions WHERE version='ULTIMATE_DECISION_GRAPH_V1') THEN
   RAISE EXCEPTION 'Context/hash changed' USING ERRCODE='55006'; END IF;
  stamp=clock_timestamp();input=jsonb_set(input,'{result_generated_at}',to_jsonb(stamp));
  IF (SELECT count(*) FROM public.dispatch_run_jobs WHERE workspace_id=wid AND state IN('queued','running'))>=32 THEN RAISE EXCEPTION 'Queue full' USING ERRCODE='53300'; END IF;
  INSERT INTO public.decision_runs(id,workspace_id,created_by_user_id,created_at,dataset_id,workflow_version,decision_case_id,node_id,
    logistics_model_version_id,data_pack_version_id,graph_definition_version,case_policy_hash,node_policy_hash,contract_hash,input_context_hash,
    transit_model_version,runtime_profile,result_schema_version,engine_name,engine_version,schema_version,status,configuration_json,progress_json,upstream_run_id)
  VALUES(rid,wid,uid,stamp,(arguments->>'dataset_id')::uuid,2,cid,node_key,c.logistics_model_version_id,p.current_version_id,c.graph_definition_version,
    c.case_policy_hash,dation_private.t8_hash('POLICY',dation_private.t8_policy_projection(policy)),mv.contract_hash,ih,
    'DATION_TRANSIT_V1',schema_name,1,engine_name,'2.0.0',schema_name,'queued',
    jsonb_build_object('ultimate_graph',arguments->'graph_snapshot','frozen_context',ctx,'node_policy',policy),jsonb_build_object('stage','queued'),upstream.id) RETURNING * INTO r;
  IF dation_private.t8_read_set(r) IS DISTINCT FROM reads THEN RAISE EXCEPTION 'Consumed inputs changed' USING ERRCODE='55006'; END IF;
  FOR previous IN SELECT * FROM public.decision_runs WHERE workspace_id=wid AND decision_case_id=cid AND workflow_version=2
   AND id<>rid AND superseded_at IS NULL AND node_id IN('logistics_assignment','logistics_scheduling') AND (node_key='logistics_assignment' OR node_id='logistics_scheduling') ORDER BY id FOR UPDATE LOOP
   IF previous.approved_at IS NOT NULL THEN
    INSERT INTO public.decision_approval_events(workspace_id,run_id,case_id,node_id,action,actor,actor_user_id,occurred_at,replacement_run_id,reason_code)
     VALUES(wid,previous.id,cid,previous.node_id,'superseded','user:'||uid,uid,stamp,rid,CASE WHEN previous.node_id='logistics_assignment' THEN 'RUN_REPLACED' ELSE 'UPSTREAM_INVALIDATED' END);
   END IF;
   UPDATE public.decision_runs SET superseded_at=stamp,superseded_by_run_id=rid WHERE id=previous.id;
  END LOOP;
  INSERT INTO public.dispatch_run_jobs(workspace_id,run_id,request_json,request_fingerprint)
   VALUES(wid,rid,jsonb_build_object('workspace_id',wid,'workflow_version',2,'engine_name',engine_name,'engine_version','2.0.0','schema_version',schema_name,
    'runtime_profile',schema_name,'result_schema_version',1,'input',input,'entries',arguments->'entries','client_request',arguments->'client_request')||CASE WHEN node_key='logistics_scheduling' THEN jsonb_build_object('source_package',upstream.result_json,'source_artifacts',(SELECT jsonb_agg(to_jsonb(ar) ORDER BY ar.kind,ar.part_key) FROM public.decision_result_artifacts ar WHERE ar.workspace_id=wid AND ar.run_id=upstream.id)) ELSE '{}'::jsonb END,intent);
  RETURN jsonb_build_object('replayed',false,'run',to_jsonb(r)-'result_json'-'configuration_json');
 END IF;
 IF r.id IS NULL THEN RAISE EXCEPTION 'Run not found' USING ERRCODE='P0002'; END IF;
 IF operation IN('prepare','prepared','finish') THEN
  SELECT * INTO j FROM public.dispatch_run_jobs WHERE workspace_id=wid AND run_id=rid FOR UPDATE;
  SELECT * INTO r FROM public.decision_runs WHERE workspace_id=wid AND id=rid FOR UPDATE;
  SELECT * INTO pub FROM dation_private.ultimate_run_publications WHERE workspace_id=wid AND run_id=rid;
  IF operation='finish' AND r.status='completed' AND pub.result_fingerprint=arguments->>'result_fingerprint' THEN RETURN jsonb_build_object('replayed',true,'run',to_jsonb(r)-'configuration_json'); END IF;
  IF j.state IS DISTINCT FROM 'running' OR j.lease_token IS DISTINCT FROM (arguments->>'worker_token')::uuid OR j.lease_expires_at<=clock_timestamp() OR j.deadline_at<=clock_timestamp() THEN RAISE EXCEPTION 'Lease lost' USING ERRCODE='55006'; END IF;
  IF operation='prepared' THEN RETURN jsonb_build_object('publication',CASE WHEN pub.run_id IS NULL THEN NULL ELSE to_jsonb(pub) END,'artifacts',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.kind,x.part_key) FROM public.decision_result_artifacts x WHERE x.workspace_id=wid AND x.run_id=rid),'[]')); END IF;
  IF operation='prepare' THEN
   body=arguments->'package';fp=body#>>'{fingerprints,result_fingerprint}';manifest=body#>'{artifact_manifest,artifacts}';
   mh=encode(sha256(convert_to(dation_private.t8_canonical(manifest),'UTF8')),'hex');
   IF dation_private.t8_package_hash(body) IS DISTINCT FROM fp OR body#>>'{decision,run_id}' IS DISTINCT FROM rid::text
    OR body->'context' IS DISTINCT FROM r.configuration_json->'frozen_context' OR body#>>'{fingerprints,input_context_hash}' IS DISTINCT FROM r.input_context_hash
    OR body->>'result_schema' IS DISTINCT FROM r.schema_version OR body#>>'{engine,engine_name}' IS DISTINCT FROM r.engine_name
    OR body#>>'{engine,engine_version}' IS DISTINCT FROM r.engine_version OR body#>>'{engine,runtime_profile}' IS DISTINCT FROM r.runtime_profile
    OR body->>'result_schema_version' IS DISTINCT FROM '1' OR body#>>'{decision,node_id}' IS DISTINCT FROM r.node_id
    OR body#>>'{engine,transit_model_version}' IS DISTINCT FROM r.transit_model_version
    OR body->>'assembler_version' IS DISTINCT FROM (CASE WHEN r.node_id='logistics_assignment' THEN 'RESULT_ASSEMBLER_D1_V1' ELSE 'RESULT_ASSEMBLER_D2_V1' END)
    OR r.node_id='logistics_scheduling' AND (body->'source_transport_plan' IS DISTINCT FROM j.request_json#>'{input,source_transport_plan}' OR body#>>'{fingerprints,upstream_result_fingerprint}' IS DISTINCT FROM j.request_json#>>'{input,source_transport_plan,result_fingerprint}') OR jsonb_array_length(manifest) NOT BETWEEN 1 AND 800
    OR (SELECT count(*) FROM jsonb_array_elements(manifest) x WHERE x->>'kind'='CORE' AND x->>'artifact_schema'='engine_core_v1')<>1
    OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(manifest) x WHERE x->>'kind'='EVIDENCE' AND x->>'artifact_schema'='engine_evidence_v1')
    OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(manifest) x WHERE x->>'kind'='EXPORT_ROWS' AND x->>'artifact_schema'='export_rows_v1')
    OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(manifest) x WHERE x->>'kind'='AI_BASE' AND x->>'artifact_schema'='decision_context_v1')
    THEN RAISE EXCEPTION 'Package binding invalid' USING ERRCODE='22023'; END IF;
   IF pub.run_id IS NOT NULL THEN
    IF pub.package IS DISTINCT FROM body THEN RAISE EXCEPTION 'Prepared publication differs' USING ERRCODE='22023'; END IF;
   ELSE
    INSERT INTO dation_private.ultimate_run_publications(workspace_id,run_id,package,result_fingerprint,manifest_hash) VALUES(wid,rid,body,fp,mh);
    FOR item IN SELECT value FROM jsonb_array_elements(manifest) LOOP
     IF item->>'workspace_id' IS DISTINCT FROM wid::text OR item->>'run_id' IS DISTINCT FROM rid::text OR item->>'core_fingerprint' IS DISTINCT FROM body#>>'{fingerprints,core_result_fingerprint}'
      OR item->>'assembler_version' IS DISTINCT FROM body->>'assembler_version' OR (item->>'size_bytes')::bigint>1048576 THEN RAISE EXCEPTION 'Foreign/oversized artifact' USING ERRCODE='22023'; END IF;
     INSERT INTO public.decision_result_artifacts(id,workspace_id,run_id,kind,part_key,artifact_schema,schema_version,content_sha256,size_bytes,media_type,
      storage_bucket,storage_path,assembler_version,core_fingerprint,producer_lease_token,producer_generation,producer_metadata,lookup_keys)
     VALUES((item->>'artifact_id')::uuid,wid,rid,item->>'kind',item->>'part_key',item->>'artifact_schema',(item->>'schema_version')::integer,
      item->>'content_sha256',(item->>'size_bytes')::bigint,item->>'media_type','dda-inputs',wid::text||'/runs/'||rid::text||'/'||lower(item->>'kind')||'/'||
      (item->>'part_key')||'/'||(item->>'content_sha256')||'.json',item->>'assembler_version',item->>'core_fingerprint',j.lease_token,j.attempts,
      jsonb_build_object('runtime_profile',r.runtime_profile,'input_context_hash',r.input_context_hash,'retrieval_index',
       (arguments->'artifact_indexes'->(item->>'artifact_id'))-'entities'),
      ARRAY(SELECT (x->>0)||'/'||(x->>1) FROM jsonb_array_elements(coalesce(arguments->'artifact_indexes'->(item->>'artifact_id')->'entities','[]')) x));
    END LOOP;
   END IF;
   RETURN jsonb_build_object('package',body,'artifacts',(SELECT jsonb_agg(to_jsonb(x) ORDER BY x.kind,x.part_key) FROM public.decision_result_artifacts x WHERE x.workspace_id=wid AND x.run_id=rid));
  END IF;
  IF pub.run_id IS NULL OR pub.result_fingerprint IS DISTINCT FROM arguments->>'result_fingerprint' OR pub.manifest_hash IS DISTINCT FROM arguments->>'verified_manifest_hash'
   OR (SELECT count(*) FROM public.decision_result_artifacts WHERE workspace_id=wid AND run_id=rid)<>jsonb_array_length(pub.package#>'{artifact_manifest,artifacts}')
   OR NOT EXISTS(SELECT 1 FROM public.decision_result_artifacts WHERE workspace_id=wid AND run_id=rid AND kind='CORE' AND artifact_schema='engine_core_v1') THEN RAISE EXCEPTION 'Incomplete publication' USING ERRCODE='22023'; END IF;
  UPDATE public.decision_runs SET status='completed',finished_at=clock_timestamp(),result_json=pub.package,result_fingerprint=pub.result_fingerprint,
   result_package_version=1,assembler_version=pub.package->>'assembler_version',artifact_manifest_hash=pub.manifest_hash,
   core_fingerprint=pub.package#>>'{fingerprints,core_result_fingerprint}',summary_json=pub.package->'summary',progress_json=jsonb_build_object('stage','completed') WHERE id=rid;
  UPDATE public.decision_result_artifacts SET publication_state='READY',result_fingerprint=pub.result_fingerprint WHERE workspace_id=wid AND run_id=rid;
  UPDATE public.dispatch_run_jobs SET state='completed',lease_token=NULL,lease_expires_at=NULL WHERE workspace_id=wid AND run_id=rid;
  SELECT * INTO r FROM public.decision_runs WHERE id=rid;
  RETURN jsonb_build_object('replayed',false,'run',to_jsonb(r)-'configuration_json');
 END IF;
 -- Readers and human approval always use the published Run, never the journal.
 IF r.status<>'completed' OR r.result_fingerprint IS NULL OR r.result_fingerprint IS DISTINCT FROM arguments->>'result_fingerprint'
  OR dation_private.t8_package_hash(r.result_json) IS DISTINCT FROM r.result_fingerprint THEN RAISE EXCEPTION 'Published result not found/mismatched' USING ERRCODE='22023'; END IF;
 SELECT owner_user_id INTO owner_id FROM public.decision_assignments WHERE workspace_id=wid AND decision_case_id=cid AND node_id=r.node_id;
 IF role_name NOT IN('admin','operator') OR (role_name<>'admin' AND owner_id IS DISTINCT FROM uid) THEN blockers=blockers||'"OWNER_REQUIRED"'::jsonb; END IF;
 IF NOT dation_private.responsibility_eligible(wid,owner_id,'decision_owner') THEN blockers=blockers||'"ELIGIBLE_OWNER_REQUIRED"'::jsonb; END IF;
 IF c.status='archived' THEN blockers=blockers||'"ARCHIVED_CASE"'::jsonb; END IF;
 IF NOT dation_private.t8_fresh(r) THEN blockers=blockers||'"STALE_CONTEXT"'::jsonb; END IF;
 IF r.result_json#>>'{approval_review,decision_ready_for_review}' IS DISTINCT FROM 'true' THEN blockers=blockers||'"REVIEW_NOT_READY"'::jsonb; END IF;
 IF (SELECT count(*) FROM public.decision_result_artifacts WHERE workspace_id=wid AND run_id=rid AND result_fingerprint=r.result_fingerprint AND publication_state='READY')<>jsonb_array_length(r.result_json#>'{artifact_manifest,artifacts}') THEN blockers=blockers||'"ARTIFACTS_NOT_READY"'::jsonb; END IF;
 IF operation='approve' THEN
  IF arguments->>'case_id' IS DISTINCT FROM cid::text OR arguments->>'node_id' IS DISTINCT FROM r.node_id OR arguments->>'verified_manifest_hash' IS DISTINCT FROM r.artifact_manifest_hash THEN RAISE EXCEPTION 'Approval binding invalid' USING ERRCODE='22023'; END IF;
  IF jsonb_array_length(blockers)>0 THEN RAISE EXCEPTION 'Current approval denied' USING ERRCODE='42501'; END IF;
  IF r.approved_at IS NULL THEN
   stamp=clock_timestamp();
   UPDATE public.decision_runs SET approved_at=stamp,approved_by='user:'||uid,approved_by_user_id=uid WHERE workspace_id=wid AND id=rid;
   INSERT INTO public.decision_approval_events(workspace_id,run_id,case_id,node_id,action,actor,actor_user_id,occurred_at)
    VALUES(wid,rid,cid,r.node_id,'approved','user:'||uid,uid,stamp);
   SELECT * INTO r FROM public.decision_runs WHERE id=rid;
  END IF;
 END IF;
 RETURN jsonb_build_object('run',to_jsonb(r),'artifacts',(SELECT jsonb_agg(to_jsonb(x) ORDER BY x.kind,x.part_key) FROM public.decision_result_artifacts x WHERE x.workspace_id=wid AND x.run_id=rid),
  'overlay',jsonb_build_object('run_id',rid,'result_fingerprint',r.result_fingerprint,'approval_allowed',jsonb_array_length(blockers)=0,
   'freshness',CASE WHEN dation_private.t8_fresh(r) THEN 'CURRENT' ELSE 'STALE' END,'approval_blockers',blockers));
END; $function$

CREATE OR REPLACE FUNCTION public.platform_ultimate_foundation(target_workspace_id uuid, actor_user_id uuid, operation text, arguments jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE role_name text; enabled boolean; dda boolean; m public.logistics_models; v public.logistics_model_versions;
 c public.decision_cases; item jsonb; changes jsonb; owner_id uuid; expected_stamp timestamptz; target uuid;
 page_limit integer; page_offset integer; search_text text; result jsonb;
BEGIN
 role_name=dation_private.team_actor(target_workspace_id,actor_user_id);
 SELECT ultimate_foundation_enabled INTO enabled FROM dation_private.platform_release WHERE singleton;
 SELECT EXISTS(SELECT 1 FROM public.workspace_ddas WHERE workspace_id=target_workspace_id AND dda_id='logistics' AND status='enabled') INTO dda;
 IF operation='capabilities' THEN RETURN jsonb_build_object('enabled',enabled AND dda,'can_create_case',enabled AND dda AND role_name IN('admin','operator'),
  'can_manage_models',enabled AND dda AND role_name='admin','can_assign',enabled AND dda AND role_name='admin','runtime_execution_available',false); END IF;
 IF NOT dda THEN RAISE EXCEPTION 'DDA access denied' USING ERRCODE='42501'; END IF;
 IF operation IS NULL OR operation NOT IN('model_list','model_get','model_create','model_update','model_publish','case_get','case_create','case_update')
  OR jsonb_typeof(arguments) IS DISTINCT FROM 'object' OR octet_length(arguments::text)>524288 THEN
  RAISE EXCEPTION 'Invalid foundation operation' USING ERRCODE='22023'; END IF;
 IF operation IN('model_create','model_update','model_publish','case_create','case_update') THEN
  PERFORM 1 FROM public.workspaces WHERE id=target_workspace_id FOR UPDATE;
  role_name=dation_private.team_actor(target_workspace_id,actor_user_id,operation IN('model_create','model_update','model_publish'));
  SELECT ultimate_foundation_enabled INTO enabled FROM dation_private.platform_release WHERE singleton;
  IF NOT EXISTS(SELECT 1 FROM public.workspace_ddas WHERE workspace_id=target_workspace_id AND dda_id='logistics' AND status='enabled') THEN RAISE EXCEPTION 'DDA access denied' USING ERRCODE='42501'; END IF;
  IF role_name='viewer' THEN RAISE EXCEPTION 'Read-only membership' USING ERRCODE='42501'; END IF;
  IF NOT enabled THEN RAISE EXCEPTION 'Ultimate creation is closed' USING ERRCODE='P0002'; END IF;
  PERFORM set_config('dation.workspace_id',target_workspace_id::text,true);
  PERFORM set_config('dation.actor_user_id',actor_user_id::text,true);
 END IF;

 IF operation='model_list' THEN
  page_limit=coalesce((arguments->>'limit')::integer,25);page_offset=coalesce((arguments->>'offset')::integer,0);search_text=coalesce(arguments->>'search_text','');
  IF page_limit NOT BETWEEN 1 AND 50 OR page_offset NOT BETWEEN 0 AND 1000000 OR length(search_text)>120 THEN RAISE EXCEPTION 'Invalid page' USING ERRCODE='22023'; END IF;
  WITH matched AS (SELECT * FROM public.logistics_models WHERE workspace_id=target_workspace_id
   AND (coalesce((arguments->>'include_archived')::boolean,false) OR status='active')
   AND (search_text='' OR strpos(lower(name),lower(search_text))>0)),
  page AS (SELECT * FROM matched ORDER BY updated_at DESC,id LIMIT page_limit OFFSET page_offset)
  SELECT jsonb_build_object('items',coalesce((SELECT jsonb_agg(to_jsonb(p)-'draft_config_jsonb'||jsonb_build_object('versions',
    (SELECT coalesce(jsonb_agg(jsonb_build_object('id',vv.id,'version',vv.version,'published_at',vv.published_at) ORDER BY vv.version DESC),'[]') FROM public.logistics_model_versions vv WHERE vv.workspace_id=p.workspace_id AND vv.model_id=p.id)) ORDER BY p.updated_at DESC,p.id) FROM page p),'[]'),
   'total',(SELECT count(*) FROM matched),'limit',page_limit,'offset',page_offset) INTO result;
  RETURN result;
 END IF;

 IF operation IN('model_get','model_update','model_publish') THEN
  SELECT * INTO m FROM public.logistics_models WHERE workspace_id=target_workspace_id AND id=(arguments->>'model_id')::uuid;
  IF NOT FOUND THEN RAISE EXCEPTION 'Model not found' USING ERRCODE='P0002'; END IF;
 END IF;
 IF operation='model_create' THEN
  target=(arguments->>'id')::uuid;
  SELECT * INTO m FROM public.logistics_models WHERE id=target;
  IF FOUND THEN
   IF m.workspace_id<>target_workspace_id THEN RAISE EXCEPTION 'Model not found' USING ERRCODE='P0002'; END IF;
   IF m.creation_intent_hash IS DISTINCT FROM arguments->>'creation_intent_hash' THEN RAISE EXCEPTION 'Creation intent changed' USING ERRCODE='55006'; END IF;
  ELSE
   IF NOT dation_private.t3_configuration_valid(arguments->'configuration') OR coalesce(arguments->>'configuration_hash','') !~ '^[0-9a-f]{64}$'
    OR coalesce(arguments->>'creation_intent_hash','') !~ '^[0-9a-f]{64}$' THEN RAISE EXCEPTION 'Invalid Model configuration' USING ERRCODE='22023'; END IF;
   INSERT INTO public.logistics_models(id,workspace_id,name,description,created_by,draft_config_jsonb,draft_config_hash,creation_intent_hash)
   VALUES(target,target_workspace_id,arguments->>'name',arguments->>'description',actor_user_id,arguments->'configuration',arguments->>'configuration_hash',arguments->>'creation_intent_hash') RETURNING * INTO m;
   INSERT INTO public.audit_events(workspace_id,actor_user_id,event_type,object_type,object_id) VALUES(target_workspace_id,actor_user_id,'logistics_model.created','logistics_model',m.id);
  END IF;
 ELSIF operation='model_update' THEN
  IF m.revision IS DISTINCT FROM (arguments->>'expected_revision')::bigint THEN RAISE EXCEPTION 'Model changed' USING ERRCODE='55006'; END IF;
  IF NOT dation_private.t3_configuration_valid(arguments->'configuration') OR coalesce(arguments->>'configuration_hash','') !~ '^[0-9a-f]{64}$' THEN RAISE EXCEPTION 'Invalid Model configuration' USING ERRCODE='22023'; END IF;
  UPDATE public.logistics_models SET name=arguments->>'name',description=arguments->>'description',status=arguments->>'status',draft_config_jsonb=arguments->'configuration',
   draft_config_hash=arguments->>'configuration_hash',revision=revision+1,updated_at=clock_timestamp() WHERE id=m.id AND workspace_id=target_workspace_id RETURNING * INTO m;
  INSERT INTO public.audit_events(workspace_id,actor_user_id,event_type,object_type,object_id,metadata_json) VALUES(target_workspace_id,actor_user_id,'logistics_model.updated','logistics_model',m.id,jsonb_build_object('revision',m.revision));
 ELSIF operation='model_publish' THEN
  SELECT * INTO v FROM public.logistics_model_versions WHERE id=(arguments->>'version_id')::uuid;
  IF FOUND THEN
   IF v.workspace_id<>target_workspace_id OR v.model_id<>m.id THEN RAISE EXCEPTION 'Version not found' USING ERRCODE='P0002'; END IF;
   IF v.source_model_revision IS DISTINCT FROM (arguments->>'expected_revision')::bigint THEN RAISE EXCEPTION 'Publish intent changed' USING ERRCODE='55006'; END IF;
   RETURN jsonb_build_object('version',to_jsonb(v),'model_revision',m.revision,'replayed',true);
  END IF;
  IF m.revision IS DISTINCT FROM (arguments->>'expected_revision')::bigint OR m.draft_config_hash IS DISTINCT FROM arguments->>'configuration_hash' THEN RAISE EXCEPTION 'Model changed' USING ERRCODE='55006'; END IF;
  IF m.status<>'active' OR NOT dation_private.t3_configuration_valid(m.draft_config_jsonb)
   OR coalesce(arguments->>'contract_hash','') !~ '^[0-9a-f]{64}$'
   OR arguments#>>'{contract_descriptor,schema_version}' IS DISTINCT FROM 'ultimate_model_domain_reference_v1'
   OR arguments#>>'{contract_descriptor,configuration_hash}' IS DISTINCT FROM m.draft_config_hash THEN RAISE EXCEPTION 'Invalid publication' USING ERRCODE='22023'; END IF;
  INSERT INTO public.logistics_model_versions(id,workspace_id,model_id,version,graph_definition_version,config_schema_version,config_jsonb,
   contract_descriptor_jsonb,config_hash,contract_hash,contract_registry_version,published_by,source_model_revision)
  VALUES((arguments->>'version_id')::uuid,target_workspace_id,m.id,(SELECT coalesce(max(version),0)+1 FROM public.logistics_model_versions WHERE model_id=m.id),
   'ULTIMATE_FOUNDATION_V1','logistics_model_config_v1',m.draft_config_jsonb,arguments->'contract_descriptor',m.draft_config_hash,arguments->>'contract_hash','ULTIMATE_DOMAIN_V1',actor_user_id,m.revision) RETURNING * INTO v;
  UPDATE public.logistics_models SET revision=revision+1,updated_at=clock_timestamp() WHERE id=m.id RETURNING * INTO m;
  INSERT INTO public.audit_events(workspace_id,actor_user_id,event_type,object_type,object_id,metadata_json)
   VALUES(target_workspace_id,actor_user_id,'logistics_model.version_published','logistics_model',m.id,jsonb_build_object('version_id',v.id,'version',v.version));
  RETURN jsonb_build_object('version',to_jsonb(v),'model_revision',m.revision,'replayed',false);
 END IF;
 IF operation IN('model_get','model_create','model_update') THEN
  RETURN jsonb_build_object('model',to_jsonb(m),'versions',coalesce((SELECT jsonb_agg(to_jsonb(vv) ORDER BY vv.version DESC)
   FROM public.logistics_model_versions vv WHERE vv.workspace_id=target_workspace_id AND vv.model_id=m.id),'[]'));
 END IF;

 target=(arguments->>CASE WHEN operation='case_create' THEN 'id' ELSE 'case_id' END)::uuid;
 SELECT * INTO c FROM public.decision_cases WHERE workspace_id=target_workspace_id AND id=target;
 IF operation='case_create' THEN
  IF FOUND THEN
   IF c.workflow_version<>2 OR c.creation_intent_hash IS DISTINCT FROM arguments->>'creation_intent_hash' THEN RAISE EXCEPTION 'Creation intent changed' USING ERRCODE='55006'; END IF;
   RETURN dation_private.t3_case_context(c,actor_user_id);
  END IF;
  IF EXISTS(SELECT 1 FROM public.decision_cases WHERE id=target) THEN RAISE EXCEPTION 'Case not found' USING ERRCODE='P0002'; END IF;
  SELECT * INTO v FROM public.logistics_model_versions WHERE workspace_id=target_workspace_id AND id=(arguments->>'logistics_model_version_id')::uuid;
  IF NOT FOUND THEN RAISE EXCEPTION 'Model Version not found' USING ERRCODE='P0002'; END IF;
  SELECT * INTO m FROM public.logistics_models WHERE workspace_id=target_workspace_id AND id=v.model_id;
  IF m.status<>'active' OR NOT dation_private.t3_configuration_valid(v.config_jsonb) THEN RAISE EXCEPTION 'Choose an active published Model Version' USING ERRCODE='22023'; END IF;
  IF length(coalesce(trim(arguments->>'name'),'')) NOT BETWEEN 1 AND 120
   OR NOT dation_private.t3_policy_valid(arguments->'case_policy') OR coalesce(arguments->>'case_policy_hash','') !~ '^[0-9a-f]{64}$'
   OR coalesce(arguments->>'horizon_type','') NOT IN('DAILY','WEEKLY','MONTHLY','CUSTOM')
   OR coalesce(arguments->>'creation_intent_hash','') !~ '^[0-9a-f]{64}$' THEN RAISE EXCEPTION 'Invalid Case context' USING ERRCODE='22023'; END IF;
  owner_id=(arguments->>'decision_owner_user_id')::uuid;
  IF role_name='admin' AND owner_id IS NULL THEN RAISE EXCEPTION 'Choose a Decision Owner' USING ERRCODE='22023'; END IF;
  IF owner_id IS NOT NULL AND role_name<>'admin' THEN RAISE EXCEPTION 'Only Admin may assign owners' USING ERRCODE='42501'; END IF;
  IF owner_id IS NOT NULL AND NOT dation_private.responsibility_eligible(target_workspace_id,owner_id,'decision_owner') THEN RAISE EXCEPTION 'Owner is not eligible' USING ERRCODE='22023'; END IF;
  INSERT INTO public.decision_cases(id,workspace_id,schema_version,workflow_version,label,description,category,logistics_model_version_id,
   planning_start,planning_end,horizon_type,operating_mode,case_policy_schema_version,case_policy_jsonb,case_policy_hash,graph_definition_version,created_by_user_id,creation_intent_hash)
  VALUES(target,target_workspace_id,'decision_case_v2',2,arguments->>'name',arguments->>'description',
   CASE arguments->>'horizon_type' WHEN 'WEEKLY' THEN 'weekly' WHEN 'MONTHLY' THEN 'monthly' WHEN 'DAILY' THEN 'live_operation' ELSE 'extraordinary' END,
   v.id,(arguments->>'planning_start')::date,(arguments->>'planning_end')::date,arguments->>'horizon_type',arguments->>'operating_mode','case_policy_v1',arguments->'case_policy',arguments->>'case_policy_hash',v.graph_definition_version,actor_user_id,arguments->>'creation_intent_hash') RETURNING * INTO c;
  INSERT INTO public.case_data_packs(id,workspace_id,case_id) VALUES((arguments->>'pack_id')::uuid,target_workspace_id,c.id);
  INSERT INTO public.case_data_pack_versions(id,workspace_id,case_id,pack_id,version,manifest_hash,contract_set_hash,created_by)
   VALUES((arguments->>'pack_version_id')::uuid,target_workspace_id,c.id,(arguments->>'pack_id')::uuid,1,arguments->>'manifest_hash',arguments->>'contract_set_hash',actor_user_id);
  UPDATE public.case_data_packs SET current_version_id=(arguments->>'pack_version_id')::uuid WHERE workspace_id=target_workspace_id AND case_id=c.id;
  IF owner_id IS NOT NULL THEN
   PERFORM public.platform_assign_decision(target_workspace_id,actor_user_id,c.id,'logistics_assignment',NULL,owner_id,NULL);
   PERFORM public.platform_assign_decision(target_workspace_id,actor_user_id,c.id,'logistics_scheduling',NULL,owner_id,NULL);
  END IF;
  RETURN dation_private.t3_case_context(c,actor_user_id);
 END IF;
 IF NOT FOUND OR c.workflow_version<>2 THEN RAISE EXCEPTION 'Ultimate Case not found' USING ERRCODE='P0002'; END IF;
 IF operation='case_get' THEN RETURN dation_private.t3_case_context(c,actor_user_id); END IF;
 SELECT * INTO c FROM public.decision_cases WHERE workspace_id=target_workspace_id AND id=target FOR UPDATE;
 IF c.updated_at IS DISTINCT FROM (arguments->>'expected_updated_at')::timestamptz THEN RAISE EXCEPTION 'Case changed' USING ERRCODE='55006'; END IF;
 IF c.status='archived' THEN RAISE EXCEPTION 'Restore Case before editing' USING ERRCODE='22023'; END IF;
 changes=arguments->'changes';
 IF jsonb_typeof(changes) IS DISTINCT FROM 'object' OR changes-ARRAY['name','description','planning_start','planning_end','horizon_type','operating_mode','case_policy','case_policy_hash']<>'{}'
  OR (changes?'case_policy' AND NOT dation_private.t3_policy_valid(changes->'case_policy'))
  OR (changes?'name' AND nullif(trim(changes->>'name'),'') IS NULL)
  OR jsonb_typeof(arguments->'owner_updates') IS DISTINCT FROM 'array' OR jsonb_array_length(arguments->'owner_updates')>2 THEN
  RAISE EXCEPTION 'Invalid context update' USING ERRCODE='22023'; END IF;
 IF jsonb_array_length(arguments->'owner_updates')>0 AND role_name<>'admin' THEN RAISE EXCEPTION 'Only Admin may assign owners' USING ERRCODE='42501'; END IF;
 IF (SELECT count(*)<>count(DISTINCT x->>'node_id') FROM jsonb_array_elements(arguments->'owner_updates') x) THEN RAISE EXCEPTION 'Duplicate owner update' USING ERRCODE='22023'; END IF;
 UPDATE public.decision_cases SET label=CASE WHEN changes?'name' THEN changes->>'name' ELSE label END,
  description=CASE WHEN changes?'description' THEN changes->>'description' ELSE description END,
  planning_start=CASE WHEN changes?'planning_start' THEN (changes->>'planning_start')::date ELSE planning_start END,
  planning_end=CASE WHEN changes?'planning_end' THEN (changes->>'planning_end')::date ELSE planning_end END,
  horizon_type=CASE WHEN changes?'horizon_type' THEN changes->>'horizon_type' ELSE horizon_type END,
  operating_mode=CASE WHEN changes?'operating_mode' THEN changes->>'operating_mode' ELSE operating_mode END,
  case_policy_jsonb=CASE WHEN changes?'case_policy' THEN changes->'case_policy' ELSE case_policy_jsonb END,
  case_policy_hash=CASE WHEN changes?'case_policy' THEN changes->>'case_policy_hash' ELSE case_policy_hash END,
  updated_at=clock_timestamp(),last_activity_at=clock_timestamp()
 WHERE workspace_id=target_workspace_id AND id=c.id RETURNING * INTO c;
 FOR item IN SELECT x FROM jsonb_array_elements(arguments->'owner_updates') x LOOP
  PERFORM public.platform_assign_decision(target_workspace_id,actor_user_id,c.id,item->>'node_id',
   (item->>'expected_updated_at')::timestamptz,(item->>'owner_user_id')::uuid,NULL);
 END LOOP;
 INSERT INTO public.audit_events(workspace_id,actor_user_id,event_type,object_type,object_id,decision_case_id,metadata_json)
 VALUES(target_workspace_id,actor_user_id,'decision_case.context_updated','decision_case',c.id,c.id,
  jsonb_build_object('fields',(SELECT coalesce(jsonb_agg(k),'[]') FROM jsonb_object_keys(changes) k)));
 RETURN dation_private.t3_case_context(c,actor_user_id);
END; $function$

CREATE OR REPLACE FUNCTION public.platform_ultimate_graph(target_workspace_id uuid, actor_user_id uuid, target_case_id uuid, operation text DEFAULT 'snapshot'::text, target_node_id text DEFAULT NULL::text, selected_run_id uuid DEFAULT NULL::uuid, page_limit integer DEFAULT 25, page_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE c public.decision_cases; role_name text; body jsonb; runs jsonb; selected jsonb; history jsonb; total bigint;
BEGIN
 role_name=dation_private.team_actor(target_workspace_id,actor_user_id);
 IF operation NOT IN('snapshot','configure','history','cohort') OR operation IS NULL
 OR target_node_id IS NOT NULL AND target_node_id NOT IN('logistics_assignment','logistics_scheduling')
 OR operation IN('configure','history') AND target_node_id IS NULL
 OR page_limit NOT BETWEEN 1 AND 50 OR page_offset NOT BETWEEN 0 AND 1000000 THEN
  RAISE EXCEPTION 'Invalid graph request' USING ERRCODE='22023'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.workspace_ddas WHERE workspace_id=target_workspace_id AND dda_id='logistics' AND status='enabled') THEN
  RAISE EXCEPTION 'DDA access denied' USING ERRCODE='42501'; END IF;
 -- Same order as Pack/context/admission writers. One coherent, authorized input snapshot.
 PERFORM 1 FROM public.workspaces WHERE id=target_workspace_id FOR SHARE;
 SELECT * INTO c FROM public.decision_cases WHERE workspace_id=target_workspace_id AND id=target_case_id FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Case not found' USING ERRCODE='P0002'; END IF;
 role_name=dation_private.team_actor(target_workspace_id,actor_user_id);
 IF operation='cohort' THEN RETURN jsonb_build_object('workflow_version',c.workflow_version); END IF;
 IF c.workflow_version<>2 OR c.graph_definition_version NOT IN('ULTIMATE_FOUNDATION_V1','ULTIMATE_DECISION_GRAPH_V1') THEN
  RAISE EXCEPTION 'Unsupported graph cohort/binding' USING ERRCODE='22023'; END IF;
 IF selected_run_id IS NOT NULL THEN
  SELECT dation_private.t5_run_projection(r) INTO selected FROM public.decision_runs r
  WHERE r.workspace_id=target_workspace_id AND r.decision_case_id=c.id AND r.workflow_version=2 AND r.id=selected_run_id
   AND (target_node_id IS NULL OR r.node_id=target_node_id);
  IF NOT FOUND THEN RAISE EXCEPTION 'Run not found in Case/node' USING ERRCODE='P0002'; END IF;
 END IF;
 IF operation='history' THEN
  SELECT count(*) INTO total FROM public.decision_runs WHERE workspace_id=target_workspace_id AND decision_case_id=c.id AND workflow_version=2 AND node_id=target_node_id;
  SELECT coalesce(jsonb_agg(dation_private.t5_run_projection(r) ORDER BY r.created_at DESC,r.id DESC),'[]') INTO history
   FROM (SELECT * FROM public.decision_runs WHERE workspace_id=target_workspace_id AND decision_case_id=c.id AND workflow_version=2 AND node_id=target_node_id
    ORDER BY created_at DESC,id DESC LIMIT page_limit OFFSET page_offset) r;
  RETURN jsonb_build_object('items',history,'total',total,'limit',page_limit,'offset',page_offset);
 END IF;
 IF (SELECT count(*) FROM public.decision_runs WHERE workspace_id=target_workspace_id AND decision_case_id=c.id AND workflow_version=2 AND superseded_at IS NULL)>100 THEN
  RAISE EXCEPTION 'Ambiguous/unbounded active history' USING ERRCODE='22023'; END IF;
 body=dation_private.t3_case_context(c,actor_user_id);
 SELECT coalesce(jsonb_agg(dation_private.t5_run_projection(r)||jsonb_build_object('history_count',
  (SELECT count(*) FROM public.decision_runs h WHERE h.workspace_id=r.workspace_id AND h.decision_case_id=r.decision_case_id AND h.node_id=r.node_id))),'[]')
 INTO runs FROM public.decision_runs r WHERE r.workspace_id=target_workspace_id AND r.decision_case_id=c.id AND r.workflow_version=2 AND r.superseded_at IS NULL;
 RETURN body||jsonb_build_object('runtime_capabilities',jsonb_build_object('logistics_scheduling',(SELECT ultimate_scheduling_admissions_enabled FROM dation_private.platform_release WHERE singleton)))||jsonb_build_object('definition',(SELECT to_jsonb(d) FROM dation_private.decision_definition_versions d WHERE version='ULTIMATE_DECISION_GRAPH_V1'),
  'entries',coalesce((SELECT jsonb_agg(jsonb_build_object('slot_key',e.slot_key,'contract_hash',e.contract_hash,
   'canonical_sha256',e.canonical_sha256,'normalizer_version',e.normalizer_version,'record_count',e.record_count,
   'model_version_id',o.model_version_id,'summary',o.summary) ORDER BY e.slot_key)
   FROM public.case_data_pack_entries e JOIN dation_private.ultimate_input_objects o ON o.workspace_id=e.workspace_id AND o.dataset_id=e.dataset_id
   WHERE e.workspace_id=c.workspace_id AND e.case_id=c.id AND e.pack_version_id=(body#>>'{pack,current_version_id}')::uuid),'[]'),
  'runs',runs,'selected_run',selected,
  'history_counts',(SELECT jsonb_object_agg(n.id,(SELECT count(*) FROM public.decision_runs h
    WHERE h.workspace_id=c.workspace_id AND h.decision_case_id=c.id AND h.workflow_version=2 AND h.node_id=n.id))
    FROM (VALUES('logistics_assignment'),('logistics_scheduling')) n(id)),
  'permissions',coalesce(body->'permissions','{}')||jsonb_build_object('can_write',role_name IN('admin','operator') AND c.status<>'archived'));
END; $function$

CREATE OR REPLACE FUNCTION public.platform_update_case(target_workspace_id uuid, actor_user_id uuid, target_case_id uuid, expected_updated_at timestamp with time zone, change_label boolean DEFAULT false, new_label text DEFAULT NULL::text, archive boolean DEFAULT NULL::boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE c decision_cases;
BEGIN
 PERFORM dation_private.data_actor(target_workspace_id,actor_user_id,true);
 SELECT * INTO c FROM decision_cases WHERE workspace_id=target_workspace_id AND id=target_case_id FOR UPDATE NOWAIT;
 IF NOT FOUND THEN RAISE EXCEPTION 'Case not found' USING ERRCODE='P0002'; END IF;
 IF expected_updated_at IS DISTINCT FROM c.updated_at THEN RAISE EXCEPTION 'Case changed; refresh' USING ERRCODE='55006'; END IF;
 IF change_label AND new_label IS NOT NULL AND (length(trim(new_label)) NOT BETWEEN 1 AND 120) THEN RAISE EXCEPTION 'Invalid label' USING ERRCODE='22023'; END IF;
 UPDATE decision_cases SET label=CASE WHEN change_label THEN nullif(trim(new_label),'') ELSE label END,
  status=CASE WHEN archive THEN 'archived' WHEN archive=false THEN 'active' ELSE status END,
  archived_at=CASE WHEN archive THEN now() WHEN archive=false THEN NULL ELSE archived_at END,
  updated_at=clock_timestamp(),last_activity_at=clock_timestamp() WHERE id=c.id AND workspace_id=target_workspace_id RETURNING * INTO c;
 RETURN jsonb_build_object('id',c.id,'label',c.label,'updated_at',c.updated_at,'status',c.status);
EXCEPTION WHEN lock_not_available THEN RAISE EXCEPTION 'Case is busy; retry' USING ERRCODE='55006';
END; $function$

CREATE OR REPLACE FUNCTION public.platform_update_case_identity(target_workspace_id uuid, actor_user_id uuid, target_case_id uuid, expected_updated_at timestamp with time zone, identity_changes jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE c decision_cases; result jsonb;
BEGIN
 IF jsonb_typeof(identity_changes)<>'object' OR identity_changes-'label'-'category'-'description'<>'{}'::jsonb THEN
  RAISE EXCEPTION 'Invalid Case identity' USING ERRCODE='22023';
 END IF;
 -- Reuse the canonical actor, workspace, row lock, name validation and CAS.
 result=public.platform_update_case(target_workspace_id,actor_user_id,target_case_id,expected_updated_at,
  identity_changes?'label',identity_changes->>'label',NULL);
 UPDATE decision_cases SET
  category=CASE WHEN identity_changes?'category' THEN identity_changes->>'category' ELSE category END,
  description=CASE WHEN identity_changes?'description' THEN nullif(trim(identity_changes->>'description'),'') ELSE description END
 WHERE workspace_id=target_workspace_id AND id=target_case_id RETURNING * INTO c;
 RETURN result||jsonb_build_object('category',c.category,'description',c.description);
END; $function$

CREATE OR REPLACE FUNCTION public.platform_update_member(target_workspace_id uuid, actor_user_id uuid, member_user_id uuid, expected_updated_at timestamp with time zone, new_role text, new_business_role text, new_status text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE member workspace_members;
BEGIN
 PERFORM 1 FROM workspaces WHERE id=target_workspace_id FOR UPDATE;
 PERFORM dation_private.team_actor(target_workspace_id,actor_user_id,true);
 SELECT * INTO member FROM workspace_members WHERE workspace_id=target_workspace_id AND user_id=member_user_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Member not found' USING ERRCODE='P0002'; END IF;
 IF member.updated_at IS DISTINCT FROM expected_updated_at THEN RAISE EXCEPTION 'Member changed' USING ERRCODE='55006'; END IF;
 IF new_role IS NULL OR new_status IS NULL OR new_role NOT IN('admin','operator','viewer') OR new_status NOT IN('active','disabled') OR
 (new_business_role IS NOT NULL AND new_business_role NOT IN('data_owner','data_steward','decision_owner','approver')) THEN RAISE EXCEPTION 'Invalid role' USING ERRCODE='22023'; END IF;
 IF member.access_role='admin' AND member.status='active' AND (new_role<>'admin' OR new_status<>'active') AND NOT EXISTS(
 SELECT 1 FROM workspace_members m JOIN auth.users u ON u.id=m.user_id AND u.email_confirmed_at IS NOT NULL
 WHERE m.workspace_id=target_workspace_id AND m.user_id<>member_user_id AND m.access_role='admin' AND m.status='active') THEN
 RAISE EXCEPTION 'Keep at least one active administrator' USING ERRCODE='22023'; END IF;
 UPDATE workspace_members SET access_role=new_role,business_role=new_business_role,status=new_status,updated_at=clock_timestamp()
 WHERE workspace_id=target_workspace_id AND user_id=member_user_id;
 INSERT INTO audit_events(workspace_id,actor_user_id,event_type,metadata_json) VALUES(target_workspace_id,actor_user_id,'team.member_updated',
 jsonb_build_object('user_id',member_user_id,'before',jsonb_build_object('access_role',member.access_role,'business_role',member.business_role,'status',member.status),'after',jsonb_build_object('access_role',new_role,'business_role',new_business_role,'status',new_status)));
 RETURN jsonb_build_object('user_id',member_user_id,'status',new_status);
END; $function$

CREATE OR REPLACE FUNCTION public.platform_update_member_foundation(target_workspace_id uuid, actor_user_id uuid, member_user_id uuid, expected_updated_at timestamp with time zone, new_role text, new_status text, new_business_roles text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE member public.workspace_members; result jsonb;
BEGIN
 PERFORM 1 FROM public.workspaces WHERE id=target_workspace_id FOR UPDATE;
 PERFORM dation_private.team_actor(target_workspace_id,actor_user_id,true);
 SELECT * INTO member FROM public.workspace_members WHERE workspace_id=target_workspace_id AND user_id=member_user_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Member not found' USING ERRCODE='P0002'; END IF;
 -- Update responsibilities while the actor still has Admin access. This also
 -- allows an Admin to demote themself when another active Admin remains.
 result=public.platform_set_member_responsibilities(target_workspace_id,actor_user_id,member_user_id,expected_updated_at,new_business_roles);
 SELECT * INTO member FROM public.workspace_members WHERE workspace_id=target_workspace_id AND user_id=member_user_id;
 PERFORM public.platform_update_member(target_workspace_id,actor_user_id,member_user_id,member.updated_at,new_role,member.business_role,new_status);
 SELECT * INTO member FROM public.workspace_members WHERE workspace_id=target_workspace_id AND user_id=member_user_id;
 RETURN result||jsonb_build_object('user_id',member_user_id,'status',new_status,'access_role',new_role,'updated_at',member.updated_at);
END; $function$

CREATE OR REPLACE FUNCTION public.platform_update_workspace(target_workspace_id uuid, actor_user_id uuid, expected_updated_at timestamp with time zone, section_name text, changes jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE workspace workspaces; before_values jsonb; after_values jsonb; allowed text[];
BEGIN
 SELECT * INTO workspace FROM workspaces WHERE id=target_workspace_id FOR UPDATE NOWAIT;
 PERFORM dation_private.team_actor(target_workspace_id,actor_user_id,true);
 IF workspace.updated_at IS DISTINCT FROM expected_updated_at THEN RAISE EXCEPTION 'Workspace changed; refresh' USING ERRCODE='55006'; END IF;
 IF section_name IS NULL OR section_name NOT IN('general','operation') OR changes IS NULL OR jsonb_typeof(changes)<>'object' THEN
 RAISE EXCEPTION 'Invalid settings section' USING ERRCODE='22023'; END IF;
 allowed=CASE WHEN section_name='general' THEN ARRAY['name','country','language','timezone'] ELSE ARRAY['currency','weight_unit','distance_unit','logistics_unit'] END;
 IF (changes-allowed)<>'{}'::jsonb OR NOT changes ?& allowed OR EXISTS(SELECT 1 FROM jsonb_each(changes) WHERE jsonb_typeof(value)<>'string') THEN
 RAISE EXCEPTION 'Invalid settings fields' USING ERRCODE='22023'; END IF;
 IF section_name='general' THEN
  IF length(trim(changes->>'name')) NOT BETWEEN 2 AND 120 OR changes->>'country' !~ '^[A-Z]{2}$' OR changes->>'language' NOT IN('es','en','pt')
   OR NOT EXISTS(SELECT 1 FROM pg_timezone_names WHERE name=changes->>'timezone') THEN RAISE EXCEPTION 'Invalid general preferences' USING ERRCODE='22023'; END IF;
  before_values=jsonb_build_object('name',workspace.name,'country',workspace.country,'language',workspace.language,'timezone',workspace.timezone);
  UPDATE workspaces SET name=trim(changes->>'name'),country=changes->>'country',language=changes->>'language',timezone=changes->>'timezone',updated_at=clock_timestamp()
   WHERE id=target_workspace_id RETURNING * INTO workspace;
  after_values=jsonb_build_object('name',workspace.name,'country',workspace.country,'language',workspace.language,'timezone',workspace.timezone);
 ELSE
  IF changes->>'currency' NOT IN('ARS','BRL','CLP','COP','EUR','MXN','PEN','USD','UYU') OR changes->>'weight_unit' NOT IN('kg','t')
   OR changes->>'distance_unit' NOT IN('km','mi') OR changes->>'logistics_unit' NOT IN('units','pallets','cases') THEN RAISE EXCEPTION 'Invalid operational preferences' USING ERRCODE='22023'; END IF;
  before_values=jsonb_build_object('currency',workspace.currency,'weight_unit',workspace.weight_unit,'distance_unit',workspace.distance_unit,'logistics_unit',workspace.logistics_unit);
  UPDATE workspaces SET currency=changes->>'currency',weight_unit=changes->>'weight_unit',distance_unit=changes->>'distance_unit',logistics_unit=changes->>'logistics_unit',updated_at=clock_timestamp()
   WHERE id=target_workspace_id RETURNING * INTO workspace;
  after_values=jsonb_build_object('currency',workspace.currency,'weight_unit',workspace.weight_unit,'distance_unit',workspace.distance_unit,'logistics_unit',workspace.logistics_unit);
 END IF;
 INSERT INTO audit_events(workspace_id,actor_user_id,event_type,metadata_json) VALUES(target_workspace_id,actor_user_id,'workspace.settings_updated',
  jsonb_build_object('section',section_name,'before',before_values,'after',after_values));
 RETURN jsonb_build_object('workspace',to_jsonb(workspace));
EXCEPTION WHEN lock_not_available THEN RAISE EXCEPTION 'Workspace is busy; refresh' USING ERRCODE='55006';
END; $function$

CREATE OR REPLACE FUNCTION public.platform_validate_decision_stage(target_workspace_id uuid, actor_user_id uuid, target_case_id uuid, target_node_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
 PERFORM dation_private.team_actor(target_workspace_id,actor_user_id);
 IF target_node_id NOT IN('logistics_assignment','logistics_scheduling') OR target_node_id IS NULL THEN RAISE EXCEPTION 'Invalid node' USING ERRCODE='22023'; END IF;
 PERFORM set_config('dation.actor_user_id',actor_user_id::text,true);
 PERFORM dation_private.require_workflow_responsibility(target_workspace_id,target_case_id,target_node_id,'configure');
 IF target_node_id='logistics_scheduling' AND NOT EXISTS(SELECT 1 FROM decision_runs
  WHERE workspace_id=target_workspace_id AND decision_case_id=target_case_id AND node_id='logistics_assignment'
   AND approved_at IS NOT NULL AND superseded_at IS NULL) THEN
  RAISE EXCEPTION 'Aprobá la decisión anterior antes de configurar.' USING ERRCODE='P0001'; END IF;
 RETURN jsonb_build_object('case_id',target_case_id,'node_id',target_node_id,'ready',true);
END; $function$

CREATE OR REPLACE FUNCTION public.platform_workflow_responsibilities(target_workspace_id uuid, actor_user_id uuid, target_case_id uuid, operation text DEFAULT 'read'::text, target_stage_key text DEFAULT NULL::text, expected_updated_at timestamp with time zone DEFAULT NULL::timestamp with time zone, new_owner_user_id uuid DEFAULT NULL::uuid, new_approver_user_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE role_name text; c decision_cases; stage dation_private.workflow_stage_assignments; result jsonb;
BEGIN
 IF operation IS NULL OR operation NOT IN('read','write') THEN RAISE EXCEPTION 'Invalid operation' USING ERRCODE='22023'; END IF;
 IF operation='write' THEN PERFORM 1 FROM workspaces WHERE id=target_workspace_id FOR UPDATE; END IF;
 role_name=dation_private.team_actor(target_workspace_id,actor_user_id,operation='write');
 SELECT * INTO c FROM decision_cases WHERE workspace_id=target_workspace_id AND id=target_case_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'Case not found' USING ERRCODE='P0002'; END IF;
 IF operation='write' THEN
  IF c.status='archived' THEN RAISE EXCEPTION 'Restore case before assigning' USING ERRCODE='22023'; END IF;
  IF target_stage_key IS NULL OR target_stage_key NOT IN('data_preparation','data_owner','logistics_assignment','logistics_scheduling') THEN RAISE EXCEPTION 'Invalid stage' USING ERRCODE='22023'; END IF;
  IF target_stage_key IN('data_preparation','data_owner') THEN
   target_stage_key='data_owner';
   IF new_approver_user_id IS NOT NULL THEN RAISE EXCEPTION 'Data is not a decision node' USING ERRCODE='22023'; END IF;
   SELECT * INTO stage FROM dation_private.workflow_stage_assignments WHERE workspace_id=target_workspace_id AND decision_case_id=target_case_id AND stage_key='data_owner' FOR UPDATE;
   IF stage.updated_at IS DISTINCT FROM expected_updated_at THEN RAISE EXCEPTION 'Assignment changed' USING ERRCODE='55006'; END IF;
   IF new_owner_user_id IS DISTINCT FROM stage.owner_user_id THEN
    IF new_owner_user_id IS NOT NULL AND NOT dation_private.responsibility_eligible(target_workspace_id,new_owner_user_id,'data_owner') THEN RAISE EXCEPTION 'Assignee responsibility is not eligible' USING ERRCODE='22023'; END IF;
    INSERT INTO dation_private.workflow_stage_assignments VALUES(target_workspace_id,target_case_id,'data_owner',new_owner_user_id,actor_user_id,clock_timestamp())
     ON CONFLICT(workspace_id,decision_case_id,stage_key) DO UPDATE SET owner_user_id=excluded.owner_user_id,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
    INSERT INTO audit_events(workspace_id,actor_user_id,event_type,object_type,object_id,decision_case_id,metadata_json)
     VALUES(target_workspace_id,actor_user_id,'stage.responsible_changed','decision_case',target_case_id,target_case_id,
      jsonb_build_object('stage_key','data_owner','previous_user_id',stage.owner_user_id,'new_user_id',new_owner_user_id));
   END IF;
  ELSE
   PERFORM public.platform_assign_decision(target_workspace_id,actor_user_id,target_case_id,target_stage_key,expected_updated_at,new_owner_user_id,new_approver_user_id);
  END IF;
 END IF;
 WITH stages AS (
  SELECT 'data_owner' key,a.owner_user_id,a.updated_at FROM (SELECT 1) x LEFT JOIN dation_private.workflow_stage_assignments a
   ON a.workspace_id=target_workspace_id AND a.decision_case_id=target_case_id AND a.stage_key='data_owner'
  UNION ALL SELECT n.key,a.owner_user_id,a.updated_at FROM (VALUES('logistics_assignment'),('logistics_scheduling')) n(key)
   LEFT JOIN decision_assignments a ON a.workspace_id=target_workspace_id AND a.decision_case_id=target_case_id AND a.node_id=n.key)
 SELECT jsonb_object_agg(key,jsonb_build_object('owner',dation_private.team_person(target_workspace_id,owner_user_id),'updated_at',updated_at,
  'approver',CASE WHEN key='data_owner' THEN NULL ELSE dation_private.team_person(target_workspace_id,owner_user_id) END,
  'approver_eligible',key<>'data_owner' AND dation_private.responsibility_eligible(target_workspace_id,owner_user_id,'decision_owner'),
  'owner_eligible',dation_private.responsibility_eligible(target_workspace_id,owner_user_id,CASE WHEN key='data_owner' THEN 'data_owner' ELSE 'decision_owner' END),
  'can_execute',role_name IN('admin','operator') AND (role_name='admin' OR owner_user_id=actor_user_id),
  'can_approve',role_name IN('admin','operator') AND (role_name='admin' OR owner_user_id=actor_user_id))) INTO result FROM stages;
 result=jsonb_set(result,'{data_preparation}',result->'data_owner');
 RETURN jsonb_build_object('case_id',target_case_id,'stages',result,'can_assign',role_name='admin' AND c.status<>'archived',
  'can_prepare',role_name<>'viewer','gates_enforced',(SELECT workflow_gates_enabled FROM dation_private.platform_release WHERE singleton),
  'attributes_applied',c.attributes_applied_at IS NOT NULL,'policy_version',c.workflow_policy_version);
END; $function$

CREATE OR REPLACE FUNCTION public.protect_comparative_analysis()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'dation_private', 'public', 'pg_temp'
AS $function$
BEGIN
 IF NEW.id IS DISTINCT FROM OLD.id OR NEW.base_run_id IS DISTINCT FROM OLD.base_run_id OR
    NEW.base_result_fingerprint IS DISTINCT FROM OLD.base_result_fingerprint OR
    (NEW.request_json-'_observability') IS DISTINCT FROM (OLD.request_json-'_observability') THEN
  RAISE EXCEPTION 'Comparative identity is immutable' USING ERRCODE='22023';
 END IF;
 IF OLD.status='completed' AND NEW IS DISTINCT FROM OLD THEN
  RAISE EXCEPTION 'Completed comparative evidence is immutable' USING ERRCODE='22023';
 END IF;
 IF NEW.generation IS DISTINCT FROM OLD.generation AND NOT
    (OLD.status='error' AND NEW.status='queued' AND NEW.generation=OLD.generation+1) THEN
  RAISE EXCEPTION 'Invalid comparative retry' USING ERRCODE='22023';
 END IF;
 RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION public.protect_persistence_identity()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'dation_private', 'public', 'pg_temp'
AS $function$
BEGIN
 IF TG_TABLE_NAME='datasets' THEN
   IF ROW(NEW.id,NEW.created_at,NEW.storage_bucket,NEW.storage_path,NEW.sha256,NEW.size_bytes,NEW.original_filename,NEW.dataset_type)
      IS DISTINCT FROM ROW(OLD.id,OLD.created_at,OLD.storage_bucket,OLD.storage_path,OLD.sha256,OLD.size_bytes,OLD.original_filename,OLD.dataset_type) THEN
     RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='La identidad del archivo persistido es inmutable';
   END IF;
 ELSIF TG_TABLE_NAME='decision_cases' THEN
   IF ROW(NEW.id,NEW.created_at,NEW.domain,NEW.orders_dataset_id,NEW.fleet_dataset_id,NEW.input_signature)
      IS DISTINCT FROM ROW(OLD.id,OLD.created_at,OLD.domain,OLD.orders_dataset_id,OLD.fleet_dataset_id,OLD.input_signature) THEN
     RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='El Data Pack del Decision Case es inmutable';
   END IF;
 ELSE
   IF ROW(NEW.id,NEW.created_at,NEW.dataset_id,NEW.orders_dataset_id,NEW.fleet_dataset_id,NEW.engine_name,NEW.engine_version,NEW.schema_version)
      IS DISTINCT FROM ROW(OLD.id,OLD.created_at,OLD.dataset_id,OLD.orders_dataset_id,OLD.fleet_dataset_id,OLD.engine_name,OLD.engine_version,OLD.schema_version)
      OR (NEW.configuration_json #- '{decision_case,status}' #- '{decision_case,approved_at}')
        IS DISTINCT FROM (OLD.configuration_json #- '{decision_case,status}' #- '{decision_case,approved_at}') THEN
     RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='La identidad y configuración de la corrida son inmutables';
   END IF;
   IF OLD.status IN ('completed','error') AND (
     ROW(NEW.status,NEW.started_at,NEW.finished_at,NEW.duration_ms,NEW.input_fingerprint,NEW.result_fingerprint,NEW.summary_json,NEW.error_message)
       IS DISTINCT FROM ROW(OLD.status,OLD.started_at,OLD.finished_at,OLD.duration_ms,OLD.input_fingerprint,OLD.result_fingerprint,OLD.summary_json,OLD.error_message)
     OR (NEW.result_json #- '{decision_case,status}' #- '{decision_case,approved_at}')
       IS DISTINCT FROM (OLD.result_json #- '{decision_case,status}' #- '{decision_case,approved_at}')) THEN
     RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='El resultado terminal de la corrida es inmutable';
   END IF;
   IF OLD.approved_at IS NOT NULL AND ROW(NEW.approved_at,NEW.approved_by) IS DISTINCT FROM ROW(OLD.approved_at,OLD.approved_by)
      OR OLD.superseded_at IS NOT NULL AND ROW(NEW.superseded_at,NEW.superseded_by_run_id) IS DISTINCT FROM ROW(OLD.superseded_at,OLD.superseded_by_run_id) THEN
     RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='Una aprobación histórica no puede reactivarse ni reescribirse';
   END IF;
 END IF;
 RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.report_dispatch_worker(target_worker_id uuid, worker_revision text, is_ready boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'dation_private', 'public', 'pg_temp'
AS $function$
BEGIN
 IF target_worker_id IS NULL OR worker_revision IS NULL OR is_ready IS NULL THEN
  RAISE EXCEPTION 'Invalid worker report' USING ERRCODE='22023';
 END IF;
 INSERT INTO dispatch_worker_instances VALUES(target_worker_id,worker_revision,clock_timestamp(),is_ready)
 ON CONFLICT(worker_id) DO UPDATE SET revision=excluded.revision,seen_at=excluded.seen_at,ready=excluded.ready;
 DELETE FROM dispatch_worker_instances WHERE seen_at < clock_timestamp()-interval '24 hours';
 RETURN true;
END; $function$

CREATE OR REPLACE FUNCTION public.validate_current_run_admission()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'dation_private', 'public', 'pg_temp'
AS $function$
DECLARE source public.decision_runs%rowtype;
BEGIN
 IF NEW.decision_case_id IS NULL THEN RETURN NEW; END IF;
 PERFORM 1 FROM public.decision_cases WHERE id=NEW.decision_case_id FOR UPDATE;
 IF NEW.upstream_run_id IS NOT NULL THEN
   SELECT * INTO source FROM public.decision_runs WHERE id=NEW.upstream_run_id;
   IF NOT FOUND OR source.status<>'completed' OR source.approved_at IS NULL OR source.superseded_at IS NOT NULL THEN
     RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='La corrida upstream ya no es la decisión aprobada vigente';
   END IF;
   IF source.upstream_run_id IS NOT NULL AND NOT EXISTS (
     SELECT 1 FROM public.decision_runs r WHERE r.id=source.upstream_run_id
     AND r.decision_case_id=NEW.decision_case_id AND r.status='completed' AND r.approved_at IS NOT NULL AND r.superseded_at IS NULL) THEN
     RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='La cadena de decisiones upstream está desactualizada';
   END IF;
 END IF;
 RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_decision_run_history()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'dation_private', 'public', 'pg_temp'
AS $function$
declare
    case_orders uuid;
    case_fleet uuid;
    source_case uuid;
    source_node text;
    source_approved_at timestamptz;
    expected_source_node text;
begin
    if tg_op = 'UPDATE' then
        if new.decision_case_id is distinct from old.decision_case_id
           or new.node_id is distinct from old.node_id
           or new.upstream_run_id is distinct from old.upstream_run_id then
            raise exception 'La identidad y el lineage de una Decision Run son inmutables';
        end if;
    end if;

    if new.decision_case_id is null then
        if new.node_id is not null or new.upstream_run_id is not null then
            raise exception 'Una corrida sin Decision Case no puede declarar nodo o dependencia';
        end if;
        return new;
    end if;

    select orders_dataset_id, fleet_dataset_id
      into case_orders, case_fleet
      from public.decision_cases
     where id = new.decision_case_id;

    if not found then
        raise exception 'El Decision Case de la corrida no existe';
    end if;

    if new.orders_dataset_id is distinct from case_orders
       or new.fleet_dataset_id is distinct from case_fleet then
        raise exception 'La Decision Run usa un Data Pack distinto al Decision Case';
    end if;

    expected_source_node := case new.node_id
        when 'logistics_assignment' then null
        when 'logistics_scheduling' then 'logistics_assignment'
        when 'logistics_final_assignment' then 'logistics_scheduling'
        else null
    end;

    if expected_source_node is null then
        if new.upstream_run_id is not null then
            raise exception 'Assignment no admite una corrida upstream';
        end if;
    else
        if new.upstream_run_id is null then
            raise exception 'La decisión requiere una corrida upstream aprobada';
        end if;

        select decision_case_id, node_id, approved_at
          into source_case, source_node, source_approved_at
          from public.decision_runs
         where id = new.upstream_run_id;

        if not found
           or source_case is distinct from new.decision_case_id
           or source_node is distinct from expected_source_node
           or source_approved_at is null then
            raise exception 'El lineage de la Decision Run no corresponde al Decision Case';
        end if;
    end if;

    if new.approved_at is not null and new.status <> 'completed' then
        raise exception 'Sólo una corrida completada puede aprobarse';
    end if;

    return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.validate_dispatch_run()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'dation_private', 'public', 'pg_temp'
AS $function$
begin
  if new.schema_version in ('dispatch_v1', 'dispatch_v2') then
    if new.orders_dataset_id is null
       or new.fleet_dataset_id is null
       or new.dataset_id <> new.orders_dataset_id then
      raise exception 'Una corrida dispatch requiere órdenes y flota';
    end if;

    if not exists (
      select 1
      from public.datasets
      where id = new.orders_dataset_id
        and dataset_type = 'orders'
    )
    or not exists (
      select 1
      from public.datasets
      where id = new.fleet_dataset_id
        and dataset_type = 'fleet'
    ) then
      raise exception 'Tipos de datasets incorrectos';
    end if;

    if new.status = 'completed'
       and new.result_json is not null
       and coalesce(new.result_json ->> 'schema_version', '') <> new.schema_version then
      raise exception 'La versión del resultado no coincide con la corrida';
    end if;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.validate_interpretation_source()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'dation_private', 'public', 'pg_temp'
AS $function$
DECLARE actual uuid;
BEGIN
 IF NEW.analysis_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM decision_comparative_analyses WHERE id=NEW.analysis_id AND base_run_id=NEW.run_id AND status='completed') THEN
  RAISE EXCEPTION 'Comparative evidence unavailable' USING ERRCODE='22023';
 END IF;
 IF NEW.chat_turn_id IS NOT NULL THEN SELECT run_id INTO actual FROM decision_chat_turns WHERE turn_id=NEW.chat_turn_id;
 ELSE SELECT run_id INTO actual FROM decision_explanations WHERE id=NEW.explanation_id; END IF;
 IF actual IS DISTINCT FROM NEW.run_id THEN RAISE EXCEPTION 'Interpreter source mismatch' USING ERRCODE='22023'; END IF;
 RETURN NEW;
END; $function$
